select ac_cargar_unidad($ac${"slug":"energia-1","rama":"energia","orden":1,"nivel":1,"titulo_es":"Qué es la energía","bajada_es":"La energía no se ve, pero mueve todo. Sus formas, sus transformaciones, sus fuentes y por qué pesa tanto en el clima.","objetivos_es":["Reconocer las formas de la energía en situaciones cotidianas","Explicar por qué toda transformación \"pierde\" una parte como calor","Calcular la eficiencia de un aparato o una máquina","Distinguir fuentes primarias, fuentes secundarias y vectores","Relacionar el uso de energía fósil con las emisiones de CO₂"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":1,"fuentes":["iea-energia","owid-energia","owid-co2","ipcc-ar6-syr","iea-eficiencia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-1.s1","orden":1,"tipo":"leccion","titulo_es":"La energía que mueve todo","bajada_es":"Luz, calor, movimiento, electricidad: la misma cosa en distintas formas.","minutos":11,"pasos":[{"slug":"energia-1.s1.p1","orden":1,"grupo":"energia-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una definición útil","cuerpo":["La energía es la capacidad de producir un cambio: mover algo, calentarlo, iluminarlo, hacerlo crecer. No se ve directamente; se ven sus efectos.","Aparece en muchas formas: química (guardada en la comida, la nafta o el gas), eléctrica, térmica (el calor), cinética (la del movimiento), luminosa, y potencial (la que tiene el agua en lo alto de una represa, lista para caer)."]},"solucion":{}},{"slug":"energia-1.s1.p2","orden":2,"grupo":"energia-1.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada ejemplo con la forma de energía que tiene.","izquierda":[{"id":"a1","texto":"Un sándwich antes de comerlo"},{"id":"a2","texto":"Una pelota que rueda"},{"id":"a3","texto":"El agua detrás de una represa"},{"id":"a4","texto":"Una pava caliente"}],"derecha":[{"id":"b1","texto":"Química"},{"id":"b2","texto":"Cinética"},{"id":"b3","texto":"Potencial"},{"id":"b4","texto":"Térmica"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro formas distintas de la misma cosa. Lo interesante es cómo pasan de una a otra."}},{"slug":"energia-1.s1.p3","orden":3,"grupo":"energia-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nada se crea, todo se transforma","cuerpo":["La energía no aparece de la nada ni desaparece: se transforma de una forma en otra. Es una de las leyes más firmes de la física. En el tronco lo viste con la cadena del sol a las plantas y de las plantas a los animales.","Cuando decimos que \"gastamos\" energía, en realidad la transformamos en formas que ya no nos sirven, casi siempre calor que se dispersa en el ambiente."]},"solucion":{}},{"slug":"energia-1.s1.p4","orden":4,"grupo":"energia-1.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Seguí la energía desde el sol hasta tu pierna cuando pedaleás.","items":[{"id":"i1","texto":"El sol emite luz"},{"id":"i2","texto":"Una planta de trigo la guarda como energía química"},{"id":"i3","texto":"Comés pan hecho con ese trigo"},{"id":"i4","texto":"Tus músculos transforman esa energía en movimiento"},{"id":"i5","texto":"La bicicleta avanza"},{"id":"i6","texto":"El pan le devuelve la luz al sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Casi toda la energía que usamos empezó siendo luz del sol, incluso la del petróleo, que es sol guardado hace millones de años."}},{"slug":"energia-1.s1.p5","orden":5,"grupo":"energia-1.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuando una lámpara se apaga, la energía que usó desaparece.","razones":[{"id":"r1","texto":"Porque se transformó en luz y calor que se dispersaron"},{"id":"r2","texto":"Porque vuelve a la red eléctrica al apagar"},{"id":"r3","texto":"Porque queda guardada en la lámpara"}]},"solucion":{"valor":false,"explicacion":"No desaparece: se transformó en luz y calor, que se dispersaron en la habitación. La energía se conserva, pero se vuelve menos útil.","clave":["r1"]}},{"slug":"energia-1.s1.p6","orden":6,"grupo":"energia-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transformaciones de todos los días","cuerpo":["Un celular transforma energía eléctrica en química (al cargar la batería) y después en luz, sonido y calor. Un auto transforma la energía química de la nafta en movimiento y mucho calor. Una central hidroeléctrica transforma la energía potencial del agua en movimiento de una turbina y después en electricidad."]},"solucion":{}},{"slug":"energia-1.s1.p7","orden":7,"grupo":"energia-1.s1.p7","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las transformaciones en una central hidroeléctrica.","items":[{"id":"i1","texto":"El agua está acumulada en lo alto del embalse"},{"id":"i2","texto":"El agua cae por un conducto"},{"id":"i3","texto":"Hace girar una turbina"},{"id":"i4","texto":"La turbina mueve un generador"},{"id":"i5","texto":"Sale electricidad hacia la red"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Potencial, cinética, mecánica, eléctrica. Cada paso es una transformación."}},{"slug":"energia-1.s1.p8","orden":8,"grupo":"energia-1.s1.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué transformación principal hace cada aparato?","grupos":[{"id":"g1","nombre":"Eléctrica a movimiento"},{"id":"g2","nombre":"Eléctrica a calor"},{"id":"g3","nombre":"Química a calor"}],"items":[{"id":"i1","texto":"Un ventilador"},{"id":"i2","texto":"Una pava eléctrica"},{"id":"i3","texto":"Una hornalla de gas"},{"id":"i4","texto":"Una licuadora"},{"id":"i5","texto":"Una estufa de cuarzo"},{"id":"i6","texto":"Una estufa a leña"},{"id":"i7","texto":"Un lavarropas girando"},{"id":"i8","texto":"Una plancha"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Casi todos los aparatos hacen una transformación principal, y además producen algo de calor que no buscamos."}},{"slug":"energia-1.s1.p9","orden":9,"grupo":"energia-1.s1.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas cosas tienen energía química guardada? Marcá todas.","opciones":[{"id":"o1","texto":"La nafta de un tanque"},{"id":"o2","texto":"Una batería cargada"},{"id":"o3","texto":"Un leño seco"},{"id":"o4","texto":"Una manzana"},{"id":"o5","texto":"Una ráfaga de viento"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La energía química está en los enlaces de las moléculas. El viento tiene energía de movimiento, no química."}},{"slug":"energia-1.s1.p10","orden":10,"grupo":"energia-1.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un auto frena y los discos de freno se calientan. ¿Qué pasó con la energía del movimiento?","opciones":[{"id":"o1","texto":"Se transformó en calor por el roce"},{"id":"o2","texto":"Volvió al tanque como nafta sin quemar"},{"id":"o3","texto":"Desapareció al frenar el auto"},{"id":"o4","texto":"Se guardó en las ruedas para arrancar después"}]},"solucion":{"clave":["o1"],"explicacion":"Los autos eléctricos pueden recuperar una parte al frenar (freno regenerativo), pero en un freno común todo termina como calor.","por_opcion":{"o3":"La energía no desaparece: se transforma. Los frenos calientes son la prueba."}}},{"slug":"energia-1.s1.p11","orden":11,"grupo":"energia-1.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía no se crea ni se {{0}}: se {{1}}, y casi siempre una parte termina como {{2}}.","banco":[{"id":"w1","texto":"destruye"},{"id":"w2","texto":"transforma"},{"id":"w3","texto":"calor"},{"id":"w4","texto":"acumula"},{"id":"w5","texto":"multiplica"},{"id":"w6","texto":"luz"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres palabras que explican por qué hablar de \"gastar energía\" es una forma de decir."}},{"slug":"energia-1.s1.p12","orden":12,"grupo":"energia-1.s1.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación de un estudiante y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La energía de la nafta es energía química."},{"id":"s2","texto":"Cuando el auto anda, esa energía se destruye."},{"id":"s3","texto":"Por eso el motor se calienta tanto."},{"id":"s4","texto":"Un auto eléctrico no transforma energía: la usa tal cual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Toda máquina es una transformadora de energía. La pregunta útil es cuánta sale en la forma que queremos.","por_opcion":{"s2":"No se destruye: se transforma en movimiento y, sobre todo, en calor.","s4":"También transforma: de química (batería) a eléctrica y a movimiento."}}},{"slug":"energia-1.s1.p13","orden":13,"grupo":"energia-1.s1.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas cosas por cuánta energía tienen, de más a menos (valores aproximados).","items":[{"id":"i1","texto":"Un litro de nafta"},{"id":"i2","texto":"Un día de comida de una persona adulta"},{"id":"i3","texto":"Una batería de celular cargada"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Un litro de nafta tiene casi cuatro días de comida de una persona. Por eso los combustibles fósiles fueron tan poderosos, y tan difíciles de reemplazar.","valores":{"i1":"≈ 9 kWh","i2":"≈ 2,3 kWh","i3":"≈ 0,015 kWh"}}}]},{"slug":"energia-1.s2","orden":2,"tipo":"leccion","titulo_es":"Transformar siempre cuesta","bajada_es":"Por qué ninguna máquina aprovecha toda la energía, y cómo se mide cuánto aprovecha: la eficiencia.","minutos":13,"pasos":[{"slug":"energia-1.s2.p1","orden":1,"grupo":"energia-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La parte que se escapa","cuerpo":["En cada transformación, una parte de la energía termina en una forma que no buscábamos, casi siempre calor. Una lamparita vieja, incandescente, convierte solo alrededor del 5 % de la electricidad en luz: el resto es calor. Por eso quemaba al tocarla.","La eficiencia es la fracción de la energía que sale en la forma útil. Se calcula como energía útil dividida energía que entra, y se expresa en porcentaje."],"destacado":{"valor":"útil ÷ entra","texto":"es la cuenta de la eficiencia. Multiplicada por 100, da el porcentaje."}},"solucion":{}},{"slug":"energia-1.s2.p2","orden":2,"grupo":"energia-1.s2.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"La eficiencia de un motor","planteo":"Un motor de auto recibe 100 unidades de energía de la nafta y entrega 25 como movimiento de las ruedas.","pasos":["Energía útil: 25. Energía que entra: 100.","Eficiencia: 25 ÷ 100 = 0,25, o sea 25 %.","Las otras 75 unidades salen como calor por el escape y el radiador."],"resultado":"Un motor de nafta aprovecha alrededor de un cuarto de la energía. Un motor eléctrico, en cambio, supera el 85 %."},"solucion":{}},{"slug":"energia-1.s2.p3","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 200 unidades de energía y entrega 50 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"50 ÷ 200 = 0,25, que es 25 %. El resto, 150 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p3.v2","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 500 unidades de energía y entrega 175 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"175 ÷ 500 = 0,35, que es 35 %. El resto, 325 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p3.v3","orden":3,"grupo":"energia-1.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una máquina recibe 80 unidades de energía y entrega 72 en la forma útil. ¿Cuál es su eficiencia?","unidad":"%","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"72 ÷ 80 = 0,9, que es 90 %. El resto, 8 unidades, se fue como calor u otra forma no buscada."}},{"slug":"energia-1.s2.p4","orden":4,"grupo":"energia-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lámparas: el mismo trabajo con menos energía","cuerpo":["Una lámpara LED da la misma luz que una incandescente de 60 W usando alrededor de 8 a 10 W. No es que \"ahorre luz\": desperdicia mucho menos en calor.","La misma idea sirve para cualquier aparato: cuando un aparato es más eficiente, hace el mismo trabajo con menos energía. Es la base de la etiqueta de eficiencia que vas a ver en la próxima unidad."]},"solucion":{}},{"slug":"energia-1.s2.p5","orden":5,"grupo":"energia-1.s2.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas máquinas por su eficiencia típica, de más a menos.","items":[{"id":"i1","texto":"Motor eléctrico"},{"id":"i2","texto":"Central térmica de ciclo combinado"},{"id":"i3","texto":"Motor de auto a nafta"},{"id":"i4","texto":"Lamparita incandescente (como fuente de luz)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las máquinas que queman algo pierden mucho en calor. Las eléctricas pierden poco. Esa diferencia está en el centro de la transición energética.","valores":{"i1":"≈ 85-95 %","i2":"≈ 55-60 %","i3":"≈ 20-30 %","i4":"≈ 5 %"}}},{"slug":"energia-1.s2.p6","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 60 W se reemplaza por una LED de 9 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1,"explicacion":"Se ahorran 60 − 9 = 51 W de 60: 51 ÷ 60 × 100 ≈ 85 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p6.v2","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 100 W se reemplaza por una LED de 14 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":86,"tolerancia":1,"explicacion":"Se ahorran 100 − 14 = 86 W de 100: 86 ÷ 100 × 100 ≈ 86 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p6.v3","orden":6,"grupo":"energia-1.s2.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara incandescente de 40 W se reemplaza por una LED de 6 W que da la misma luz. ¿Qué porcentaje de energía se ahorra? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":85,"tolerancia":1,"explicacion":"Se ahorran 40 − 6 = 34 W de 40: 34 ÷ 40 × 100 ≈ 85 %. La misma luz con mucho menos calor."}},{"slug":"energia-1.s2.p7","orden":7,"grupo":"energia-1.s2.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una lamparita incandescente de 60 W da más luz que una LED de 60 W.","razones":[{"id":"r1","texto":"Porque la LED convierte en luz mucha más parte de la energía"},{"id":"r2","texto":"Porque los watts miden la luz que da la lámpara"},{"id":"r3","texto":"Porque las dos tienen la misma eficiencia"}]},"solucion":{"valor":false,"explicacion":"Es al revés: con 60 W, una LED da muchísima más luz, porque convierte en luz una parte mucho mayor de la energía. Los watts miden energía por segundo, no luz.","clave":["r1"]}},{"slug":"energia-1.s2.p8","orden":8,"grupo":"energia-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pérdidas en cadena","cuerpo":["Cuando la energía pasa por varias transformaciones, las pérdidas se multiplican. Si una central aprovecha el 40 %, la red pierde un 10 % en el camino y la lamparita aprovecha el 5 %, de 100 unidades de gas quemado solo llegan como luz 100 × 0,4 × 0,9 × 0,05 ≈ 1,8 unidades.","Por eso mejorar la eficiencia en el último eslabón, el aparato, ahorra mucho más de lo que parece: cada unidad que no pide el aparato se ahorra en toda la cadena."]},"solucion":{}},{"slug":"energia-1.s2.p9","orden":9,"grupo":"energia-1.s2.p9","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"De gas a luz","planteo":"Una central aprovecha el 40 % del gas, la red pierde el 10 % y una lámpara LED convierte el 40 % de la electricidad en luz.","pasos":["Salen de la central: 100 × 0,40 = 40.","Llegan a casa: 40 × 0,90 = 36.","Salen como luz: 36 × 0,40 = 14,4."],"resultado":"Con LED llegan como luz unas 14 de cada 100 unidades de gas; con incandescente, menos de 2. La misma cadena, con un eslabón mejor."},"solucion":{}},{"slug":"energia-1.s2.p10","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 40 % del combustible, a casa llega el 90 % de su electricidad y el aparato aprovecha el 80 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":28.8,"tolerancia":0.2,"explicacion":"100 × 0,4 × 0,9 × 0,8 ≈ 28,8. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p10.v2","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 50 % del combustible, a casa llega el 90 % de su electricidad y el aparato aprovecha el 90 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":40.5,"tolerancia":0.2,"explicacion":"100 × 0,5 × 0,9 × 0,9 ≈ 40,5. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p10.v3","orden":10,"grupo":"energia-1.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central aprovecha el 35 % del combustible, a casa llega el 85 % de su electricidad y el aparato aprovecha el 60 %. De 100 unidades de combustible, ¿cuántas terminan como energía útil? Redondeá a un decimal.","unidad":"unidades","decimales":1},"solucion":{"valor":17.8,"tolerancia":0.2,"explicacion":"100 × 0,35 × 0,85 × 0,6 ≈ 17,8. Las pérdidas se multiplican eslabón por eslabón."}},{"slug":"energia-1.s2.p11","orden":11,"grupo":"energia-1.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué cambiar una lámpara ahorra gas en una central.","items":[{"id":"i1","texto":"Se cambia una lámpara incandescente por una LED"},{"id":"i2","texto":"La casa pide menos electricidad"},{"id":"i3","texto":"La red transporta menos energía"},{"id":"i4","texto":"La central quema menos gas"},{"id":"i5","texto":"Se emite menos CO₂"},{"id":"i6","texto":"La LED produce gas en la casa"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ahorro viaja para atrás por la cadena. Por eso se dice que la energía más limpia es la que no se usa."}},{"slug":"energia-1.s2.p12","orden":12,"grupo":"energia-1.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los motores de auto a nafta se calientan tanto?","opciones":[{"id":"o1","texto":"Porque la mayor parte de la energía termina como calor"},{"id":"o2","texto":"Porque el sol calienta el capó durante el viaje"},{"id":"o3","texto":"Porque la nafta ya viene caliente de la estación"},{"id":"o4","texto":"Porque el motor necesita calor para mover las ruedas"}]},"solucion":{"clave":["o1"],"explicacion":"Tres cuartos de la energía de la nafta se van en calor. El radiador existe para sacarlo.","por_opcion":{"o3":"La nafta está a temperatura ambiente: el calor sale de la combustión."}}},{"slug":"energia-1.s2.p13","orden":13,"grupo":"energia-1.s2.p13","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales indican que un aparato es poco eficiente? Marcá todas.","opciones":[{"id":"o1","texto":"Se calienta mucho sin que su función sea calentar"},{"id":"o2","texto":"Hace el mismo trabajo que otro con más watts"},{"id":"o3","texto":"Hace mucho ruido o vibra al funcionar"},{"id":"o4","texto":"Tiene una etiqueta de eficiencia clase A"},{"id":"o5","texto":"Es más chico que otro modelo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El calor, el ruido y la vibración son energía que se va sin hacer el trabajo buscado."}},{"slug":"energia-1.s2.p14","orden":14,"grupo":"energia-1.s2.p14","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es energía útil o energía perdida?","grupos":[{"id":"g1","nombre":"Útil"},{"id":"g2","nombre":"Perdida"}],"items":[{"id":"i1","texto":"La luz de una lámpara"},{"id":"i2","texto":"El calor de una lamparita incandescente"},{"id":"i3","texto":"El giro del tambor del lavarropas"},{"id":"i4","texto":"El ruido de un motor"},{"id":"i5","texto":"El calor de una estufa en invierno"},{"id":"i6","texto":"El calor del cargador del celular"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Que algo sea útil depende de lo que buscamos: el calor de la estufa es el objetivo; el de la lamparita, un desperdicio."}},{"slug":"energia-1.s2.p15","orden":15,"grupo":"energia-1.s2.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La eficiencia es la energía {{0}} dividida la energía que {{1}}; en una cadena, las pérdidas se {{2}}.","banco":[{"id":"w1","texto":"útil"},{"id":"w2","texto":"entra"},{"id":"w3","texto":"multiplican"},{"id":"w4","texto":"total"},{"id":"w5","texto":"sale"},{"id":"w6","texto":"restan"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta y la regla de la cadena, juntas."}}]},{"slug":"energia-1.s3","orden":3,"tipo":"leccion","titulo_es":"De dónde sale la energía","bajada_es":"Fuentes primarias, fuentes secundarias y vectores: el mapa para entender cualquier discusión sobre energía.","minutos":11,"pasos":[{"slug":"energia-1.s3.p1","orden":1,"grupo":"energia-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Fuentes primarias","cuerpo":["Una fuente primaria es la energía tal como está en la naturaleza: petróleo, gas natural, carbón, uranio, sol, viento, agua de los ríos, biomasa (leña, residuos vegetales) y calor de la Tierra (geotermia).","Algunas son fósiles: se formaron durante millones de años con restos de seres vivos y, al quemarse, emiten CO₂ que estaba guardado bajo tierra. Otras son renovables: se reponen a escala humana."]},"solucion":{}},{"slug":"energia-1.s3.p2","orden":2,"grupo":"energia-1.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas fuentes primarias.","grupos":[{"id":"g1","nombre":"Fósiles"},{"id":"g2","nombre":"Renovables"},{"id":"g3","nombre":"Ni fósil ni renovable"}],"items":[{"id":"i1","texto":"Petróleo"},{"id":"i2","texto":"Sol"},{"id":"i3","texto":"Uranio"},{"id":"i4","texto":"Gas natural"},{"id":"i5","texto":"Viento"},{"id":"i6","texto":"Carbón"},{"id":"i7","texto":"Agua de los ríos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g1","i7":"g2"},"explicacion":"El uranio no es fósil (no viene de seres vivos) ni renovable (es un mineral que se agota), pero no emite CO₂ al generar electricidad."}},{"slug":"energia-1.s3.p3","orden":3,"grupo":"energia-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Secundarias y vectores","cuerpo":["Las fuentes secundarias se obtienen transformando las primarias: la nafta y el gasoil se hacen refinando petróleo; la electricidad se genera con gas, agua, viento, sol o uranio.","La electricidad es un vector: no es una fuente, sino una forma cómoda de transportar energía. Por eso la pregunta \"¿es limpio un auto eléctrico?\" depende de con qué se generó esa electricidad."]},"solucion":{}},{"slug":"energia-1.s3.p4","orden":4,"grupo":"energia-1.s3.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada energía secundaria con la primaria de la que suele salir.","izquierda":[{"id":"a1","texto":"Nafta"},{"id":"a2","texto":"Carbón vegetal"},{"id":"a3","texto":"Electricidad de Yacyretá"},{"id":"a4","texto":"Electricidad de un parque eólico"}],"derecha":[{"id":"b1","texto":"Petróleo"},{"id":"b2","texto":"Leña"},{"id":"b3","texto":"Agua del río Paraná"},{"id":"b4","texto":"Viento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada secundaria tiene detrás una primaria. La electricidad puede venir de cualquiera."}},{"slug":"energia-1.s3.p5","orden":5,"grupo":"energia-1.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad es una fuente de energía, como el petróleo o el viento.","razones":[{"id":"r1","texto":"Porque es un vector que transporta energía de otra fuente"},{"id":"r2","texto":"Porque la electricidad se extrae de minas"},{"id":"r3","texto":"Porque la electricidad no tiene relación con ninguna fuente"}]},"solucion":{"valor":false,"explicacion":"La electricidad es un vector: transporta energía que viene de una fuente primaria. Su impacto depende de esa fuente.","clave":["r1"]}},{"slug":"energia-1.s3.p6","orden":6,"grupo":"energia-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El mundo y Argentina","cuerpo":["A nivel mundial, alrededor de 8 de cada 10 unidades de energía primaria vienen todavía de combustibles fósiles. En Argentina la proporción es parecida o incluso mayor, con un peso muy alto del gas natural: se usa para generar electricidad, calefaccionar casas, cocinar y en la industria.","La energía primaria no es solo electricidad: también es el combustible del transporte, el gas de las casas y el calor de las industrias. La electricidad es una parte, importante pero no la única."],"datos":{"tipo":"barras","titulo":"Energía primaria mundial por fuente (aproximado)","unidad":"% del total","filas":[{"etiqueta":"Petróleo","valor":32},{"etiqueta":"Carbón","valor":26},{"etiqueta":"Gas natural","valor":23},{"etiqueta":"Hidro","valor":6},{"etiqueta":"Nuclear","valor":4},{"etiqueta":"Eólica, solar y otras renovables","valor":9}],"nota":"Valores redondeados de los últimos años; cambian año a año."}},"solucion":{}},{"slug":"energia-1.s3.p7","orden":7,"grupo":"energia-1.s3.p7","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la energía primaria del mundo viene de combustibles fósiles.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":80,"banda":"lineal","explicacion":"Alrededor del 80 %. Aunque las renovables crecen rápido, el mundo todavía funciona mayormente con petróleo, carbón y gas."}},{"slug":"energia-1.s3.p8","orden":8,"grupo":"energia-1.s3.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Para qué se usa el gas natural en Argentina? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Para generar electricidad en centrales térmicas"},{"id":"o2","texto":"Para calefaccionar casas y calentar agua"},{"id":"o3","texto":"Para cocinar"},{"id":"o4","texto":"Como combustible de algunos vehículos (GNC)"},{"id":"o5","texto":"Para producir la electricidad de las represas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El gas está en casi todo el sistema energético argentino. Las represas usan la fuerza del agua, no gas."}},{"slug":"energia-1.s3.p9","orden":9,"grupo":"energia-1.s3.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un auto eléctrico se carga en un país donde casi toda la electricidad sale del carbón. ¿Qué pasa con sus emisiones?","opciones":[{"id":"o1","texto":"Dependen del carbón que se quemó para generar esa electricidad"},{"id":"o2","texto":"Son cero, porque el auto no tiene caño de escape"},{"id":"o3","texto":"Son iguales a las de un auto a nafta en todos los casos"},{"id":"o4","texto":"Son mayores que las de cualquier auto a nafta"}]},"solucion":{"clave":["o1"],"explicacion":"El auto eléctrico traslada las emisiones del caño de escape a la central. Cuanto más limpia la red, mejor.","por_opcion":{"o3":"Depende de la red: en redes limpias el eléctrico emite mucho menos; en redes muy sucias, la ventaja se achica."}}},{"slug":"energia-1.s3.p10","orden":10,"grupo":"energia-1.s3.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la cadena del combustible de un colectivo diésel.","items":[{"id":"i1","texto":"Se extrae petróleo de un yacimiento"},{"id":"i2","texto":"Se transporta a una refinería"},{"id":"i3","texto":"Se refina y se obtiene gasoil"},{"id":"i4","texto":"Se distribuye a las estaciones de servicio"},{"id":"i5","texto":"El colectivo lo quema en su motor"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"De fuente primaria a secundaria y a uso final. Cada paso usa energía y tiene sus pérdidas."}},{"slug":"energia-1.s3.p11","orden":11,"grupo":"energia-1.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El petróleo y el gas son fuentes fósiles."},{"id":"s2","texto":"La electricidad es una fuente limpia porque no tiene humo."},{"id":"s3","texto":"El sol y el viento son renovables."},{"id":"s4","texto":"El uranio es un combustible fósil, como el carbón."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Fuente primaria, secundaria y vector: con esas tres ideas se desarman muchas confusiones.","por_opcion":{"s2":"La electricidad es un vector: es tan limpia como la fuente que la generó.","s4":"El uranio es un mineral, no se formó de restos de seres vivos."}}},{"slug":"energia-1.s3.p12","orden":12,"grupo":"energia-1.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El petróleo es una fuente {{0}}, la nafta es {{1}} y la electricidad es un {{2}}.","banco":[{"id":"w1","texto":"primaria"},{"id":"w2","texto":"secundaria"},{"id":"w3","texto":"vector"},{"id":"w4","texto":"renovable"},{"id":"w5","texto":"fósil"},{"id":"w6","texto":"residuo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El mapa de toda la energía, resumido en una sola línea."}},{"slug":"energia-1.s3.p13","orden":13,"grupo":"energia-1.s3.p13","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el sol de hace millones de años llega al tanque de un auto.","items":[{"id":"i1","texto":"Algas y plantas antiguas guardaron energía del sol"},{"id":"i2","texto":"Quedaron enterradas bajo capas de sedimentos"},{"id":"i3","texto":"Con presión, calor y millones de años se formó petróleo"},{"id":"i4","texto":"Se extrae y se refina en nafta"},{"id":"i5","texto":"El petróleo se forma en pocos años en las refinerías"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Quemar petróleo es liberar en segundos lo que la naturaleza tardó millones de años en guardar. Por eso no es renovable."}}]},{"slug":"energia-1.s4","orden":4,"tipo":"leccion","titulo_es":"Medir la energía","bajada_es":"Joules, calorías y kilowatt-hora: las unidades con que se mide la energía y cómo pasar de una a otra.","minutos":12,"pasos":[{"slug":"energia-1.s4.p1","orden":1,"grupo":"energia-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres unidades, una misma cosa","cuerpo":["La energía se mide en joules (J) en física, en calorías en la nutrición y en kilowatt-hora (kWh) en las facturas de luz. Son unidades distintas para la misma cosa, como litros y metros cúbicos para el agua.","Un kWh es la energía que usa un aparato de 1 kW durante 1 hora, como viste en el tronco. Equivale a 3,6 millones de joules (3,6 MJ). Una kilocaloría, la \"caloría\" de las etiquetas de comida, son unos 4.184 joules."],"destacado":{"valor":"1 kWh = 3,6 MJ","texto":"la equivalencia que conecta la factura de luz con la física."}},"solucion":{}},{"slug":"energia-1.s4.p2","orden":2,"grupo":"energia-1.s4.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada unidad con dónde se usa más.","izquierda":[{"id":"a1","texto":"Kilowatt-hora (kWh)"},{"id":"a2","texto":"Kilocaloría (kcal)"},{"id":"a3","texto":"Joule (J)"},{"id":"a4","texto":"Metro cúbico de gas (m³)"}],"derecha":[{"id":"b1","texto":"Factura de luz"},{"id":"b2","texto":"Etiqueta de un alimento"},{"id":"b3","texto":"Libros de física"},{"id":"b4","texto":"Factura de gas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El m³ de gas mide volumen, pero cada m³ de gas natural tiene unos 10 kWh de energía."}},{"slug":"energia-1.s4.p3","orden":3,"grupo":"energia-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Potencia contra energía, otra vez","cuerpo":["La potencia es el ritmo al que se usa la energía; se mide en watts (W) o kilowatts (kW). La energía es la cantidad total: potencia por tiempo. Una pava de 2.000 W prendida 3 minutos usa 2 kW × 0,05 h = 0,1 kWh.","Confundir las dos es el error más común. Un aparato de mucha potencia usado poco tiempo puede gastar menos energía que uno de poca potencia prendido todo el día."]},"solucion":{}},{"slug":"energia-1.s4.p4","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 2.000 W funciona 3 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.1,"tolerancia":0.01,"explicacion":"2 kW × 0,05 h = 0,1 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v2","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.500 W funciona 20 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.5,"tolerancia":0.01,"explicacion":"1,5 kW × 0,333 h = 0,5 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v3","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 800 W funciona 30 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":0.4,"tolerancia":0.01,"explicacion":"0,8 kW × 0,5 h = 0,4 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p4.v4","orden":4,"grupo":"energia-1.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 100 W funciona 600 minutos. ¿Cuántos kWh usa?","unidad":"kWh","decimales":2},"solucion":{"valor":1,"tolerancia":0.01,"explicacion":"0,1 kW × 10 h = 1 kWh. Potencia en kW por tiempo en horas."}},{"slug":"energia-1.s4.p5","orden":5,"grupo":"energia-1.s4.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"La energía de tu comida en kWh","planteo":"Una persona come 2.000 kcal por día. ¿Cuántos kWh son?","pasos":["2.000 kcal × 4.184 J = 8.368.000 J ≈ 8,4 MJ.","8,4 MJ ÷ 3,6 MJ por kWh ≈ 2,3 kWh."],"resultado":"Todo lo que comés en un día equivale a unos 2,3 kWh: menos que lo que usa una estufa eléctrica de 2.000 W en poco más de una hora."},"solucion":{}},{"slug":"energia-1.s4.p6","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 2.500 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":2.9,"tolerancia":0.1,"explicacion":"2.500 × 4.184 = 10.460.000 J; ÷ 3.600.000 ≈ 2,9 kWh."}},{"slug":"energia-1.s4.p6.v2","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 1.800 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"1.800 × 4.184 = 7.531.200 J; ÷ 3.600.000 ≈ 2,1 kWh."}},{"slug":"energia-1.s4.p6.v3","orden":6,"grupo":"energia-1.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona come 3.000 kcal por día. ¿Cuántos kWh son? Usá 1 kcal = 4.184 J y 1 kWh = 3,6 MJ. Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"3.000 × 4.184 = 12.552.000 J; ÷ 3.600.000 ≈ 3,5 kWh."}},{"slug":"energia-1.s4.p7","orden":7,"grupo":"energia-1.s4.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por energía, de más a menos.","items":[{"id":"i1","texto":"1 m³ de gas natural"},{"id":"i2","texto":"2.000 kcal de comida"},{"id":"i3","texto":"Una pava eléctrica de 2.000 W por 3 minutos"},{"id":"i4","texto":"Una LED de 9 W prendida 1 hora"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Con una misma unidad, cosas muy distintas se vuelven comparables. Es la herramienta de los órdenes de magnitud del tronco.","valores":{"i1":"≈ 10 kWh","i2":"≈ 2,3 kWh","i3":"0,1 kWh","i4":"0,009 kWh"}}},{"slug":"energia-1.s4.p8","orden":8,"grupo":"energia-1.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una estufa de 2.000 W usa siempre más energía que una heladera de 150 W.","razones":[{"id":"r1","texto":"Porque la energía depende también del tiempo de uso"},{"id":"r2","texto":"Porque la potencia y la energía son lo mismo"},{"id":"r3","texto":"Porque las heladeras no usan electricidad"}]},"solucion":{"valor":false,"explicacion":"Depende del tiempo. La heladera funciona todo el año; la estufa, algunas horas en invierno. La energía es potencia por tiempo.","clave":["r1"]}},{"slug":"energia-1.s4.p9","orden":9,"grupo":"energia-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Grandes cantidades","cuerpo":["Para cantidades grandes se usan múltiplos: un megawatt-hora (MWh) son 1.000 kWh; un gigawatt-hora (GWh), un millón de kWh; un terawatt-hora (TWh), mil millones de kWh.","Una casa argentina típica usa del orden de 2.000 a 4.000 kWh de electricidad por año. Argentina, como país, consume alrededor de 140 TWh de electricidad por año."]},"solucion":{}},{"slug":"energia-1.s4.p10","orden":10,"grupo":"energia-1.s4.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas unidades de menor a mayor.","items":[{"id":"i1","texto":"Watt-hora (Wh)"},{"id":"i2","texto":"Kilowatt-hora (kWh)"},{"id":"i3","texto":"Megawatt-hora (MWh)"},{"id":"i4","texto":"Gigawatt-hora (GWh)"},{"id":"i5","texto":"Terawatt-hora (TWh)"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada paso multiplica por mil. Como gramo, kilo y tonelada, pero con más escalones."}},{"slug":"energia-1.s4.p11","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 1.000 casas que usan 3.000 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"1.000 × 3.000 = 3.000.000 kWh. Un GWh es un millón de kWh: 3 GWh."}},{"slug":"energia-1.s4.p11.v2","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 5.000 casas que usan 2.500 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"5.000 × 2.500 = 12.500.000 kWh. Un GWh es un millón de kWh: 12,5 GWh."}},{"slug":"energia-1.s4.p11.v3","orden":11,"grupo":"energia-1.s4.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio tiene 20.000 casas que usan 3.000 kWh por año cada una. ¿Cuántos GWh usan en total?","unidad":"GWh","decimales":1},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"20.000 × 3.000 = 60.000.000 kWh. Un GWh es un millón de kWh: 60 GWh."}},{"slug":"energia-1.s4.p12","orden":12,"grupo":"energia-1.s4.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La factura de luz marca 500 kWh en dos meses. ¿Qué mide ese número?","opciones":[{"id":"o1","texto":"La energía eléctrica que usó la casa en esos dos meses"},{"id":"o2","texto":"La potencia máxima que puede usar la casa por vez"},{"id":"o3","texto":"Lo que cuesta la luz en pesos"},{"id":"o4","texto":"La cantidad de aparatos que tiene conectados la casa"}]},"solucion":{"clave":["o1"],"explicacion":"El medidor suma energía, kWh, a lo largo del tiempo. La potencia contratada es otro dato.","por_opcion":{"o3":"Los kWh son energía; el precio sale de multiplicarlos por la tarifa."}}},{"slug":"energia-1.s4.p13","orden":13,"grupo":"energia-1.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diálogo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"—La pava tiene 2.000 W de potencia."},{"id":"s2","texto":"—Entonces cada vez que la uso gasto 2.000 kWh."},{"id":"s3","texto":"—Un kWh son 3,6 millones de joules."},{"id":"s4","texto":"—Y un GWh son mil kWh."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Potencia contra energía, y los múltiplos: dos trampas clásicas.","por_opcion":{"s2":"Los W son potencia; la energía depende del tiempo: 3 minutos son 0,1 kWh.","s4":"Un GWh es un millón de kWh; mil kWh son un MWh."}}},{"slug":"energia-1.s4.p14","orden":14,"grupo":"energia-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un kWh son {{0}} millones de joules; mil kWh son un {{1}}; y un millón de kWh son un {{2}}.","banco":[{"id":"w1","texto":"3,6"},{"id":"w2","texto":"MWh"},{"id":"w3","texto":"GWh"},{"id":"w4","texto":"36"},{"id":"w5","texto":"TWh"},{"id":"w6","texto":"kW"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La equivalencia y los múltiplos, resumidos en una línea."}}]},{"slug":"energia-1.s5","orden":5,"tipo":"leccion","titulo_es":"Energía y clima","bajada_es":"Por qué la energía está en el centro del cambio climático, y qué significa descarbonizar.","minutos":11,"pasos":[{"slug":"energia-1.s5.p1","orden":1,"grupo":"energia-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quemar es emitir","cuerpo":["Cuando se quema un combustible fósil, el carbono que tiene se une con el oxígeno del aire y forma CO₂. No hay forma de quemar nafta, gas o carbón sin producirlo: es química básica.","Por eso el uso de energía es la mayor fuente de gases de efecto invernadero: alrededor de tres cuartos de las emisiones del mundo vienen de producir y usar energía, en electricidad, transporte, calefacción e industria."],"destacado":{"valor":"≈ 3/4","texto":"de las emisiones mundiales de gases de efecto invernadero vienen de la energía."}},"solucion":{}},{"slug":"energia-1.s5.p2","orden":2,"grupo":"energia-1.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué es imposible quemar gas natural sin emitir CO₂?","opciones":[{"id":"o1","texto":"Porque su carbono se combina con el oxígeno al quemarse"},{"id":"o2","texto":"Porque las cañerías de gas están hechas de carbono"},{"id":"o3","texto":"Porque el gas ya trae CO₂ mezclado desde el yacimiento"},{"id":"o4","texto":"Porque las hornallas liberan CO₂ aunque estén apagadas"}]},"solucion":{"clave":["o1"],"explicacion":"Combustión es, justamente, la reacción del carbono con el oxígeno. El CO₂ es su producto inevitable.","por_opcion":{"o3":"Puede traer algo, pero el grueso del CO₂ se forma en la combustión misma."}}},{"slug":"energia-1.s5.p3","orden":3,"grupo":"energia-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Factores de emisión","cuerpo":["Para calcular emisiones se usan factores de emisión: cuántos kilos de CO₂ salen por cada unidad de combustible. Quemar un litro de nafta emite unos 2,3 kg de CO₂; un litro de gasoil, unos 2,7 kg; un metro cúbico de gas natural, unos 1,9 kg.","Parece raro que un litro de nafta, que pesa menos de un kilo, produzca más de dos kilos de CO₂. La razón: el CO₂ incluye el oxígeno que se toma del aire."],"datos":{"tipo":"tabla","titulo":"Factores de emisión aproximados","columnas":["Combustible","kg de CO₂"],"filas":[["1 litro de nafta","≈ 2,3"],["1 litro de gasoil","≈ 2,7"],["1 m³ de gas natural","≈ 1,9"]],"nota":"Valores de referencia redondeados."}},"solucion":{}},{"slug":"energia-1.s5.p4","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 40 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":92,"tolerancia":1.84,"explicacion":"40 × 2,3 = 92 kg de CO₂ por semana. Por año son más de 4 toneladas."}},{"slug":"energia-1.s5.p4.v2","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 50 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":115,"tolerancia":2.3000000000000003,"explicacion":"50 × 2,3 = 115 kg de CO₂ por semana. Por año son más de 5 toneladas."}},{"slug":"energia-1.s5.p4.v3","orden":4,"grupo":"energia-1.s5.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto carga 60 litros de nafta por semana. ¿Cuántos kilos de CO₂ emite por semana al quemarla? (2,3 kg por litro)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":138,"tolerancia":2.7600000000000002,"explicacion":"60 × 2,3 = 138 kg de CO₂ por semana. Por año son más de 7 toneladas."}},{"slug":"energia-1.s5.p5","orden":5,"grupo":"energia-1.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un litro de nafta, que pesa unos 750 gramos, no puede producir más de 750 gramos de CO₂.","razones":[{"id":"r1","texto":"Porque el CO₂ incluye el oxígeno que se toma del aire"},{"id":"r2","texto":"Porque la nafta pesa más cuando está caliente"},{"id":"r3","texto":"Porque el CO₂ se produce de la nada"}]},"solucion":{"valor":false,"explicacion":"Produce unos 2,3 kg, porque al quemarse cada átomo de carbono toma dos átomos de oxígeno del aire, que suman peso.","clave":["r1"]}},{"slug":"energia-1.s5.p6","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 60 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":114,"tolerancia":2.2800000000000002,"explicacion":"60 × 1,9 = 114 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p6.v2","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 90 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":171,"tolerancia":3.42,"explicacion":"90 × 1,9 = 171 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p6.v3","orden":6,"grupo":"energia-1.s5.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 150 m³ de gas natural en un mes de invierno. ¿Cuántos kilos de CO₂ emite? (1,9 kg por m³)","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":285,"tolerancia":5.7,"explicacion":"150 × 1,9 = 285 kg de CO₂. En las casas argentinas, la calefacción a gas suele ser la mayor fuente de emisiones directas."}},{"slug":"energia-1.s5.p7","orden":7,"grupo":"energia-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Descarbonizar: tres caminos","cuerpo":["Descarbonizar la energía es bajar las emisiones de CO₂ por cada unidad de energía que usamos. Hay tres caminos que se combinan: usar menos energía para lo mismo (eficiencia), generar con fuentes que no emiten (renovables, nuclear) y electrificar los usos que hoy queman combustible (autos, calefacción, cocinas).","Electrificar sirve cuando la electricidad es cada vez más limpia. Por eso las tres cosas van juntas."],"lista":["Eficiencia: menos energía para lo mismo","Fuentes limpias: renovables y nuclear","Electrificación: pasar a eléctrico lo que hoy quema combustible"]},"solucion":{}},{"slug":"energia-1.s5.p8","orden":8,"grupo":"energia-1.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué camino de descarbonización es cada medida?","grupos":[{"id":"g1","nombre":"Eficiencia"},{"id":"g2","nombre":"Fuentes limpias"},{"id":"g3","nombre":"Electrificación"}],"items":[{"id":"i1","texto":"Cambiar lámparas a LED"},{"id":"i2","texto":"Construir un parque eólico"},{"id":"i3","texto":"Pasar colectivos diésel a eléctricos"},{"id":"i4","texto":"Aislar el techo de una casa"},{"id":"i5","texto":"Instalar paneles solares en una escuela"},{"id":"i6","texto":"Cambiar una estufa a gas por una bomba de calor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres caminos que se refuerzan: la eficiencia achica la demanda, las fuentes limpias la cubren y la electrificación lleva esa limpieza a más usos."}},{"slug":"energia-1.s5.p9","orden":9,"grupo":"energia-1.s5.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué electrificar sirve más cuando la red es limpia.","items":[{"id":"i1","texto":"Un colectivo pasa de gasoil a electricidad"},{"id":"i2","texto":"Deja de quemar combustible en la calle"},{"id":"i3","texto":"Su energía ahora viene de la red"},{"id":"i4","texto":"Si la red se genera con fuentes limpias, emite mucho menos"},{"id":"i5","texto":"El colectivo eléctrico produce su propia electricidad al andar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Electrificar sin limpiar la red sirve menos. Limpiar la red sin electrificar deja afuera al transporte y al calor."}},{"slug":"energia-1.s5.p10","orden":10,"grupo":"energia-1.s5.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos usos de energía emiten CO₂ directamente al usarse? Marcá todos.","opciones":[{"id":"o1","texto":"Una hornalla de gas"},{"id":"o2","texto":"Un auto a nafta"},{"id":"o3","texto":"Una estufa a leña"},{"id":"o4","texto":"Un ventilador eléctrico"},{"id":"o5","texto":"Una LED encendida"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los eléctricos no emiten donde se usan; sus emisiones, si las hay, están en la central. Los que queman algo emiten en el lugar."}},{"slug":"energia-1.s5.p11","orden":11,"grupo":"energia-1.s5.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para un país cuya electricidad sale mayormente de gas, ¿qué conviene hacer primero si quiere que los autos eléctricos ayuden mucho?","opciones":[{"id":"o1","texto":"Limpiar la red sumando fuentes que no emiten"},{"id":"o2","texto":"Prohibir todos los autos de un día para el otro"},{"id":"o3","texto":"Nada: el auto eléctrico siempre emite cero"},{"id":"o4","texto":"Importar nafta más barata de otros países"}]},"solucion":{"clave":["o1"],"explicacion":"La electrificación y la red limpia van de la mano. Aun con gas, el eléctrico suele emitir menos, pero la ventaja crece con una red más limpia.","por_opcion":{"o3":"El auto no tiene caño de escape, pero su electricidad sí puede tener emisiones."}}},{"slug":"energia-1.s5.p12","orden":12,"grupo":"energia-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La energía es la mayor fuente de emisiones del mundo."},{"id":"s2","texto":"Como la electricidad no emite humo, electrificar alcanza para resolver el clima."},{"id":"s3","texto":"Quemar un litro de nafta emite más de 2 kg de CO₂."},{"id":"s4","texto":"La eficiencia no sirve porque las renovables son infinitas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ningún camino alcanza solo. La combinación es la estrategia.","por_opcion":{"s2":"Electrificar ayuda si la electricidad se genera con fuentes limpias; si no, se traslada el problema.","s4":"La eficiencia reduce cuánto hay que generar: abarata y acelera la transición."}}},{"slug":"energia-1.s5.p13","orden":13,"grupo":"energia-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Quemar combustibles fósiles emite {{0}}; los tres caminos para descarbonizar son eficiencia, fuentes {{1}} y {{2}}.","banco":[{"id":"w1","texto":"CO₂"},{"id":"w2","texto":"limpias"},{"id":"w3","texto":"electrificación"},{"id":"w4","texto":"oxígeno"},{"id":"w5","texto":"fósiles"},{"id":"w6","texto":"importación"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea central de toda la rama de energía."}}]},{"slug":"energia-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: qué es la energía","bajada_es":"Formas, eficiencia, fuentes, unidades y emisiones, mezclados.","minutos":8,"pasos":[{"slug":"energia-1.s6.p1","orden":1,"grupo":"energia-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Qué es la energía». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la energía de un día de Lucía","bajada_es":"Seguí la energía de un día común: qué usa, de dónde sale y cuánto CO₂ emite. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"energia-1.s7.p1","orden":1,"grupo":"energia-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El día de Lucía","cuerpo":["Lucía vive en Córdoba. A la mañana calienta agua en una pava eléctrica de 2.000 W durante 3 minutos. Va al trabajo en auto: 20 km ida y vuelta, y su auto usa 8 litros de nafta cada 100 km. A la noche mira una serie 2 horas en un televisor de 100 W con dos lámparas LED de 9 W prendidas.","En invierno, la estufa a gas de su casa usa 3 m³ de gas por día."]},"solucion":{}},{"slug":"energia-1.s7.p2","orden":2,"grupo":"energia-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de nafta usa Lucía por día para ir y volver del trabajo?","unidad":"litros","decimales":1,"contexto":"Lucía maneja 20 km por día; su auto usa 8 L cada 100 km."},"solucion":{"valor":1.6,"tolerancia":0.05,"explicacion":"20 km × 8 litros ÷ 100 km = 1,6 litros por día."}},{"slug":"energia-1.s7.p3","orden":3,"grupo":"energia-1.s7.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos de CO₂ emite ese viaje diario? (2,3 kg por litro de nafta)","unidad":"kg de CO₂","decimales":2,"contexto":"Lucía usa 1,6 L de nafta por día; la nafta emite 2,3 kg de CO₂ por litro."},"solucion":{"valor":3.68,"tolerancia":0.05,"explicacion":"1,6 × 2,3 = 3,68 kg de CO₂ por día. En un año laboral de unos 230 días, más de 800 kg."}},{"slug":"energia-1.s7.p4","orden":4,"grupo":"energia-1.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh de electricidad usa a la noche entre el televisor y las dos lámparas?","unidad":"kWh","decimales":3,"contexto":"TV de 100 W y dos LED de 9 W, prendidos 2 horas."},"solucion":{"valor":0.236,"tolerancia":0.005,"explicacion":"Televisor: 0,1 kW × 2 h = 0,2 kWh. Lámparas: 2 × 0,009 kW × 2 h = 0,036 kWh. Total: 0,236 kWh."}},{"slug":"energia-1.s7.p5","orden":5,"grupo":"energia-1.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los usos de energía de Lucía en un día de invierno, de más a menos energía (aproximado).","items":[{"id":"i1","texto":"Estufa a gas (3 m³)"},{"id":"i2","texto":"Viaje en auto (1,6 L de nafta)"},{"id":"i3","texto":"Televisor y lámparas"},{"id":"i4","texto":"Pava eléctrica"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La calefacción y el auto pesan cientos de veces más que la pava o las luces. Es el principio de elegir por impacto del tronco.","valores":{"i1":"≈ 30 kWh","i2":"≈ 14 kWh","i3":"≈ 0,24 kWh","i4":"0,1 kWh"}}},{"slug":"energia-1.s7.p6","orden":6,"grupo":"energia-1.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si Lucía quiere bajar sus emisiones lo más posible con un solo cambio, ¿cuál tiene más impacto?","opciones":[{"id":"o1","texto":"Mejorar la aislación de la casa o la calefacción"},{"id":"o2","texto":"Apagar las lámparas LED un rato antes"},{"id":"o3","texto":"Calentar menos agua en la pava a la mañana"},{"id":"o4","texto":"Desenchufar el cargador del celular a la noche"}]},"solucion":{"clave":["o1"],"explicacion":"La calefacción es el mayor uso de energía de su día de invierno. Ahí está el cambio grande. El auto es el segundo.","por_opcion":{"o3":"Ahorra, pero es un uso muy chico comparado con la calefacción y el auto."}}},{"slug":"energia-1.s7.p7","orden":7,"grupo":"energia-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los usos de energía de Lucía.","grupos":[{"id":"g1","nombre":"Emiten CO₂ donde se usan"},{"id":"g2","nombre":"Sus emisiones dependen de la red"}],"items":[{"id":"i1","texto":"La estufa a gas"},{"id":"i2","texto":"La pava eléctrica"},{"id":"i3","texto":"El auto a nafta"},{"id":"i4","texto":"El televisor"},{"id":"i5","texto":"Las lámparas LED"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Los usos que queman combustible emiten en el lugar; los eléctricos, en la central. Electrificar y limpiar la red atacan los dos grupos."}},{"slug":"energia-1.s7.p8","orden":8,"grupo":"energia-1.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Lucía escribe su plan. Marcá lo que está mal razonado.","segmentos":[{"id":"s1","texto":"Voy a revisar los burletes y cerrar mejor las ventanas en invierno."},{"id":"s2","texto":"Voy a desenchufar la pava, porque es lo que más energía usa en mi casa."},{"id":"s3","texto":"Voy a compartir el auto con un compañero dos días por semana."},{"id":"s4","texto":"Como la tele es eléctrica, no tiene ningún impacto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan empieza por los usos grandes y no descarta los eléctricos: solo los pone en su lugar.","por_opcion":{"s2":"La pava usa 0,1 kWh por día; la estufa, unos 30.","s4":"Su impacto depende de cómo se genera la electricidad, aunque sea chico."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-2","rama":"energia","orden":2,"nivel":1,"titulo_es":"La energía en casa","bajada_es":"Calefacción, heladera, aire acondicionado y stand-by: en qué se va la energía de una casa y dónde está el ahorro de verdad.","objetivos_es":["Identificar los usos que más energía consumen en un hogar","Calcular el consumo mensual de un aparato con su potencia y sus horas de uso","Leer una factura de electricidad y comparar períodos","Usar la etiqueta de eficiencia para elegir un aparato","Aplicar medidas de calefacción y refrigeración eficientes"],"repasa":["energia-1","tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["iea-eficiencia","iea-energia","owid-energia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-2.s1","orden":1,"tipo":"leccion","titulo_es":"En qué se va la energía de una casa","bajada_es":"Gas y electricidad, calefacción y heladera: el mapa de los consumos de un hogar.","minutos":11,"pasos":[{"slug":"energia-2.s1.p1","orden":1,"grupo":"energia-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos energías entran a casa","cuerpo":["En la mayoría de las casas argentinas con red de gas entran dos energías: gas natural y electricidad. El gas se usa para calefacción, agua caliente y cocina; la electricidad, para la heladera, la iluminación, los electrodomésticos, los equipos electrónicos y, cada vez más, el aire acondicionado.","Donde no hay red de gas, se usa gas envasado (garrafas), leña o electricidad para calefaccionar y cocinar, y eso cambia mucho las cuentas."]},"solucion":{}},{"slug":"energia-2.s1.p2","orden":2,"grupo":"energia-2.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué energía suele usar cada cosa en una casa con red de gas?","grupos":[{"id":"g1","nombre":"Gas"},{"id":"g2","nombre":"Electricidad"}],"items":[{"id":"i1","texto":"Estufa de tiro balanceado"},{"id":"i2","texto":"Heladera"},{"id":"i3","texto":"Calefón o termotanque a gas"},{"id":"i4","texto":"Lámparas"},{"id":"i5","texto":"Hornallas de la cocina"},{"id":"i6","texto":"Aire acondicionado"},{"id":"i7","texto":"Televisor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g2"},"explicacion":"En una casa con gas, la calefacción y el agua caliente suelen ser a gas. Eso importa: son justamente los usos más grandes."}},{"slug":"energia-2.s1.p3","orden":3,"grupo":"energia-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Calor: el uso más grande","cuerpo":["Si se suma toda la energía de un año, en muchas casas del centro y el sur del país el uso más grande es la calefacción, seguida por el agua caliente. Calentar aire y agua requiere muchísima energía.","En la electricidad, los grandes consumos suelen ser la heladera (que funciona todo el año), el aire acondicionado en verano, los aparatos que calientan (pava, horno eléctrico, estufas eléctricas) y la suma de muchos aparatos chicos."],"datos":{"tipo":"barras","titulo":"Energía de una casa con gas en un año (ejemplo aproximado)","unidad":"% del total","filas":[{"etiqueta":"Calefacción","valor":50},{"etiqueta":"Agua caliente","valor":20},{"etiqueta":"Cocina","valor":8},{"etiqueta":"Heladera","valor":7},{"etiqueta":"Resto de la electricidad","valor":15}],"nota":"Ejemplo ilustrativo de una casa de clima templado. Varía mucho según la región y el tipo de casa."}},"solucion":{}},{"slug":"energia-2.s1.p4","orden":4,"grupo":"energia-2.s1.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"En esa casa de ejemplo, ordená los usos de más a menos energía anual.","items":[{"id":"i1","texto":"Calefacción"},{"id":"i2","texto":"Agua caliente"},{"id":"i3","texto":"Cocina"},{"id":"i4","texto":"Heladera"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El calor —para el ambiente y para el agua— se lleva la mayor parte. Por eso ahí están los ahorros más grandes.","valores":{"i1":"≈ 50 %","i2":"≈ 20 %","i3":"≈ 8 %","i4":"≈ 7 %"}}},{"slug":"energia-2.s1.p5","orden":5,"grupo":"energia-2.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En una casa con gas, apagar las luces es la forma más efectiva de bajar la energía total que usa la casa.","razones":[{"id":"r1","texto":"Porque la calefacción y el agua caliente pesan mucho más"},{"id":"r2","texto":"Porque las luces no usan energía"},{"id":"r3","texto":"Porque las luces usan más energía que la calefacción"}]},"solucion":{"valor":false,"explicacion":"Apagar luces ayuda, pero la iluminación LED es un uso chico. La calefacción y el agua caliente pesan muchísimo más.","clave":["r1"]}},{"slug":"energia-2.s1.p6","orden":6,"grupo":"energia-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los pilotos y los consumos que no se ven","cuerpo":["Algunos consumos pasan desapercibidos: el piloto de un termotanque o una estufa a gas queda encendido todo el día, aunque nadie use agua caliente ni calefacción. En verano, apagar los pilotos de las estufas que no se usan ahorra gas sin ningún esfuerzo.","En la electricidad pasa algo parecido con el stand-by: televisores, decodificadores, cargadores y equipos de audio que consumen aunque estén \"apagados\"."]},"solucion":{}},{"slug":"energia-2.s1.p7","orden":7,"grupo":"energia-2.s1.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos consumos suceden aunque nadie esté usando el aparato? Marcá todos.","opciones":[{"id":"o1","texto":"El piloto de una estufa a gas en verano"},{"id":"o2","texto":"Un decodificador en stand-by"},{"id":"o3","texto":"Un cargador enchufado sin celular"},{"id":"o4","texto":"Una pava eléctrica desenchufada"},{"id":"o5","texto":"Una lámpara apagada con la llave"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Lo que queda enchufado o encendido \"por las dudas\" consume todo el tiempo. Chico por hora, grande por año."}},{"slug":"energia-2.s1.p8","orden":8,"grupo":"energia-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada uso con su mejor ahorro.","izquierda":[{"id":"a1","texto":"Calefacción"},{"id":"a2","texto":"Agua caliente"},{"id":"a3","texto":"Heladera"},{"id":"a4","texto":"Stand-by"}],"derecha":[{"id":"b1","texto":"Burletes y temperatura moderada"},{"id":"b2","texto":"Duchas más cortas"},{"id":"b3","texto":"Cerrarla bien y no poner cosas calientes"},{"id":"b4","texto":"Zapatilla con interruptor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada uso tiene su palanca. Las más grandes están en el calor."}},{"slug":"energia-2.s1.p9","orden":9,"grupo":"energia-2.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una familia quiere bajar su consumo de gas en invierno. ¿Por dónde conviene empezar?","opciones":[{"id":"o1","texto":"Por la calefacción y sus pérdidas"},{"id":"o2","texto":"Por la cocina: dejar de hacer guisos y sopas"},{"id":"o3","texto":"Por el horno: usarlo solo los domingos"},{"id":"o4","texto":"Por la pava: calentar agua solo una vez por día"}]},"solucion":{"clave":["o1"],"explicacion":"Elegir por impacto, como en el tronco: la calefacción es la mitad del consumo en muchas casas.","por_opcion":{"o3":"El horno usa gas, pero mucho menos que la calefacción en invierno."}}},{"slug":"energia-2.s1.p10","orden":10,"grupo":"energia-2.s1.p10","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de una revista y marcá los que no tienen sentido o están mal.","segmentos":[{"id":"s1","texto":"En verano, apagá los pilotos de las estufas."},{"id":"s2","texto":"Desenchufá la heladera de noche para ahorrar."},{"id":"s3","texto":"Revisá los burletes antes del invierno."},{"id":"s4","texto":"Dejá la estufa prendida con la ventana abierta para ventilar mejor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen consejo ahorra sin arruinar la comida ni la salud.","por_opcion":{"s2":"Se corta la cadena de frío y la comida se echa a perder; además al volver consume más.","s4":"Se tira el calor afuera. Para ventilar alcanza con abrir unos minutos."}}},{"slug":"energia-2.s1.p11","orden":11,"grupo":"energia-2.s1.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el piloto de una estufa en verano es un derroche.","items":[{"id":"i1","texto":"La estufa no se usa en verano"},{"id":"i2","texto":"El piloto sigue encendido todo el día"},{"id":"i3","texto":"Quema gas durante meses sin calentar nada útil"},{"id":"i4","texto":"Se paga ese gas y se emite CO₂ sin motivo"},{"id":"i5","texto":"El piloto genera electricidad para la casa"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un consumo chico por hora, multiplicado por todas las horas de un verano."}},{"slug":"energia-2.s1.p12","orden":12,"grupo":"energia-2.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En muchas casas, el mayor consumo de energía es la {{0}}, seguida por el agua {{1}}.","banco":[{"id":"w1","texto":"calefacción"},{"id":"w2","texto":"caliente"},{"id":"w3","texto":"iluminación"},{"id":"w4","texto":"fría"},{"id":"w5","texto":"computadora"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Por eso los ahorros grandes están en el calor, no en las luces."}},{"slug":"energia-2.s1.p13","orden":13,"grupo":"energia-2.s1.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"En esa casa de ejemplo, ¿qué porcentaje de toda la energía va a calefacción y agua caliente juntas?","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":70,"banda":"lineal","explicacion":"Alrededor del 70 %: la mitad para la calefacción y un quinto para el agua caliente. Calentar es lo que más energía pide."}}]},{"slug":"energia-2.s2","orden":2,"tipo":"leccion","titulo_es":"Cuánto usa cada aparato","bajada_es":"Potencia por horas: la cuenta que permite saber cuánto consume la heladera, el aire o el stand-by.","minutos":12,"pasos":[{"slug":"energia-2.s2.p1","orden":1,"grupo":"energia-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cuenta que ya sabés","cuerpo":["La energía que usa un aparato es su potencia por el tiempo que funciona. Si un aire acondicionado consume 1 kW y funciona 6 horas, usa 6 kWh ese día. En un mes de 30 días, 180 kWh.","La potencia figura en una etiqueta del aparato o en el manual, en watts (W). Para pasar a kW se divide por 1.000."]},"solucion":{}},{"slug":"energia-2.s2.p2","orden":2,"grupo":"energia-2.s2.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El aire acondicionado en enero","planteo":"Un aire acondicionado consume 1.000 W y funciona 6 horas por día durante 30 días.","pasos":["Potencia: 1.000 W = 1 kW.","Por día: 1 kW × 6 h = 6 kWh.","Por mes: 6 kWh × 30 = 180 kWh."],"resultado":"180 kWh en un mes solo de aire: puede ser tanto como todo el resto de la casa junto."},"solucion":{}},{"slug":"energia-2.s2.p3","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.000 W funciona 6 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"1 kW × 6 h × 30 días = 180 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v2","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.300 W funciona 4 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":156,"tolerancia":3.12,"explicacion":"1,3 kW × 4 h × 30 días = 156 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v3","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 800 W funciona 8 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":192,"tolerancia":3.84,"explicacion":"0,8 kW × 8 h × 30 días = 192 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p3.v4","orden":3,"grupo":"energia-2.s2.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.500 W funciona 5 horas por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":0},"solucion":{"valor":225,"tolerancia":4.5,"explicacion":"1,5 kW × 5 h × 30 días = 225 kWh. Potencia en kW por horas por días."}},{"slug":"energia-2.s2.p4","orden":4,"grupo":"energia-2.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los aparatos que se prenden y apagan solos","cuerpo":["La heladera no funciona a plena potencia todo el tiempo: su motor se prende y se apaga para mantener el frío. Por eso conviene mirar su consumo anual o diario, que figura en la etiqueta, en vez de su potencia. Una heladera eficiente usa del orden de 1 kWh por día.","Con el aire acondicionado pasa algo parecido: los equipos inverter regulan su potencia en vez de prender y apagar, y suelen usar bastante menos energía."]},"solucion":{}},{"slug":"energia-2.s2.p5","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 300 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"300 ÷ 12 = 25 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p5.v2","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 450 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":37.5,"tolerancia":0.75,"explicacion":"450 ÷ 12 = 37,5 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p5.v3","orden":5,"grupo":"energia-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La etiqueta de una heladera dice que consume 600 kWh por año. ¿Cuántos kWh usa por mes, en promedio?","unidad":"kWh por mes","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"600 ÷ 12 = 50 kWh por mes. El consumo anual de la etiqueta es la forma más confiable de comparar heladeras."}},{"slug":"energia-2.s2.p6","orden":6,"grupo":"energia-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Stand-by: poco por hora, mucho por año","cuerpo":["Un aparato en stand-by puede consumir de 1 a 10 W, o más en equipos viejos. Parece nada, pero funciona las 8.760 horas del año. Diez aparatos con 5 W de stand-by cada uno suman 50 W constantes: unos 438 kWh por año.","Según la Agencia Internacional de Energía, el stand-by llegó a representar una parte de la electricidad de los hogares de entre el 5 y el 10 % en muchos países."]},"solucion":{}},{"slug":"energia-2.s2.p7","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 30 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":262.8,"tolerancia":5.256,"explicacion":"0,03 kW × 8.760 h = 262,8 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p7.v2","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 50 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":438,"tolerancia":8.76,"explicacion":"0,05 kW × 8.760 h = 438 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p7.v3","orden":7,"grupo":"energia-2.s2.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los aparatos en stand-by de una casa suman 20 W constantes. ¿Cuántos kWh usan en un año de 8.760 horas?","unidad":"kWh por año","decimales":1},"solucion":{"valor":175.2,"tolerancia":3.504,"explicacion":"0,02 kW × 8.760 h = 175,2 kWh por año. Poco por hora, mucho por año."}},{"slug":"energia-2.s2.p8","orden":8,"grupo":"energia-2.s2.p8","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por consumo mensual típico, de más a menos (valores aproximados).","items":[{"id":"i1","texto":"Aire acondicionado 6 h diarias en verano"},{"id":"i2","texto":"Heladera con freezer"},{"id":"i3","texto":"Stand-by de toda la casa"},{"id":"i4","texto":"Cinco lámparas LED 5 h diarias"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El aire en verano es un gigante. El stand-by puede competir con la heladera. Las LED son chicas.","valores":{"i1":"≈ 180 kWh","i2":"≈ 30-45 kWh","i3":"≈ 15-35 kWh","i4":"≈ 7 kWh"}}},{"slug":"energia-2.s2.p9","orden":9,"grupo":"energia-2.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un aparato de mucha potencia siempre consume más energía por mes que uno de poca potencia.","razones":[{"id":"r1","texto":"Porque la energía depende también de las horas de uso"},{"id":"r2","texto":"Porque la potencia es la energía mensual"},{"id":"r3","texto":"Porque los aparatos de mucha potencia no consumen"}]},"solucion":{"valor":false,"explicacion":"Depende de cuántas horas funciona. Un secador de pelo de 2.000 W usado 5 minutos por día consume menos que una heladera que funciona todo el día.","clave":["r1"]}},{"slug":"energia-2.s2.p10","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 2.000 W se usa 5 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":5,"tolerancia":0.05,"explicacion":"2 kW × 0,083 h × 30 = 5 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p10.v2","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 1.800 W se usa 10 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":9,"tolerancia":0.05,"explicacion":"1,8 kW × 0,167 h × 30 = 9 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p10.v3","orden":10,"grupo":"energia-2.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un secador de pelo de 2.200 W se usa 6 minutos por día. ¿Cuántos kWh usa en 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":6.6,"tolerancia":0.05,"explicacion":"2,2 kW × 0,1 h × 30 = 6,6 kWh. Mucha potencia, poco tiempo."}},{"slug":"energia-2.s2.p11","orden":11,"grupo":"energia-2.s2.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué dato conviene mirar para comparar el consumo de dos heladeras?","opciones":[{"id":"o1","texto":"El consumo anual en kWh de la etiqueta"},{"id":"o2","texto":"La potencia del motor en watts"},{"id":"o3","texto":"El tamaño en litros solamente"},{"id":"o4","texto":"El color y el material de la puerta"}]},"solucion":{"clave":["o1"],"explicacion":"Como el motor se prende y apaga, la potencia sola no dice cuánto usa. El consumo anual sí.","por_opcion":{"o3":"El tamaño importa, pero dos heladeras iguales pueden consumir muy distinto."}}},{"slug":"energia-2.s2.p12","orden":12,"grupo":"energia-2.s2.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué reduce el consumo de una heladera? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Cerrar bien la puerta y no dejarla abierta"},{"id":"o2","texto":"Dejar espacio atrás para que ventile"},{"id":"o3","texto":"No meter comida caliente"},{"id":"o4","texto":"Revisar que el burlete cierre bien"},{"id":"o5","texto":"Ponerla al lado del horno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La heladera saca calor de adentro y lo tira afuera por atrás. Si le entra calor o no puede tirarlo, trabaja más."}},{"slug":"energia-2.s2.p13","orden":13,"grupo":"energia-2.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía de un aparato es su {{0}} por las {{1}} de uso; el stand-by consume poco por hora pero mucho por {{2}}.","banco":[{"id":"w1","texto":"potencia"},{"id":"w2","texto":"horas"},{"id":"w3","texto":"año"},{"id":"w4","texto":"tamaño"},{"id":"w5","texto":"watts"},{"id":"w6","texto":"minuto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta básica de la energía y su trampa más común."}},{"slug":"energia-2.s2.p14","orden":14,"grupo":"energia-2.s2.p14","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá los errores.","segmentos":[{"id":"s1","texto":"El aire tiene 1.000 W y lo uso 6 horas: son 6 kWh por día."},{"id":"s2","texto":"La heladera tiene un motor de 150 W, así que usa 150 × 24 = 3,6 kWh por día."},{"id":"s3","texto":"El stand-by de 5 W por aparato no importa en un año."},{"id":"s4","texto":"El secador de 2.000 W usado 5 minutos consume poco por mes."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Potencia por tiempo, pero con el tiempo real de funcionamiento.","por_opcion":{"s2":"El motor se prende y se apaga: el consumo real es mucho menor, mejor mirar la etiqueta.","s3":"Varios aparatos por 8.760 horas suman cientos de kWh."}}}]},{"slug":"energia-2.s3","orden":3,"tipo":"leccion","titulo_es":"Leer la factura de luz","bajada_es":"Qué dice cada parte, cómo comparar períodos y cómo pasar de la factura a kWh por día.","minutos":11,"pasos":[{"slug":"energia-2.s3.p1","orden":1,"grupo":"energia-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las partes de una factura","cuerpo":["Una factura de electricidad tiene el período facturado (las fechas entre dos lecturas del medidor), la lectura anterior y la actual, el consumo en kWh (la resta de las dos lecturas), los cargos (uno fijo y uno variable por kWh) y los impuestos.","El número clave para el ambiente es el consumo en kWh. El monto en pesos cambia por tarifas, subsidios e impuestos; los kWh dicen cuánta energía usó la casa."]},"solucion":{}},{"slug":"energia-2.s3.p2","orden":2,"grupo":"energia-2.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El medidor marcaba 45.320 kWh en la lectura anterior y 45.680 en la actual. ¿Cuántos kWh se consumieron?","unidad":"kWh","decimales":0},"solucion":{"valor":360,"tolerancia":7.2,"explicacion":"45.680 − 45.320 = 360 kWh. El consumo es la diferencia entre las dos lecturas."}},{"slug":"energia-2.s3.p3","orden":3,"grupo":"energia-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comparar bien","cuerpo":["Para comparar dos facturas conviene pasar a kWh por día, porque los períodos no siempre tienen la misma cantidad de días. También conviene comparar con el mismo período del año anterior: julio con julio, enero con enero, porque el clima cambia mucho el consumo.","Muchas facturas traen un gráfico con los consumos de los últimos meses: es la herramienta más simple para ver si un cambio de hábito funcionó."]},"solucion":{}},{"slug":"energia-2.s3.p4","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 360 kWh en un período de 60 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":6,"tolerancia":0.1,"explicacion":"360 ÷ 60 ≈ 6 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p4.v2","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 420 kWh en un período de 61 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":6.9,"tolerancia":0.1,"explicacion":"420 ÷ 61 ≈ 6,9 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p4.v3","orden":4,"grupo":"energia-2.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una factura marca 250 kWh en un período de 30 días. ¿Cuántos kWh por día usó la casa? Redondeá a un decimal.","unidad":"kWh por día","decimales":1},"solucion":{"valor":8.3,"tolerancia":0.1,"explicacion":"250 ÷ 30 ≈ 8,3 kWh por día. Así se pueden comparar períodos de distinta duración."}},{"slug":"energia-2.s3.p5","orden":5,"grupo":"energia-2.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Con qué conviene comparar el consumo de la factura de enero para saber si la casa ahorró?","opciones":[{"id":"o1","texto":"Con el consumo de enero del año anterior"},{"id":"o2","texto":"Con el consumo de julio del mismo año"},{"id":"o3","texto":"Con el monto en pesos de diciembre"},{"id":"o4","texto":"Con la factura de enero de un vecino"}]},"solucion":{"clave":["o1"],"explicacion":"Mismo mes, mismo clima aproximado. Así la diferencia se explica por los hábitos, no por el tiempo.","por_opcion":{"o3":"El monto cambia por tarifas e impuestos; y diciembre tiene otro clima."}}},{"slug":"energia-2.s3.p6","orden":6,"grupo":"energia-2.s3.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la factura de este mes cuesta más pesos que la anterior, seguro la casa usó más energía.","razones":[{"id":"r1","texto":"Porque el precio puede cambiar aunque el consumo no"},{"id":"r2","texto":"Porque los pesos y los kWh son siempre proporcionales"},{"id":"r3","texto":"Porque las facturas no dicen los kWh"}]},"solucion":{"valor":false,"explicacion":"Puede haber subido la tarifa o cambiado un subsidio. Para saber si se usó más energía hay que mirar los kWh, y mejor por día.","clave":["r1"]}},{"slug":"energia-2.s3.p7","orden":7,"grupo":"energia-2.s3.p7","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Comparar dos veranos","planteo":"Enero del año pasado: 420 kWh en 31 días. Enero de este año: 360 kWh en 31 días. La familia cambió el aire acondicionado a 24 °C y cerró cortinas de día.","pasos":["Año pasado: 420 ÷ 31 ≈ 13,5 kWh por día.","Este año: 360 ÷ 31 ≈ 11,6 kWh por día.","Diferencia: 13,5 − 11,6 = 1,9 kWh por día, un 14 % menos."],"resultado":"Mismo mes, misma cantidad de días: el ahorro se debe a los hábitos. Así se verifica que un cambio funciona."},"solucion":{}},{"slug":"energia-2.s3.p8","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 420 kWh y este enero 360 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":14,"tolerancia":1,"explicacion":"Bajó 60 kWh sobre 420: 60 ÷ 420 × 100 ≈ 14 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p8.v2","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 500 kWh y este enero 400 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":20,"tolerancia":1,"explicacion":"Bajó 100 kWh sobre 500: 100 ÷ 500 × 100 ≈ 20 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p8.v3","orden":8,"grupo":"energia-2.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En enero del año pasado la casa usó 300 kWh y este enero 270 kWh (mismos días). ¿En qué porcentaje bajó el consumo? Redondeá al entero.","unidad":"%","decimales":0},"solucion":{"valor":10,"tolerancia":1,"explicacion":"Bajó 30 kWh sobre 300: 30 ÷ 300 × 100 ≈ 10 %. Siempre sobre el valor original."}},{"slug":"energia-2.s3.p9","orden":9,"grupo":"energia-2.s3.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para revisar si un cambio de hábito funcionó.","items":[{"id":"i1","texto":"Anotar el consumo en kWh del mismo mes del año anterior"},{"id":"i2","texto":"Aplicar el cambio de hábito durante el mes"},{"id":"i3","texto":"Leer el consumo en kWh de la nueva factura"},{"id":"i4","texto":"Pasar los dos consumos a kWh por día"},{"id":"i5","texto":"Comparar y calcular la diferencia en porcentaje"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Medir antes, cambiar, medir después y comparar en la misma unidad: el método del tronco aplicado a la factura."}},{"slug":"energia-2.s3.p10","orden":10,"grupo":"energia-2.s3.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este dato de la factura dice cuánta energía usó la casa o no?","grupos":[{"id":"g1","nombre":"Dice cuánta energía usó"},{"id":"g2","nombre":"No dice cuánta energía usó"}],"items":[{"id":"i1","texto":"Consumo en kWh"},{"id":"i2","texto":"Monto total en pesos"},{"id":"i3","texto":"Lecturas del medidor"},{"id":"i4","texto":"Impuestos provinciales"},{"id":"i5","texto":"Gráfico de consumos por mes"},{"id":"i6","texto":"Fecha de vencimiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La energía está en los kWh y las lecturas. Lo demás es plata y administración."}},{"slug":"energia-2.s3.p11","orden":11,"grupo":"energia-2.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término de la factura con su significado.","izquierda":[{"id":"a1","texto":"Período"},{"id":"a2","texto":"Lectura actual"},{"id":"a3","texto":"Consumo"},{"id":"a4","texto":"Cargo fijo"}],"derecha":[{"id":"b1","texto":"Fechas entre dos lecturas"},{"id":"b2","texto":"Número que marca hoy el medidor"},{"id":"b3","texto":"Diferencia entre lecturas en kWh"},{"id":"b4","texto":"Monto que se paga aunque no se consuma"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro términos que alcanzan para entender cualquier factura de electricidad."}},{"slug":"energia-2.s3.p12","orden":12,"grupo":"energia-2.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estas conclusiones sobre una factura y marcá las equivocadas.","segmentos":[{"id":"s1","texto":"Este bimestre usamos 360 kWh, unos 6 kWh por día."},{"id":"s2","texto":"Julio consumió más que enero: seguro alguien dejó luces prendidas."},{"id":"s3","texto":"La factura vino más cara, así que usamos más kWh."},{"id":"s4","texto":"Comparamos con el mismo bimestre del año pasado y bajamos un 10 %."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Comparar bien es mismo período, misma unidad, y kWh en vez de pesos.","por_opcion":{"s2":"Puede deberse al clima; hay que comparar julio con julio.","s3":"El precio puede subir por la tarifa aunque el consumo baje."}}},{"slug":"energia-2.s3.p13","orden":13,"grupo":"energia-2.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para comparar facturas conviene pasar a kWh por {{0}} y comparar con el mismo {{1}} del año anterior.","banco":[{"id":"w1","texto":"día"},{"id":"w2","texto":"mes"},{"id":"w3","texto":"peso"},{"id":"w4","texto":"vecino"},{"id":"w5","texto":"minuto"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Así se ve el efecto de los hábitos y no el del clima o el de la tarifa."}},{"slug":"energia-2.s3.p14","orden":14,"grupo":"energia-2.s3.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá: una casa usa 6 kWh por día. ¿Cuántos kWh usa por año?","min":500,"max":5000,"paso":10,"unidad":"kWh","escala":"lineal"},"solucion":{"valor":2190,"banda":"lineal","explicacion":"6 × 365 = 2.190 kWh por año. Un orden de magnitud típico para una casa argentina con gas."}}]},{"slug":"energia-2.s4","orden":4,"tipo":"leccion","titulo_es":"La etiqueta de eficiencia","bajada_es":"Las letras y los números de la etiqueta, y cómo usarlos para elegir un aparato que gaste menos toda su vida.","minutos":11,"pasos":[{"slug":"energia-2.s4.p1","orden":1,"grupo":"energia-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué dice la etiqueta","cuerpo":["En Argentina, muchos aparatos se venden con una etiqueta de eficiencia energética: heladeras, lavarropas, aires acondicionados, lámparas, termotanques y otros. Tiene una escala de letras, de la más eficiente (A o sus variantes con signos +) a la menos eficiente, y el consumo de energía estimado, normalmente por año.","La letra sirve para una comparación rápida; el consumo en kWh por año sirve para hacer cuentas. Dos heladeras con la misma letra pueden consumir distinto si tienen distinto tamaño."]},"solucion":{}},{"slug":"energia-2.s4.p2","orden":2,"grupo":"energia-2.s4.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En la etiqueta de una heladera, ¿qué dato permite calcular cuánto va a consumir?","opciones":[{"id":"o1","texto":"El consumo de energía en kWh por año"},{"id":"o2","texto":"La letra de la clase de eficiencia"},{"id":"o3","texto":"El nombre del fabricante"},{"id":"o4","texto":"El volumen del freezer en litros"}]},"solucion":{"clave":["o1"],"explicacion":"La letra orienta; el número es lo que se multiplica por el precio del kWh o por años de uso.","por_opcion":{"o3":"La marca no dice cuánto consume: la etiqueta sí."}}},{"slug":"energia-2.s4.p3","orden":3,"grupo":"energia-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El precio de toda la vida","cuerpo":["Un aparato se paga dos veces: cuando se compra y cada mes en la factura. Una heladera dura 10 o 15 años. Si una consume 200 kWh por año más que otra, en 12 años son 2.400 kWh más.","Por eso conviene comparar el costo total: precio de compra más energía durante la vida útil. A veces el aparato un poco más caro es el más barato."]},"solucion":{}},{"slug":"energia-2.s4.p4","orden":4,"grupo":"energia-2.s4.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Dos heladeras","planteo":"Heladera A: consume 300 kWh por año. Heladera B: consume 500 kWh por año. Las dos duran 12 años.","pasos":["Diferencia anual: 500 − 300 = 200 kWh.","En 12 años: 200 × 12 = 2.400 kWh.","Si cada kWh cuesta $100, son $240.000 de diferencia en energía."],"resultado":"Si la heladera A cuesta menos de $240.000 más que la B, termina siendo más barata. Y además emite menos."},"solucion":{}},{"slug":"energia-2.s4.p5","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 300 kWh por año y otra 500. Si duran 12 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":2400,"tolerancia":48,"explicacion":"(500 − 300) × 12 = 2.400 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p5.v2","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 250 kWh por año y otra 400. Si duran 10 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"(400 − 250) × 10 = 1.500 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p5.v3","orden":5,"grupo":"energia-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera consume 350 kWh por año y otra 450. Si duran 15 años, ¿cuántos kWh más usa la menos eficiente en toda su vida?","unidad":"kWh","decimales":0},"solucion":{"valor":1500,"tolerancia":30,"explicacion":"(450 − 350) × 15 = 1.500 kWh. La diferencia de consumo se repite todos los años de uso."}},{"slug":"energia-2.s4.p6","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 2.400 kWh más que otra en toda su vida. Si el kWh cuesta $100, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":240000,"tolerancia":4800,"explicacion":"2.400 × 100 = $240.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p6.v2","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 1.500 kWh más que otra en toda su vida. Si el kWh cuesta $120, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":180000,"tolerancia":3600,"explicacion":"1.500 × 120 = $180.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p6.v3","orden":6,"grupo":"energia-2.s4.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una heladera usa 1.500 kWh más que otra en toda su vida. Si el kWh cuesta $150, ¿cuántos pesos más cuesta usarla?","unidad":"$","decimales":0},"solucion":{"valor":225000,"tolerancia":4500,"explicacion":"1.500 × 150 = $225.000. Ese es el \"precio escondido\" de la heladera menos eficiente."}},{"slug":"energia-2.s4.p7","orden":7,"grupo":"energia-2.s4.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos aparatos tienen la misma letra de eficiencia, consumen lo mismo.","razones":[{"id":"r1","texto":"Porque el consumo también depende del tamaño y las funciones"},{"id":"r2","texto":"Porque la letra indica el consumo exacto"},{"id":"r3","texto":"Porque las etiquetas no dicen el consumo"}]},"solucion":{"valor":false,"explicacion":"La letra compara con aparatos de su tipo y tamaño. Una heladera grande clase A puede consumir más que una chica clase A. Para comparar, el número de kWh.","clave":["r1"]}},{"slug":"energia-2.s4.p8","orden":8,"grupo":"energia-2.s4.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene mirar antes de comprar un aire acondicionado? Marcá todo lo útil.","opciones":[{"id":"o1","texto":"La clase de eficiencia de la etiqueta"},{"id":"o2","texto":"El consumo de energía estimado"},{"id":"o3","texto":"Si es inverter"},{"id":"o4","texto":"Que la potencia sea adecuada al tamaño del ambiente"},{"id":"o5","texto":"Que sea el más potente disponible, por las dudas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un equipo sobredimensionado cuesta más, consume de más y prende y apaga seguido. Tamaño justo y eficiente."}},{"slug":"energia-2.s4.p9","orden":9,"grupo":"energia-2.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la etiqueta de eficiencia cambia un mercado entero.","items":[{"id":"i1","texto":"La etiqueta muestra cuánto consume cada aparato"},{"id":"i2","texto":"Los compradores eligen más los eficientes"},{"id":"i3","texto":"Los fabricantes compiten por mejores letras"},{"id":"i4","texto":"Los aparatos del mercado se vuelven más eficientes"},{"id":"i5","texto":"La etiqueta obliga a cada casa a consumir menos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La etiqueta no obliga a nadie, pero cambia lo que se elige, y eso cambia lo que se fabrica. Una palanca de sistema, como en el tronco."}},{"slug":"energia-2.s4.p10","orden":10,"grupo":"energia-2.s4.p10","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos aparatos por su costo total en 12 años, de más a menos. Precio de compra más energía a $100 por kWh.","items":[{"id":"i1","texto":"Heladera B: $500.000 y 500 kWh por año"},{"id":"i2","texto":"Heladera A: $700.000 y 300 kWh por año"},{"id":"i3","texto":"Heladera C: $800.000 y 200 kWh por año"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"La más barata en la vidriera es la más cara en la vida. Pasa seguido con los aparatos que funcionan todo el día.","valores":{"i1":"$1.100.000","i2":"$1.060.000","i3":"$1.040.000"}}},{"slug":"energia-2.s4.p11","orden":11,"grupo":"energia-2.s4.p11","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para qué aparato la etiqueta de eficiencia pesa más en la decisión?","grupos":[{"id":"g1","nombre":"Pesa mucho (funcionan muchas horas)"},{"id":"g2","nombre":"Pesa poco (funcionan pocas horas)"}],"items":[{"id":"i1","texto":"Heladera"},{"id":"i2","texto":"Secador de pelo"},{"id":"i3","texto":"Aire acondicionado"},{"id":"i4","texto":"Batidora"},{"id":"i5","texto":"Termotanque"},{"id":"i6","texto":"Tostadora"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Cuanto más horas funciona un aparato, más importa su eficiencia. En los que se usan minutos, casi no cambia la cuenta."}},{"slug":"energia-2.s4.p12","orden":12,"grupo":"energia-2.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé lo que dice un vendedor y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Esta heladera es clase A y consume 280 kWh por año."},{"id":"s2","texto":"La otra es más barata, así que es la que más le conviene."},{"id":"s3","texto":"La etiqueta es obligatoria para las heladeras."},{"id":"s4","texto":"Todas las clase A consumen exactamente lo mismo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El precio de vidriera y la letra sola pueden engañar. El kWh por año, no.","por_opcion":{"s2":"Hay que sumar la energía de toda su vida, no solo el precio.","s4":"La letra depende del tipo y tamaño; el consumo en kWh puede variar."}}},{"slug":"energia-2.s4.p13","orden":13,"grupo":"energia-2.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un aparato se paga al {{0}} y cada mes en la {{1}}; por eso conviene comparar el costo {{2}}.","banco":[{"id":"w1","texto":"comprarlo"},{"id":"w2","texto":"factura"},{"id":"w3","texto":"total"},{"id":"w4","texto":"venderlo"},{"id":"w5","texto":"garantía"},{"id":"w6","texto":"inicial"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea del costo de toda la vida, en una línea."}}]},{"slug":"energia-2.s5","orden":5,"tipo":"leccion","titulo_es":"Calor y frío sin derrochar","bajada_es":"Termostatos, burletes, cortinas y sol: cómo estar a gusto usando mucha menos energía.","minutos":12,"pasos":[{"slug":"energia-2.s5.p1","orden":1,"grupo":"energia-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa como un balde con agujeros","cuerpo":["Calefaccionar en invierno es como llenar un balde con agujeros: el calor se escapa por el techo, las paredes, las ventanas y las rendijas. La estufa repone lo que se pierde. Tapar agujeros es más efectivo que poner una estufa más grande.","Las rendijas de puertas y ventanas dejan entrar aire frío; los burletes las cierran. Los techos sin aislar pierden mucho calor, porque el aire caliente sube. Las ventanas de vidrio simple pierden más que las paredes."]},"solucion":{}},{"slug":"energia-2.s5.p2","orden":2,"grupo":"energia-2.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Por dónde se escapa el calor de una casa en invierno? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Por el techo, sobre todo si no está aislado"},{"id":"o2","texto":"Por las rendijas de puertas y ventanas"},{"id":"o3","texto":"Por los vidrios simples de las ventanas"},{"id":"o4","texto":"Por las paredes"},{"id":"o5","texto":"Por las lámparas LED encendidas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Techo, paredes, ventanas y rendijas: los cuatro agujeros del balde."}},{"slug":"energia-2.s5.p3","orden":3,"grupo":"energia-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La temperatura justa","cuerpo":["La temperatura a la que se pone la calefacción importa mucho: cuanto más diferencia hay entre adentro y afuera, más rápido se escapa el calor. Se suele recomendar alrededor de 20 °C en invierno y, para el aire acondicionado, alrededor de 24 °C en verano.","Cada grado de más en la calefacción, o de menos en el aire, aumenta el consumo en varios puntos porcentuales. Abrigarse un poco más adentro o usar ventilador junto con el aire son cambios chicos con efecto grande."],"destacado":{"valor":"20 °C / 24 °C","texto":"son las temperaturas recomendadas para calefacción en invierno y aire en verano."}},"solucion":{}},{"slug":"energia-2.s5.p4","orden":4,"grupo":"energia-2.s5.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué cuesta más energía mantener la casa a 24 °C que a 20 °C en invierno?","opciones":[{"id":"o1","texto":"Porque con más diferencia, el calor se escapa más rápido"},{"id":"o2","texto":"Porque a más de 20 °C las estufas funcionan peor y se rompen"},{"id":"o3","texto":"Porque el aire caliente pesa más"},{"id":"o4","texto":"Porque la tarifa de gas se cobra más cara arriba de 20 °C"}]},"solucion":{"clave":["o1"],"explicacion":"La pérdida de calor crece con la diferencia de temperatura. Cuatro grados más pueden significar un aumento importante del consumo.","por_opcion":{"o3":"El aire caliente es más liviano y sube; lo que importa es la diferencia de temperatura."}}},{"slug":"energia-2.s5.p5","orden":5,"grupo":"energia-2.s5.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Poner el aire acondicionado a 17 °C enfría la habitación más rápido que ponerlo a 24 °C.","razones":[{"id":"r1","texto":"Porque la velocidad es la misma; solo sigue enfriando hasta más abajo"},{"id":"r2","texto":"Porque a 17 °C el equipo se apaga solo"},{"id":"r3","texto":"Porque a 24 °C el equipo no enfría"}]},"solucion":{"valor":false,"explicacion":"La mayoría de los equipos enfría a la misma velocidad; lo que cambia es hasta dónde sigue enfriando. A 17 °C sigue trabajando mucho más tiempo y gasta mucho más.","clave":["r1"]}},{"slug":"energia-2.s5.p6","orden":6,"grupo":"energia-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol como aliado","cuerpo":["En invierno, abrir cortinas en las ventanas donde da el sol durante el día deja entrar calor gratis; cerrarlas al atardecer ayuda a que no se escape. En verano, al revés: cerrar persianas y cortinas donde da el sol evita que la casa se caliente, y ventilar de noche con aire más fresco la enfría.","Árboles de hoja caduca del lado del sol dan sombra en verano y dejan pasar el sol en invierno. Es un ejemplo de diseño que trabaja con el clima en vez de contra él."]},"solucion":{}},{"slug":"energia-2.s5.p7","orden":7,"grupo":"energia-2.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida es para invierno o para verano?","grupos":[{"id":"g1","nombre":"Invierno"},{"id":"g2","nombre":"Verano"}],"items":[{"id":"i1","texto":"Abrir cortinas donde da el sol de día"},{"id":"i2","texto":"Cerrar persianas donde da el sol"},{"id":"i3","texto":"Cerrar cortinas gruesas al atardecer"},{"id":"i4","texto":"Ventilar de noche con aire fresco"},{"id":"i5","texto":"Colocar burletes en las ventanas"},{"id":"i6","texto":"Usar ventilador de techo con el aire a 24 °C"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las mismas cortinas y ventanas sirven en las dos estaciones, usadas al revés."}},{"slug":"energia-2.s5.p8","orden":8,"grupo":"energia-2.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un burlete ahorra gas.","items":[{"id":"i1","texto":"El burlete tapa la rendija de la ventana"},{"id":"i2","texto":"Entra menos aire frío de afuera"},{"id":"i3","texto":"La habitación pierde menos calor"},{"id":"i4","texto":"La estufa funciona menos tiempo para mantener la temperatura"},{"id":"i5","texto":"Se quema menos gas"},{"id":"i6","texto":"El burlete calienta el aire de la habitación"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una medida barata que actúa sobre la pérdida, no sobre la fuente. Tapar agujeros del balde."}},{"slug":"energia-2.s5.p9","orden":9,"grupo":"energia-2.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su solución.","izquierda":[{"id":"a1","texto":"Rendijas en la puerta"},{"id":"a2","texto":"Techo sin aislar"},{"id":"a3","texto":"Sol fuerte en verano sobre la ventana"},{"id":"a4","texto":"Aire acondicionado a 18 °C"}],"derecha":[{"id":"b1","texto":"Burlete"},{"id":"b2","texto":"Aislante en el entretecho"},{"id":"b3","texto":"Persiana o toldo exterior"},{"id":"b4","texto":"Subirlo a 24 °C y usar ventilador"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada pérdida tiene su tapón. Algunos son gratis, otros una inversión."}},{"slug":"energia-2.s5.p10","orden":10,"grupo":"energia-2.s5.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ventilar sin tirar el calor","cuerpo":["Ventilar es necesario: renueva el aire, saca humedad y, con estufas a gas, es una cuestión de seguridad. Las estufas y calefones que no son de tiro balanceado necesitan ventilación permanente, porque pueden producir monóxido de carbono, un gas invisible y mortal.","Para ventilar sin perder calor conviene abrir bien las ventanas durante unos pocos minutos, en vez de dejarlas entreabiertas durante horas."]},"solucion":{}},{"slug":"energia-2.s5.p11","orden":11,"grupo":"energia-2.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la forma más eficiente de ventilar una habitación en invierno?","opciones":[{"id":"o1","texto":"Abrir bien la ventana unos pocos minutos"},{"id":"o2","texto":"Dejar la ventana entreabierta toda la tarde"},{"id":"o3","texto":"No ventilar nunca para no perder calor"},{"id":"o4","texto":"Abrir la puerta de entrada durante una hora"}]},"solucion":{"clave":["o1"],"explicacion":"Unos minutos con la ventana bien abierta renuevan el aire sin enfriar paredes y muebles, que guardan el calor.","por_opcion":{"o3":"Ventilar es necesario por la salud, y con estufas a gas, por seguridad."}}},{"slug":"energia-2.s5.p12","orden":12,"grupo":"energia-2.s5.p12","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una casa tiene estufas a gas que no son de tiro balanceado, tapar todas las rejillas de ventilación es una buena forma de ahorrar.","razones":[{"id":"r1","texto":"Porque sin ventilación se puede acumular monóxido de carbono"},{"id":"r2","texto":"Porque las rejillas no dejan pasar aire"},{"id":"r3","texto":"Porque tapar rejillas aumenta el consumo de luz"}]},"solucion":{"valor":false,"explicacion":"Es peligroso: esas estufas necesitan aire y pueden producir monóxido de carbono. Las rejillas de ventilación nunca se tapan.","clave":["r1"]}},{"slug":"energia-2.s5.p13","orden":13,"grupo":"energia-2.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los que son peligrosos o equivocados.","segmentos":[{"id":"s1","texto":"Poné burletes en las ventanas antes del invierno."},{"id":"s2","texto":"Tapá las rejillas de ventilación para que no entre frío."},{"id":"s3","texto":"Poné el aire a 16 °C para que enfríe más rápido."},{"id":"s4","texto":"Cerrá persianas donde da el sol en verano."}]},"solucion":{"clave":["s2","s3"],"explicacion":"Ahorrar energía nunca a costa de la seguridad: las rejillas no se tocan.","por_opcion":{"s2":"Las rejillas son obligatorias con artefactos a gas: evitan intoxicaciones por monóxido de carbono.","s3":"No enfría más rápido: solo sigue enfriando más y gasta mucho más."}}},{"slug":"energia-2.s5.p14","orden":14,"grupo":"energia-2.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Se recomienda calefaccionar a unos {{0}} °C y usar el aire a unos {{1}} °C; cada grado de diferencia {{2}} el consumo.","banco":[{"id":"w1","texto":"20"},{"id":"w2","texto":"24"},{"id":"w3","texto":"aumenta"},{"id":"w4","texto":"26"},{"id":"w5","texto":"16"},{"id":"w6","texto":"reduce"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Dos números para recordar y una regla general."}}]},{"slug":"energia-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la energía en casa","bajada_es":"Usos, aparatos, factura, etiqueta y clima de la casa, mezclados.","minutos":8,"pasos":[{"slug":"energia-2.s6.p1","orden":1,"grupo":"energia-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La energía en casa». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la factura de los Giménez","bajada_es":"Una familia de Rosario recibe una factura de verano muy alta. Encontrá dónde se va la energía y armá el plan.","minutos":10,"pasos":[{"slug":"energia-2.s7.p1","orden":1,"grupo":"energia-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa de los Giménez","cuerpo":["Los Giménez son cuatro. Su factura de enero marca 540 kWh en 30 días; la de enero del año anterior, 450 kWh en 30 días. Este año compraron un segundo aire acondicionado de 1.200 W que usan 6 horas por día, y lo ponen a 18 °C.","Su heladera tiene 18 años y según una medición consume 2 kWh por día. En la casa hay un televisor, un decodificador, una consola y dos cargadores enchufados todo el tiempo, con unos 40 W de stand-by en total."]},"solucion":{}},{"slug":"energia-2.s7.p2","orden":2,"grupo":"energia-2.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por mes usa el segundo aire acondicionado? (30 días)","unidad":"kWh","decimales":0,"contexto":"Aire de 1.200 W, 6 horas por día, 30 días."},"solucion":{"valor":216,"tolerancia":4.32,"explicacion":"1,2 kW × 6 h × 30 días = 216 kWh por mes. Solo ese equipo es casi la mitad de la factura."}},{"slug":"energia-2.s7.p3","orden":3,"grupo":"energia-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje subió el consumo respecto de enero del año anterior?","unidad":"%","decimales":0,"contexto":"Enero pasado: 450 kWh. Este enero: 540 kWh. Mismos días."},"solucion":{"valor":20,"tolerancia":0.5,"explicacion":"Subió 540 − 450 = 90 kWh sobre 450: 90 ÷ 450 × 100 = 20 %."}},{"slug":"energia-2.s7.p4","orden":4,"grupo":"energia-2.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por mes usa el stand-by de la casa? (40 W, 30 días de 24 horas)","unidad":"kWh","decimales":1,"contexto":"40 W de stand-by constante."},"solucion":{"valor":28.8,"tolerancia":0.5760000000000001,"explicacion":"0,04 kW × 24 h × 30 = 28,8 kWh por mes. Casi lo mismo que una heladera nueva y eficiente."}},{"slug":"energia-2.s7.p5","orden":5,"grupo":"energia-2.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas posibles según cuántos kWh por mes ahorrarían, de más a menos (estimaciones).","items":[{"id":"i1","texto":"Subir los aires de 18 °C a 24 °C y cerrar persianas"},{"id":"i2","texto":"Cambiar la heladera vieja (2 kWh/día) por una de 1 kWh/día"},{"id":"i3","texto":"Cortar el stand-by con una zapatilla con interruptor"},{"id":"i4","texto":"Cambiar las 3 lámparas que quedaban por LED"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El aire es el gigante del verano. La heladera y el stand-by vienen después y suman. Las lámparas, al final.","valores":{"i1":"≈ 60-90 kWh","i2":"≈ 30 kWh","i3":"≈ 20-25 kWh","i4":"≈ 5 kWh"}}},{"slug":"energia-2.s7.p6","orden":6,"grupo":"energia-2.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La familia quiere un solo cambio para este mismo mes, sin gastar plata. ¿Cuál conviene?","opciones":[{"id":"o1","texto":"Aires a 24 °C y persianas cerradas de día"},{"id":"o2","texto":"Comprar una heladera nueva de clase A esta semana"},{"id":"o3","texto":"Cambiar todas las lámparas a LED"},{"id":"o4","texto":"Instalar paneles solares en todo el techo de la casa"}]},"solucion":{"clave":["o1"],"explicacion":"Sin gastar plata y con efecto inmediato: el termostato y las persianas atacan el uso más grande del verano.","por_opcion":{"o3":"Ya casi todas son LED: el ahorro sería mínimo comparado con el aire."}}},{"slug":"energia-2.s7.p7","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $100, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":36500,"tolerancia":730,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $100 = $36.500 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p7.v2","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $120, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":43800,"tolerancia":876,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $120 = $43.800 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p7.v3","orden":7,"grupo":"energia-2.s7.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La heladera vieja consume 2 kWh por día y una nueva consumiría 1 kWh por día. Con el kWh a $150, ¿cuántos pesos por año ahorraría la nueva? (365 días)","unidad":"$","decimales":0},"solucion":{"valor":54750,"tolerancia":1095,"explicacion":"Ahorra 1 kWh por día: 365 kWh por año × $150 = $54.750 por año. En 10 años de vida útil, diez veces eso."}},{"slug":"energia-2.s7.p8","orden":8,"grupo":"energia-2.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La familia escribe su plan. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Vamos a poner los aires a 24 °C y usar el ventilador de techo."},{"id":"s2","texto":"Desenchufamos la heladera de noche para compensar."},{"id":"s3","texto":"Juntamos los aparatos del stand-by en una zapatilla con interruptor."},{"id":"s4","texto":"Comparamos la próxima factura con la de diciembre para ver el ahorro."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan ataca el uso grande, no pone en riesgo la comida y se verifica comparando bien.","por_opcion":{"s2":"Se corta el frío, se arruina la comida y al volver consume más.","s4":"Hay que comparar con el mismo mes del año anterior y en kWh por día."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-3","rama":"energia","orden":3,"nivel":2,"titulo_es":"De dónde sale la electricidad","bajada_es":"Detrás de cada enchufe hay turbinas, represas, parques eólicos, centrales nucleares y miles de kilómetros de cables. Cómo funciona el sistema que te da luz.","objetivos_es":["Explicar cómo se genera electricidad con distintas fuentes","Describir la matriz eléctrica argentina y cómo cambia","Seguir el recorrido de la electricidad por la red de transmisión y distribución","Interpretar la curva de demanda y el problema de los picos","Calcular las emisiones de un consumo eléctrico con un factor de emisión"],"repasa":["energia-1","energia-2","tronco-2"],"requiere_tronco":2,"fuentes":["cammesa","iea-energia","owid-energia","ley-27424-generacion","irena"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-3.s1","orden":1,"tipo":"leccion","titulo_es":"Cómo se genera la electricidad","bajada_es":"Turbinas, generadores y paneles: las distintas formas de convertir energía en electricidad.","minutos":11,"pasos":[{"slug":"energia-3.s1.p1","orden":1,"grupo":"energia-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hacer girar un imán","cuerpo":["Casi toda la electricidad del mundo se produce igual: algo hace girar una turbina, y la turbina mueve un generador, donde un imán gira dentro de bobinas de cobre y produce corriente eléctrica. Lo que cambia es qué hace girar la turbina.","En una central térmica, es el vapor o los gases calientes de quemar gas, carbón o gasoil. En una represa, el agua que cae. En un aerogenerador, el viento. En una central nuclear, el vapor calentado por la fisión del uranio."]},"solucion":{}},{"slug":"energia-3.s1.p2","orden":2,"grupo":"energia-3.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada central con lo que hace girar su turbina.","izquierda":[{"id":"a1","texto":"Central térmica a gas"},{"id":"a2","texto":"Represa hidroeléctrica"},{"id":"a3","texto":"Aerogenerador"},{"id":"a4","texto":"Central nuclear"}],"derecha":[{"id":"b1","texto":"Gases calientes de la combustión"},{"id":"b2","texto":"Agua que cae"},{"id":"b3","texto":"Viento"},{"id":"b4","texto":"Vapor calentado por la fisión del uranio"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas fuentes, un mismo principio: hacer girar un generador."}},{"slug":"energia-3.s1.p3","orden":3,"grupo":"energia-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La excepción: el panel solar","cuerpo":["Los paneles solares fotovoltaicos no tienen turbina ni partes que giren: la luz del sol, al llegar a un material semiconductor como el silicio, libera electrones y genera corriente directamente. Por eso casi no tienen mantenimiento mecánico y se pueden instalar en un techo.","La corriente de los paneles es continua; un equipo llamado inversor la transforma en corriente alterna, la que usa la red."]},"solucion":{}},{"slug":"energia-3.s1.p4","orden":4,"grupo":"energia-3.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta forma de generar usa una turbina o no?","grupos":[{"id":"g1","nombre":"Usa turbina"},{"id":"g2","nombre":"No usa turbina"}],"items":[{"id":"i1","texto":"Central térmica de ciclo combinado"},{"id":"i2","texto":"Panel solar fotovoltaico en un techo"},{"id":"i3","texto":"Represa de Yacyretá"},{"id":"i4","texto":"Parque solar en la Puna"},{"id":"i5","texto":"Parque eólico"},{"id":"i6","texto":"Central nuclear Atucha II"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g1"},"explicacion":"La fotovoltaica es la gran excepción: convierte luz en electricidad sin movimiento."}},{"slug":"energia-3.s1.p5","orden":5,"grupo":"energia-3.s1.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un panel solar genera electricidad haciendo girar una pequeña turbina con el calor del sol.","razones":[{"id":"r1","texto":"Porque la luz genera corriente directamente en el semiconductor"},{"id":"r2","texto":"Porque los paneles tienen un motor adentro"},{"id":"r3","texto":"Porque los paneles queman el aire caliente"}]},"solucion":{"valor":false,"explicacion":"Los paneles fotovoltaicos no tienen partes móviles: la luz libera electrones en un semiconductor y eso genera corriente directamente.","clave":["r1"]}},{"slug":"energia-3.s1.p6","orden":6,"grupo":"energia-3.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una central térmica a gas.","items":[{"id":"i1","texto":"Se quema gas natural"},{"id":"i2","texto":"Los gases calientes hacen girar una turbina"},{"id":"i3","texto":"La turbina mueve el generador"},{"id":"i4","texto":"El generador produce electricidad"},{"id":"i5","texto":"La electricidad sale a la red de alta tensión"},{"id":"i6","texto":"El gas se convierte directamente en electricidad sin girar nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Química a calor, calor a movimiento, movimiento a electricidad: las transformaciones de la unidad 1."}},{"slug":"energia-3.s1.p7","orden":7,"grupo":"energia-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ciclo combinado","cuerpo":["Una central térmica común aprovecha alrededor de un tercio de la energía del combustible. Las de ciclo combinado usan los gases calientes para mover una turbina y, además, aprovechan el calor que queda para producir vapor y mover otra: así llegan a aprovechar alrededor del 55 al 60 %.","Por eso, con el mismo gas, una central de ciclo combinado produce mucha más electricidad y emite menos por kWh."]},"solucion":{}},{"slug":"energia-3.s1.p8","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 100 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":23,"tolerancia":0.46,"explicacion":"Común: 100 × 0,35 = 35. Ciclo combinado: 100 × 0,58 = 58. Diferencia: 23 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p8.v2","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 200 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":46,"tolerancia":0.92,"explicacion":"Común: 200 × 0,35 = 70. Ciclo combinado: 200 × 0,58 = 116. Diferencia: 46 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p8.v3","orden":8,"grupo":"energia-3.s1.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 150 unidades de energía de gas, ¿cuántas unidades más de electricidad produce una central de ciclo combinado (58 %) que una térmica común (35 %)?","unidad":"unidades","decimales":1},"solucion":{"valor":34.5,"tolerancia":0.6900000000000001,"explicacion":"Común: 150 × 0,35 = 52,5. Ciclo combinado: 150 × 0,58 = 87. Diferencia: 34,5 unidades más con el mismo gas."}},{"slug":"energia-3.s1.p9","orden":9,"grupo":"energia-3.s1.p9","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas centrales por la eficiencia típica con que convierten su fuente en electricidad, de más a menos.","items":[{"id":"i1","texto":"Represa hidroeléctrica"},{"id":"i2","texto":"Central de ciclo combinado"},{"id":"i3","texto":"Central térmica común"},{"id":"i4","texto":"Panel solar comercial"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La eficiencia no lo es todo: el sol es gratis e inagotable, aunque el panel aproveche una parte chica.","valores":{"i1":"≈ 85-90 %","i2":"≈ 55-60 %","i3":"≈ 30-40 %","i4":"≈ 20 % de la luz que recibe"}}},{"slug":"energia-3.s1.p10","orden":10,"grupo":"energia-3.s1.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué fuentes generan electricidad sin emitir CO₂ al funcionar? Marcá todas.","opciones":[{"id":"o1","texto":"Represa hidroeléctrica"},{"id":"o2","texto":"Parque eólico"},{"id":"o3","texto":"Central nuclear"},{"id":"o4","texto":"Paneles solares"},{"id":"o5","texto":"Central térmica a gas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Hidro, eólica, nuclear y solar no emiten CO₂ al generar, aunque todas tienen impactos al construirse."}},{"slug":"energia-3.s1.p11","orden":11,"grupo":"energia-3.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué equipo convierte la corriente continua de los paneles solares en la corriente alterna de la red?","opciones":[{"id":"o1","texto":"El inversor"},{"id":"o2","texto":"El medidor de luz"},{"id":"o3","texto":"La turbina"},{"id":"o4","texto":"El disyuntor diferencial"}]},"solucion":{"clave":["o1"],"explicacion":"Sin inversor, la electricidad de los paneles no podría usarse en la casa ni volcarse a la red.","por_opcion":{"o3":"Los paneles no tienen turbina: la conversión la hace un equipo electrónico."}}},{"slug":"energia-3.s1.p12","orden":12,"grupo":"energia-3.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En una represa, el agua que cae hace girar una turbina."},{"id":"s2","texto":"Las centrales nucleares queman uranio como si fuera carbón."},{"id":"s3","texto":"Los aerogeneradores convierten el viento en movimiento y luego en electricidad."},{"id":"s4","texto":"Una central de ciclo combinado es menos eficiente que una térmica común."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo funciona cada central ayuda a entender sus ventajas y límites.","por_opcion":{"s2":"No hay combustión: la fisión del uranio libera calor que produce vapor.","s4":"Es más eficiente: aprovecha el calor dos veces."}}},{"slug":"energia-3.s1.p13","orden":13,"grupo":"energia-3.s1.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Casi toda la electricidad se genera haciendo girar un {{0}}; los paneles solares son la excepción porque convierten la {{1}} directamente; y el {{2}} adapta su corriente a la red.","banco":[{"id":"w1","texto":"generador"},{"id":"w2","texto":"luz"},{"id":"w3","texto":"inversor"},{"id":"w4","texto":"motor"},{"id":"w5","texto":"calor"},{"id":"w6","texto":"medidor"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El principio de la generación y su gran excepción."}}]},{"slug":"energia-3.s2","orden":2,"tipo":"leccion","titulo_es":"La matriz eléctrica argentina","bajada_es":"Gas, represas, uranio, viento y sol: de qué está hecha la electricidad del país y cómo cambia.","minutos":11,"pasos":[{"slug":"energia-3.s2.p1","orden":1,"grupo":"energia-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un sistema interconectado","cuerpo":["Casi todo el país está conectado al Sistema Argentino de Interconexión (SADI): una red de líneas de alta tensión que une centrales y ciudades de casi todas las provincias. CAMMESA es la empresa que administra ese sistema: decide, hora por hora, qué centrales generan para cubrir la demanda.","Así, la electricidad que llega a tu casa es una mezcla de lo que generan muchas centrales, a veces a cientos de kilómetros."]},"solucion":{}},{"slug":"energia-3.s2.p2","orden":2,"grupo":"energia-3.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"De qué está hecha","cuerpo":["En los últimos años, algo más de la mitad de la electricidad argentina salió de centrales térmicas, sobre todo a gas natural. Las grandes represas —como Yacyretá, Salto Grande, El Chocón o Piedra del Águila— aportaron una parte que cambia mucho según las lluvias. Las centrales nucleares Atucha I, Atucha II y Embalse aportaron alrededor de un 5 a 8 %. Y las renovables, sobre todo eólica y solar, crecieron rápido en la última década."],"datos":{"tipo":"barras","titulo":"Generación eléctrica en Argentina por fuente (aproximado, años recientes)","unidad":"% del total","filas":[{"etiqueta":"Térmica (sobre todo gas)","valor":57},{"etiqueta":"Hidráulica (grandes represas)","valor":18},{"etiqueta":"Renovables (eólica, solar y otras)","valor":17},{"etiqueta":"Nuclear","valor":8}],"nota":"Valores aproximados redondeados a partir de datos de CAMMESA; cambian cada año con las lluvias y la demanda."}},"solucion":{}},{"slug":"energia-3.s2.p3","orden":3,"grupo":"energia-3.s2.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese gráfico, ordená las fuentes por su aporte a la electricidad argentina, de más a menos.","items":[{"id":"i1","texto":"Térmica, sobre todo gas"},{"id":"i2","texto":"Hidráulica"},{"id":"i3","texto":"Renovables como eólica y solar"},{"id":"i4","texto":"Nuclear"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El gas sigue siendo la base del sistema. Las renovables ya aportan casi tanto como las grandes represas.","valores":{"i1":"≈ 57 %","i2":"≈ 18 %","i3":"≈ 17 %","i4":"≈ 8 %"}}},{"slug":"energia-3.s2.p4","orden":4,"grupo":"energia-3.s2.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la electricidad argentina viene de fuentes que no emiten CO₂ al generar (hidráulica, nuclear y renovables), según ese gráfico.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":43,"banda":"lineal","explicacion":"18 + 8 + 17 = 43 %. Algo más de cuatro de cada diez kWh."}},{"slug":"energia-3.s2.p5","orden":5,"grupo":"energia-3.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada central con su fuente.","izquierda":[{"id":"a1","texto":"Yacyretá"},{"id":"a2","texto":"Atucha II"},{"id":"a3","texto":"Parques eólicos de Chubut"},{"id":"a4","texto":"Cauchari, en Jujuy"}],"derecha":[{"id":"b1","texto":"Agua del río Paraná"},{"id":"b2","texto":"Uranio"},{"id":"b3","texto":"Viento patagónico"},{"id":"b4","texto":"Sol de la Puna"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una geografía diversa: agua en el noreste, viento en el sur, sol en el noroeste."}},{"slug":"energia-3.s2.p6","orden":6,"grupo":"energia-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué cambia de un año a otro","cuerpo":["La matriz no es fija. En años secos, las represas generan menos y hay que quemar más gas, como pasó durante la bajante del Paraná. En años lluviosos, al revés. Las renovables crecen por las leyes que las promueven y porque se abarataron: la Ley 27.191 fijó metas de participación de renovables, y la Ley 27.424 habilitó a usuarios a generar su propia energía y volcar excedentes a la red."]},"solucion":{}},{"slug":"energia-3.s2.p7","orden":7,"grupo":"energia-3.s2.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué una sequía puede aumentar las emisiones de la electricidad.","items":[{"id":"i1","texto":"Llueve poco en la cuenca de los ríos"},{"id":"i2","texto":"Las represas generan menos electricidad"},{"id":"i3","texto":"CAMMESA despacha más centrales térmicas"},{"id":"i4","texto":"Se quema más gas"},{"id":"i5","texto":"Suben las emisiones por kWh"},{"id":"i6","texto":"Las represas emiten más CO₂ en la sequía"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Agua y energía están conectadas: la bajante del río se nota en la matriz eléctrica."}},{"slug":"energia-3.s2.p8","orden":8,"grupo":"energia-3.s2.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La matriz eléctrica argentina es siempre la misma, año tras año.","razones":[{"id":"r1","texto":"Porque depende de las lluvias, la demanda y las nuevas centrales"},{"id":"r2","texto":"Porque la ley fija un porcentaje exacto de cada fuente"},{"id":"r3","texto":"Porque solo hay centrales a gas"}]},"solucion":{"valor":false,"explicacion":"Cambia con las lluvias (más o menos hidro), con la demanda y con las nuevas centrales renovables que se suman.","clave":["r1"]}},{"slug":"energia-3.s2.p9","orden":9,"grupo":"energia-3.s2.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace CAMMESA? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Administra el mercado eléctrico mayorista"},{"id":"o2","texto":"Decide qué centrales generan en cada momento"},{"id":"o3","texto":"Publica datos de generación y demanda"},{"id":"o4","texto":"Construye todos los paneles solares de las casas"},{"id":"o5","texto":"Factura directamente la luz de cada hogar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"CAMMESA administra el sistema; las facturas de las casas las emiten las distribuidoras."}},{"slug":"energia-3.s2.p10","orden":10,"grupo":"energia-3.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué establece la Ley 27.424 de generación distribuida?","opciones":[{"id":"o1","texto":"Que los usuarios generen renovable y vuelquen excedentes"},{"id":"o2","texto":"Que todas las casas deben tener paneles solares por obligación"},{"id":"o3","texto":"Que se prohíben las centrales térmicas"},{"id":"o4","texto":"Que la electricidad es gratuita para quienes tienen paneles"}]},"solucion":{"clave":["o1"],"explicacion":"Un usuario con paneles puede consumir su propia energía y entregar lo que sobra a la red.","por_opcion":{"o3":"No prohíbe centrales: habilita a los usuarios a generar y conectarse a la red."}}},{"slug":"energia-3.s2.p11","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 17 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":23.8,"tolerancia":0.47600000000000003,"explicacion":"140 × 17 ÷ 100 = 23,8 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p11.v2","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 15 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":21,"tolerancia":0.42,"explicacion":"140 × 15 ÷ 100 = 21 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p11.v3","orden":11,"grupo":"energia-3.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina genera unos 140 TWh de electricidad por año y las renovables aportan el 20 %, ¿cuántos TWh aportan?","unidad":"TWh","decimales":1},"solucion":{"valor":28,"tolerancia":0.56,"explicacion":"140 × 20 ÷ 100 = 28 TWh: el consumo de millones de hogares, sin quemar combustible."}},{"slug":"energia-3.s2.p12","orden":12,"grupo":"energia-3.s2.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad que llega a tu casa sale siempre de la central más cercana.","razones":[{"id":"r1","texto":"Porque llega de un sistema interconectado con muchas centrales"},{"id":"r2","texto":"Porque cada barrio tiene su propia central"},{"id":"r3","texto":"Porque la electricidad no viaja por cables"}]},"solucion":{"valor":false,"explicacion":"Llega de un sistema interconectado: es una mezcla de lo que generan muchas centrales, algunas a cientos de kilómetros.","clave":["r1"]}},{"slug":"energia-3.s2.p13","orden":13,"grupo":"energia-3.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Buena parte de la electricidad argentina se genera con gas."},{"id":"s2","texto":"Las represas generan siempre lo mismo, llueva o no."},{"id":"s3","texto":"Argentina tiene tres centrales nucleares en funcionamiento."},{"id":"s4","texto":"Las renovables todavía no generan nada relevante en el país."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer la matriz permite entender el impacto de cada kWh que usamos.","por_opcion":{"s2":"Dependen de las lluvias: en sequías generan menos.","s4":"Ya aportan una parte importante, que creció rápido en la última década."}}},{"slug":"energia-3.s2.p14","orden":14,"grupo":"energia-3.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El sistema que conecta centrales y ciudades se llama {{0}}; lo administra {{1}}; y la fuente que más electricidad aporta en Argentina es el {{2}}.","banco":[{"id":"w1","texto":"SADI"},{"id":"w2","texto":"CAMMESA"},{"id":"w3","texto":"gas"},{"id":"w4","texto":"ENARGAS"},{"id":"w5","texto":"INTA"},{"id":"w6","texto":"carbón"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender la electricidad del país."}}]},{"slug":"energia-3.s3","orden":3,"tipo":"leccion","titulo_es":"La red: del generador al enchufe","bajada_es":"Alta tensión, transformadores, distribuidoras y pérdidas: el viaje de la electricidad.","minutos":11,"pasos":[{"slug":"energia-3.s3.p1","orden":1,"grupo":"energia-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Subir la tensión para viajar","cuerpo":["La electricidad viaja desde las centrales por líneas de alta tensión: cientos de miles de voltios. ¿Por qué tan alta? Porque a mayor tensión, para la misma potencia, circula menos corriente, y los cables se calientan menos: se pierde menos energía en el camino.","Cerca de las ciudades, las subestaciones bajan la tensión con transformadores, y las distribuidoras la llevan por la red de media y baja tensión hasta las casas, donde llega a 220 voltios."]},"solucion":{}},{"slug":"energia-3.s3.p2","orden":2,"grupo":"energia-3.s3.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido de la electricidad desde la central hasta tu casa.","items":[{"id":"i1","texto":"Se genera en la central"},{"id":"i2","texto":"Un transformador eleva la tensión"},{"id":"i3","texto":"Viaja por líneas de alta tensión"},{"id":"i4","texto":"Una subestación la baja cerca de la ciudad"},{"id":"i5","texto":"La distribuidora la lleva por el barrio hasta tu casa"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Subir para viajar lejos, bajar para usar. Transformadores en los dos extremos."}},{"slug":"energia-3.s3.p3","orden":3,"grupo":"energia-3.s3.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la electricidad viaja largas distancias en alta tensión?","opciones":[{"id":"o1","texto":"Porque así se pierde menos energía en los cables"},{"id":"o2","texto":"Porque así llega más rápido a las casas"},{"id":"o3","texto":"Porque los cables de alta tensión son más baratos"},{"id":"o4","texto":"Porque las casas usan alta tensión"}]},"solucion":{"clave":["o1"],"explicacion":"Menos corriente, menos calentamiento del cable, menos pérdidas.","por_opcion":{"o3":"El motivo principal es reducir las pérdidas, no el costo del cable."}}},{"slug":"energia-3.s3.p4","orden":4,"grupo":"energia-3.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las pérdidas","cuerpo":["Aun así, una parte de la energía se pierde en el camino: como calor en cables y transformadores (pérdidas técnicas) y, en algunos lugares, por conexiones irregulares o medidores que fallan (pérdidas no técnicas). En total, una parte relevante de la electricidad generada no llega a facturarse.","Por eso cada kWh que se ahorra en casa ahorra algo más en la central: también se evitan las pérdidas de transportarlo."]},"solucion":{}},{"slug":"energia-3.s3.p5","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 100 MWh y en la red se pierde el 10 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"100 × 0.9 = 90 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p5.v2","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 250 MWh y en la red se pierde el 12 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":220,"tolerancia":4.4,"explicacion":"250 × 0.88 = 220 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p5.v3","orden":5,"grupo":"energia-3.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central genera 500 MWh y en la red se pierde el 8 %. ¿Cuántos MWh llegan a los usuarios?","unidad":"MWh","decimales":1},"solucion":{"valor":460,"tolerancia":9.200000000000001,"explicacion":"500 × 0.92 = 460 MWh. Las pérdidas son energía generada, con sus emisiones, que no usa nadie."}},{"slug":"energia-3.s3.p6","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 10 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 100 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":111.1,"tolerancia":0.2,"explicacion":"100 ÷ 0,9 ≈ 111,1 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p6.v2","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 10 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 90 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":100,"tolerancia":0.2,"explicacion":"90 ÷ 0,9 ≈ 100 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p6.v3","orden":6,"grupo":"energia-3.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en la red se pierde el 20 % de lo generado, ¿cuántos kWh hay que generar para que lleguen 200 kWh a una casa? Redondeá a un decimal.","unidad":"kWh","decimales":1},"solucion":{"valor":250,"tolerancia":0.2,"explicacion":"200 ÷ 0,8 ≈ 250 kWh. Por eso ahorrar en casa ahorra un poco más en la central."}},{"slug":"energia-3.s3.p7","orden":7,"grupo":"energia-3.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una pérdida técnica o no técnica?","grupos":[{"id":"g1","nombre":"Técnica"},{"id":"g2","nombre":"No técnica"}],"items":[{"id":"i1","texto":"Calor en los cables de alta tensión"},{"id":"i2","texto":"Una conexión irregular a la red"},{"id":"i3","texto":"Calentamiento de un transformador"},{"id":"i4","texto":"Un medidor que registra de menos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las técnicas se reducen con mejor infraestructura; las no técnicas, con control y acceso formal al servicio."}},{"slug":"energia-3.s3.p8","orden":8,"grupo":"energia-3.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cortes y confiabilidad","cuerpo":["Un sistema eléctrico tiene que equilibrar en cada instante lo que se genera con lo que se consume. Si una línea importante se cae o la demanda supera lo disponible, puede haber cortes. En días de calor extremo, las redes de distribución de los barrios, sobrecargadas por miles de aires acondicionados, son las que más fallan."]},"solucion":{}},{"slug":"energia-3.s3.p9","orden":9,"grupo":"energia-3.s3.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué hay cortes en los barrios en una ola de calor.","items":[{"id":"i1","texto":"Hace muchísimo calor varios días seguidos"},{"id":"i2","texto":"Miles de aires acondicionados funcionan a la vez"},{"id":"i3","texto":"Los cables y transformadores del barrio se sobrecargan"},{"id":"i4","texto":"Se calientan y se dañan"},{"id":"i5","texto":"Se corta la luz en el barrio"},{"id":"i6","texto":"El calor hace que las centrales dejen de existir"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchas veces el problema no es la generación, sino la distribución local."}},{"slug":"energia-3.s3.p10","orden":10,"grupo":"energia-3.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Ahorrar energía en casa en un día de calor extremo puede ayudar a evitar cortes en el barrio.","razones":[{"id":"r1","texto":"Porque alivia la carga de la red del barrio en las horas pico"},{"id":"r2","texto":"Porque la red no tiene límites"},{"id":"r3","texto":"Porque los cortes solo dependen de las centrales"}]},"solucion":{"valor":true,"explicacion":"Si muchos vecinos bajan su consumo en las horas pico, por ejemplo con el aire a 24 °C, se alivia la carga de los transformadores del barrio.","clave":["r1"]}},{"slug":"energia-3.s3.p11","orden":11,"grupo":"energia-3.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la red con su función.","izquierda":[{"id":"a1","texto":"Línea de alta tensión"},{"id":"a2","texto":"Subestación"},{"id":"a3","texto":"Distribuidora"},{"id":"a4","texto":"Transformador del barrio"}],"derecha":[{"id":"b1","texto":"Transportar energía a larga distancia"},{"id":"b2","texto":"Bajar la tensión cerca de las ciudades"},{"id":"b3","texto":"Llevar la electricidad hasta cada casa y facturar"},{"id":"b4","texto":"Adaptar la tensión para las casas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada parte de la red cumple su función en la cadena."}},{"slug":"energia-3.s3.p12","orden":12,"grupo":"energia-3.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La electricidad viaja en alta tensión para perder menos energía."},{"id":"s2","texto":"Toda la electricidad que se genera llega a las casas sin pérdidas."},{"id":"s3","texto":"En olas de calor, las redes de los barrios pueden sobrecargarse."},{"id":"s4","texto":"Las casas reciben la electricidad en alta tensión directamente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La red es tan importante como las centrales.","por_opcion":{"s2":"Una parte se pierde como calor en cables y transformadores, y por pérdidas no técnicas.","s4":"Llega a 220 voltios después de pasar por transformadores."}}},{"slug":"energia-3.s3.p13","orden":13,"grupo":"energia-3.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La electricidad viaja lejos en alta {{0}}; los {{1}} la adaptan; y una parte se {{2}} en el camino.","banco":[{"id":"w1","texto":"tensión"},{"id":"w2","texto":"transformadores"},{"id":"w3","texto":"pierde"},{"id":"w4","texto":"velocidad"},{"id":"w5","texto":"medidores"},{"id":"w6","texto":"multiplica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre el viaje de la electricidad."}}]},{"slug":"energia-3.s4","orden":4,"tipo":"leccion","titulo_es":"La demanda cambia cada hora","bajada_es":"La curva diaria, los picos de verano e invierno y por qué la electricidad tiene que generarse en el momento.","minutos":11,"pasos":[{"slug":"energia-3.s4.p1","orden":1,"grupo":"energia-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Generar al instante","cuerpo":["A diferencia del agua o el gas, la electricidad casi no se guarda en la red: tiene que generarse en el mismo instante en que se consume. Por eso el sistema sigue la demanda minuto a minuto, encendiendo y apagando centrales.","La demanda cambia a lo largo del día: baja de madrugada, sube a la mañana y tiene picos, que en Argentina suelen darse en las tardes y noches de verano muy caluroso, por el aire acondicionado, y en los días más fríos del invierno."]},"solucion":{}},{"slug":"energia-3.s4.p2","orden":2,"grupo":"energia-3.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos momentos de un día de verano caluroso por su demanda eléctrica típica, de menor a mayor.","items":[{"id":"i1","texto":"Madrugada, a las 5"},{"id":"i2","texto":"Mañana, a las 10"},{"id":"i3","texto":"Mediodía, a las 13"},{"id":"i4","texto":"Tarde-noche, a las 20"}],"extremos":["Menor demanda","Mayor demanda"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"En los días de mucho calor, el pico suele llegar a la tarde y primeras horas de la noche."}},{"slug":"energia-3.s4.p3","orden":3,"grupo":"energia-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Base y pico","cuerpo":["Algunas centrales generan casi todo el tiempo, cubriendo la demanda mínima: se las llama de base (por ejemplo, las nucleares). Otras se encienden solo en los picos: suelen ser térmicas más caras y, a veces, menos eficientes. Por eso los picos son los momentos más caros y a menudo los de más emisiones.","Bajar el pico —moviendo consumos a otras horas o ahorrando en esos momentos— evita encender las centrales más caras y contaminantes."]},"solucion":{}},{"slug":"energia-3.s4.p4","orden":4,"grupo":"energia-3.s4.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta central suele funcionar como base o para los picos?","grupos":[{"id":"g1","nombre":"Base"},{"id":"g2","nombre":"Picos"}],"items":[{"id":"i1","texto":"Central nuclear"},{"id":"i2","texto":"Turbina de gas que se enciende rápido"},{"id":"i3","texto":"Represa de pasada que genera con el caudal del río"},{"id":"i4","texto":"Motores diésel de emergencia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Las de base generan parejo; las de pico se prenden y apagan según la demanda."}},{"slug":"energia-3.s4.p5","orden":5,"grupo":"energia-3.s4.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el pico de demanda suele ser el momento más contaminante.","items":[{"id":"i1","texto":"La demanda sube en la tarde de un día caluroso"},{"id":"i2","texto":"Las centrales de base ya están a pleno"},{"id":"i3","texto":"Se encienden centrales de pico"},{"id":"i4","texto":"Suelen ser térmicas menos eficientes"},{"id":"i5","texto":"Cada kWh del pico emite más"},{"id":"i6","texto":"En el pico solo generan los paneles solares"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mover o reducir consumos en el pico tiene un efecto mayor que en otras horas."}},{"slug":"energia-3.s4.p6","orden":6,"grupo":"energia-3.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad se puede guardar en los cables para usarla en el pico.","razones":[{"id":"r1","texto":"Porque la red transporta pero no almacena"},{"id":"r2","texto":"Porque los cables son baterías gigantes"},{"id":"r3","texto":"Porque la electricidad no se usa en los picos"}]},"solucion":{"valor":false,"explicacion":"La red no almacena: hay que generar en el momento. Para guardar hacen falta baterías, represas de bombeo u otros sistemas.","clave":["r1"]}},{"slug":"energia-3.s4.p7","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 10.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 500 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"10.000 × 500 W = 5.000.000 W = 5 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p7.v2","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 50.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 400 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"50.000 × 400 W = 20.000.000 W = 20 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p7.v3","orden":7,"grupo":"energia-3.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una ciudad, 20.000 casas suben el aire de 18 °C a 24 °C en el pico y cada una baja 600 W su consumo. ¿Cuántos MW baja la demanda del pico?","unidad":"MW","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"20.000 × 600 W = 12.000.000 W = 12 MW. Lo que genera una central chica, sin construir nada."}},{"slug":"energia-3.s4.p8","orden":8,"grupo":"energia-3.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol y el pico","cuerpo":["La energía solar genera más al mediodía. En verano, ayuda a cubrir parte de la demanda de la tarde. Pero cuando el sol baja, la demanda sigue alta y la solar cae. Por eso, con mucha solar, se vuelve cada vez más importante almacenar energía del mediodía para la noche, o mover consumos hacia el mediodía."]},"solucion":{}},{"slug":"energia-3.s4.p9","orden":9,"grupo":"energia-3.s4.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada medida con cómo ayuda en el pico.","izquierda":[{"id":"a1","texto":"Poner el aire a 24 °C"},{"id":"a2","texto":"Programar el lavarropas de noche"},{"id":"a3","texto":"Baterías que se cargan al mediodía"},{"id":"a4","texto":"Tarifas más caras en el pico"}],"derecha":[{"id":"b1","texto":"Baja la demanda de cada casa"},{"id":"b2","texto":"Mueve un consumo fuera del pico"},{"id":"b3","texto":"Guardan energía solar para la noche"},{"id":"b4","texto":"Incentivan consumir en otras horas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Reducir, mover y almacenar: las tres formas de aliviar el pico."}},{"slug":"energia-3.s4.p10","orden":10,"grupo":"energia-3.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a bajar el pico de demanda en un día de calor? Marcá todo.","opciones":[{"id":"o1","texto":"Aire acondicionado a 24 °C"},{"id":"o2","texto":"Cerrar persianas donde da el sol"},{"id":"o3","texto":"Usar el lavarropas en otro horario"},{"id":"o4","texto":"Apagar aparatos que no se usan"},{"id":"o5","texto":"Encender todos los aires a 16 °C al llegar a casa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchas medidas chicas en muchas casas bajan mucho el pico."}},{"slug":"energia-3.s4.p11","orden":11,"grupo":"energia-3.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene poner el lavarropas de noche en lugar de a las 20 en un día muy caluroso?","opciones":[{"id":"o1","texto":"Porque se usa menos electricidad en el pico"},{"id":"o2","texto":"Porque de noche el lavarropas lava mejor"},{"id":"o3","texto":"Porque de noche la electricidad no tiene costo"},{"id":"o4","texto":"Porque de noche no se usa agua"}]},"solucion":{"clave":["o1"],"explicacion":"Mover consumos fuera del pico evita encender centrales caras y reduce el riesgo de cortes.","por_opcion":{"o3":"Puede ser más barata con tarifas horarias, pero no es gratis."}}},{"slug":"energia-3.s4.p12","orden":12,"grupo":"energia-3.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La demanda eléctrica cambia a lo largo del día."},{"id":"s2","texto":"El pico de demanda es a las 4 de la mañana."},{"id":"s3","texto":"En los picos se encienden centrales más caras."},{"id":"s4","texto":"Los paneles solares generan más de noche."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender la curva de demanda permite ahorrar donde más importa.","por_opcion":{"s2":"En los días calurosos, el pico suele ser a la tarde y primeras horas de la noche.","s4":"Generan más al mediodía y nada de noche."}}},{"slug":"energia-3.s4.p13","orden":13,"grupo":"energia-3.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La electricidad se genera en el mismo {{0}} en que se consume; las centrales de {{1}} funcionan siempre; y en el {{2}} se encienden las más caras.","banco":[{"id":"w1","texto":"instante"},{"id":"w2","texto":"base"},{"id":"w3","texto":"pico"},{"id":"w4","texto":"año"},{"id":"w5","texto":"punta"},{"id":"w6","texto":"valle"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres ideas centrales de la curva de demanda eléctrica."}}]},{"slug":"energia-3.s5","orden":5,"tipo":"leccion","titulo_es":"Cuánto emite un kWh","bajada_es":"El factor de emisión de la red, cómo cambia según la fuente y cómo calcular las emisiones de tu consumo.","minutos":11,"pasos":[{"slug":"energia-3.s5.p1","orden":1,"grupo":"energia-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El factor de emisión","cuerpo":["Para saber cuánto CO₂ emite un kWh que se consume, se usa el factor de emisión de la red: los kilos de CO₂ que se emitieron, en promedio, para generar cada kWh. Depende de la mezcla de fuentes: una red con mucho carbón puede superar 0,8 kg por kWh; una con mucha hidro y nuclear puede estar por debajo de 0,1.","En Argentina, con mucho gas y una parte importante de hidro, nuclear y renovables, el factor ronda valores del orden de 0,3 a 0,4 kg de CO₂ por kWh, y cambia de un año a otro."],"destacado":{"valor":"≈ 0,3-0,4 kg","texto":"de CO₂ por kWh es el orden del factor de emisión de la red eléctrica argentina en años recientes."}},"solucion":{}},{"slug":"energia-3.s5.p2","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 250 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":87.5,"tolerancia":1.75,"explicacion":"250 × 0,35 = 87,5 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p2.v2","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 400 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"400 × 0,35 = 140 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p2.v3","orden":2,"grupo":"energia-3.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa consume 180 kWh por mes. Con un factor de emisión de 0,35 kg de CO₂ por kWh, ¿cuántos kg de CO₂ corresponden a su consumo mensual?","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":63,"tolerancia":1.26,"explicacion":"180 × 0,35 = 63 kg de CO₂ por mes. Por año, doce veces eso."}},{"slug":"energia-3.s5.p3","orden":3,"grupo":"energia-3.s5.p3","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas redes eléctricas por su factor de emisión típico, de más a menos.","items":[{"id":"i1","texto":"Red basada en carbón"},{"id":"i2","texto":"Red basada en gas"},{"id":"i3","texto":"Red argentina de años recientes"},{"id":"i4","texto":"Red con mucha hidro y nuclear"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El mismo aparato emite muy distinto según el país donde se enchufe.","valores":{"i1":"más de 0,8 kg/kWh","i2":"≈ 0,4-0,5 kg/kWh","i3":"≈ 0,3-0,4 kg/kWh","i4":"menos de 0,1 kg/kWh"}}},{"slug":"energia-3.s5.p4","orden":4,"grupo":"energia-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué el mismo aparato emite distinto","cuerpo":["Una heladera que consume 300 kWh por año emite unos 105 kg de CO₂ con un factor de 0,35, pero más de 240 kg en una red de carbón y menos de 30 kg en una red muy limpia. La eficiencia del aparato importa, y también cómo se genera la electricidad.","Por eso limpiar la red —sumar renovables— reduce las emisiones de todos los aparatos a la vez, sin que nadie cambie nada en su casa."]},"solucion":{}},{"slug":"energia-3.s5.p5","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 300 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":3},"solucion":{"valor":210.00000000000003,"tolerancia":4.200000000000001,"explicacion":"300 × (0,8 − 0,1) = 210 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p5.v2","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 500 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":3},"solucion":{"valor":350.00000000000006,"tolerancia":7.000000000000001,"explicacion":"500 × (0,8 − 0,1) = 350 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p5.v3","orden":5,"grupo":"energia-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato consume 200 kWh por año. ¿Cuántos kg de CO₂ más emite en una red de carbón (0,8 kg/kWh) que en una red muy limpia (0,1 kg/kWh)?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"200 × (0,8 − 0,1) = 140 kg de CO₂ más por año. La red importa tanto como el aparato."}},{"slug":"energia-3.s5.p6","orden":6,"grupo":"energia-3.s5.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo sumar renovables a la red baja las emisiones de tu heladera.","items":[{"id":"i1","texto":"Se construyen parques eólicos y solares"},{"id":"i2","texto":"Generan una parte mayor de la electricidad"},{"id":"i3","texto":"Se quema menos gas en las centrales"},{"id":"i4","texto":"Baja el factor de emisión de la red"},{"id":"i5","texto":"Cada kWh de tu heladera emite menos"},{"id":"i6","texto":"Tu heladera empieza a funcionar con viento directo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Limpiar la red es una palanca de sistema: mejora todos los aparatos a la vez."}},{"slug":"energia-3.s5.p7","orden":7,"grupo":"energia-3.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos casas consumen los mismos kWh, siempre emiten lo mismo, estén en el país que estén.","razones":[{"id":"r1","texto":"Porque depende de cómo se genera la electricidad en cada lugar"},{"id":"r2","texto":"Porque todos los kWh del mundo son idénticos en emisiones"},{"id":"r3","texto":"Porque las emisiones dependen solo del precio"}]},"solucion":{"valor":false,"explicacion":"Depende del factor de emisión de la red de cada lugar. El mismo consumo puede emitir varias veces más en una red de carbón.","clave":["r1"]}},{"slug":"energia-3.s5.p8","orden":8,"grupo":"energia-3.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Generar en casa","cuerpo":["Con la Ley 27.424 de generación distribuida, una casa o un comercio pueden instalar paneles solares, consumir su propia energía y volcar los excedentes a la red, que la distribuidora descuenta o paga. Un sistema de 3 kW en buena parte de Argentina puede generar del orden de 4.000 kWh por año, aunque depende mucho de la región y la orientación."]},"solucion":{}},{"slug":"energia-3.s5.p9","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 4.000 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1400,"tolerancia":28,"explicacion":"4.000 × 0,35 = 1.400 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p9.v2","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 3.500 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1225,"tolerancia":24.5,"explicacion":"3.500 × 0,35 = 1.225 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p9.v3","orden":9,"grupo":"energia-3.s5.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Unos paneles en el techo generan 5.000 kWh por año. Con un factor de 0,35 kg de CO₂ por kWh de la red, ¿cuántos kg de CO₂ por año se evitan?","unidad":"kg de CO₂","decimales":0},"solucion":{"valor":1750,"tolerancia":35,"explicacion":"5.000 × 0,35 = 1.750 kg de CO₂ por año que no hace falta emitir en una central."}},{"slug":"energia-3.s5.p10","orden":10,"grupo":"energia-3.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción reduce las emisiones de la electricidad bajando el consumo o limpiando la generación?","grupos":[{"id":"g1","nombre":"Baja el consumo"},{"id":"g2","nombre":"Limpia la generación"}],"items":[{"id":"i1","texto":"Cambiar a lámparas LED"},{"id":"i2","texto":"Paneles solares en el techo"},{"id":"i3","texto":"Poner el aire a 24 °C"},{"id":"i4","texto":"Un nuevo parque eólico"},{"id":"i5","texto":"Heladera eficiente"},{"id":"i6","texto":"Una represa que genera más en un año lluvioso"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos palancas se multiplican: menos kWh y cada kWh más limpio."}},{"slug":"energia-3.s5.p11","orden":11,"grupo":"energia-3.s5.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿De qué depende cuánto CO₂ emite el consumo eléctrico de una casa? Marcá todo.","opciones":[{"id":"o1","texto":"Cuántos kWh consume"},{"id":"o2","texto":"La mezcla de fuentes de la red"},{"id":"o3","texto":"En qué horario consume, si en el pico se usan centrales más sucias"},{"id":"o4","texto":"Si genera parte de su energía con paneles"},{"id":"o5","texto":"El color de la factura"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cantidad, mezcla, horario y generación propia: las variables de la huella eléctrica."}},{"slug":"energia-3.s5.p12","orden":12,"grupo":"energia-3.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cálculo y marcá los errores.","segmentos":[{"id":"s1","texto":"La casa usa 3.000 kWh por año."},{"id":"s2","texto":"Con 0,35 kg por kWh, emite 3.000 × 0,35 = 1.050 kg de CO₂ por año."},{"id":"s3","texto":"Si la red se vuelve más limpia, sus emisiones no cambian."},{"id":"s4","texto":"Si instala paneles que generan 2.000 kWh, sus emisiones se duplican."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Consumo por factor: una cuenta simple con dos palancas.","por_opcion":{"s3":"Si baja el factor de emisión, baja la huella de cada kWh.","s4":"Al revés: evita comprar esos kWh a la red y baja su huella."}}},{"slug":"energia-3.s5.p13","orden":13,"grupo":"energia-3.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los kg de CO₂ por kWh de la red son el factor de {{0}}; en Argentina ronda los {{1}} kg; y sumar {{2}} lo baja.","banco":[{"id":"w1","texto":"emisión"},{"id":"w2","texto":"0,35"},{"id":"w3","texto":"renovables"},{"id":"w4","texto":"consumo"},{"id":"w5","texto":"3,5"},{"id":"w6","texto":"medidores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La cuenta que conecta el enchufe con el clima."}}]},{"slug":"energia-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: de dónde sale la electricidad","bajada_es":"Generación, matriz, red, demanda y emisiones, mezclados.","minutos":8,"pasos":[{"slug":"energia-3.s6.p1","orden":1,"grupo":"energia-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «De dónde sale la electricidad». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el pico de febrero","bajada_es":"Una ola de calor pone al límite la red de una ciudad. Con los números, armá el plan para pasar el pico sin cortes.","minutos":10,"pasos":[{"slug":"energia-3.s7.p1","orden":1,"grupo":"energia-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["Una ciudad de 200.000 casas enfrenta una ola de calor. A las 20 horas, la demanda llega a 450 MW y la red de distribución aguanta 420 MW sin cortes. Muchas casas tienen el aire a 18 °C. Se estima que subirlo a 24 °C baja unos 400 W por casa que lo use, y que la mitad de las casas tiene aire.","La red tiene un factor de emisión de 0,35 kg de CO₂ por kWh, pero en el pico se encienden turbinas de gas con un factor de 0,6."]},"solucion":{}},{"slug":"energia-3.s7.p2","orden":2,"grupo":"energia-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos MW sobran de demanda por encima de lo que aguanta la red?","unidad":"MW","decimales":0,"contexto":"Demanda de 450 MW; la red aguanta 420 MW."},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"450 − 420 = 30 MW. Hay que bajar al menos eso para evitar cortes."}},{"slug":"energia-3.s7.p3","orden":3,"grupo":"energia-3.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la mitad de las 200.000 casas sube el aire a 24 °C y cada una baja 400 W, ¿cuántos MW baja la demanda?","unidad":"MW","decimales":0,"contexto":"100.000 casas con aire; 400 W menos cada una."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"100.000 × 400 W = 40.000.000 W = 40 MW. Alcanza para pasar el pico sin cortes."}},{"slug":"energia-3.s7.p4","orden":4,"grupo":"energia-3.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ se evitan por cada hora que se bajan esos 40 MW en el pico? (0,6 kg por kWh en el pico)","unidad":"kg de CO₂","decimales":0,"contexto":"40 MW menos durante una hora; turbinas de pico con 0,6 kg de CO₂ por kWh."},"solucion":{"valor":24000,"tolerancia":480,"explicacion":"40 MW durante 1 hora son 40 MWh = 40.000 kWh; × 0,6 = 24.000 kg de CO₂ evitados por hora de pico."}},{"slug":"energia-3.s7.p5","orden":5,"grupo":"energia-3.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas para esta noche por rapidez de efecto, de más rápida a más lenta.","items":[{"id":"i1","texto":"Pedido masivo de subir los aires a 24 °C"},{"id":"i2","texto":"Mover lavarropas y termotanques eléctricos fuera del pico"},{"id":"i3","texto":"Cambiar transformadores del barrio"},{"id":"i4","texto":"Construir un parque solar con baterías"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Para esta noche, la demanda. Para los próximos veranos, la red y la generación.","valores":{"i1":"efecto en minutos","i2":"efecto en horas","i3":"efecto en meses","i4":"efecto en años"}}},{"slug":"energia-3.s7.p6","orden":6,"grupo":"energia-3.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mensaje a la población tiene más chances de funcionar?","opciones":[{"id":"o1","texto":"\"Hoy de 18 a 22, aire a 24 °C: evitemos cortes\""},{"id":"o2","texto":"\"Usen menos energía porque sí, sin más explicación\""},{"id":"o3","texto":"\"El que tenga cortes es por su culpa y de nadie más\""},{"id":"o4","texto":"\"No hay ningún problema, sigan todo igual que siempre\""}]},"solucion":{"clave":["o1"],"explicacion":"Concreto, con horario, con una acción simple y con el motivo: fácil, oportuno y social.","por_opcion":{"o3":"Culpar aleja; un pedido concreto y con motivo claro funciona mejor."}}},{"slug":"energia-3.s7.p7","orden":7,"grupo":"energia-3.s7.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las medidas según su horizonte.","grupos":[{"id":"g1","nombre":"Para esta noche"},{"id":"g2","nombre":"Para los próximos años"}],"items":[{"id":"i1","texto":"Pedir aires a 24 °C"},{"id":"i2","texto":"Reforzar la red de distribución"},{"id":"i3","texto":"Mover consumos flexibles fuera del pico"},{"id":"i4","texto":"Sumar solar con baterías"},{"id":"i5","texto":"Apagar vidrieras iluminadas del centro"},{"id":"i6","texto":"Mejorar la aislación de las viviendas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Un buen plan combina respuestas inmediatas con cambios estructurales."}},{"slug":"energia-3.s7.p8","orden":8,"grupo":"energia-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La distribuidora publica su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Pedimos aires a 24 °C entre las 18 y las 22."},{"id":"s2","texto":"Para ahorrar, cortaremos la luz a los hospitales en el pico."},{"id":"s3","texto":"Reforzaremos los transformadores de los barrios más cargados."},{"id":"s4","texto":"Como la solar no genera a las 20, no conviene sumar solar nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pasar el pico hoy y prepararse para los próximos veranos.","por_opcion":{"s2":"Los servicios esenciales se protegen; se piden reducciones a consumos flexibles.","s4":"Con baterías o moviendo consumos al mediodía, la solar ayuda mucho."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-4","rama":"energia","orden":4,"nivel":2,"titulo_es":"Energías renovables","bajada_es":"El sol de la Puna y el viento patagónico están entre los mejores del mundo. Cómo se aprovechan, qué pasa cuando no hay sol ni viento y cuánto cuestan.","objetivos_es":["Explicar cómo funcionan la energía solar, eólica, hidráulica, biomasa y geotérmica","Calcular la energía que genera una instalación usando el factor de capacidad","Describir estrategias para manejar la variabilidad de sol y viento","Interpretar la caída de costos de las renovables","Evaluar impactos y beneficios locales de los proyectos renovables"],"repasa":["energia-3","energia-1","tronco-2"],"requiere_tronco":2,"fuentes":["irena","cammesa","ley-27424-generacion","iea-energia","owid-energia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-4.s1","orden":1,"tipo":"leccion","titulo_es":"La energía del sol","bajada_es":"Paneles fotovoltaicos, termotanques solares y por qué el noroeste argentino es un lugar privilegiado.","minutos":12,"pasos":[{"slug":"energia-4.s1.p1","orden":1,"grupo":"energia-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos formas de usar el sol","cuerpo":["El sol se puede usar para producir electricidad, con paneles fotovoltaicos, o para calentar agua o aire directamente, con colectores solares térmicos como los termotanques solares. Los dos aprovechan una fuente gratuita e inagotable, pero de formas distintas.","Un termotanque solar puede cubrir buena parte del agua caliente de una casa durante gran parte del año, y ahorrar mucho gas o electricidad."]},"solucion":{}},{"slug":"energia-4.s1.p2","orden":2,"grupo":"energia-4.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es energía solar fotovoltaica o térmica?","grupos":[{"id":"g1","nombre":"Fotovoltaica"},{"id":"g2","nombre":"Térmica"}],"items":[{"id":"i1","texto":"Paneles en el techo que alimentan la heladera"},{"id":"i2","texto":"Termotanque solar para la ducha"},{"id":"i3","texto":"Parque solar en la Puna conectado a la red"},{"id":"i4","texto":"Colector que calienta el agua de una pileta"},{"id":"i5","texto":"Cargador solar de celular"},{"id":"i6","texto":"Cocina solar parabólica"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La fotovoltaica produce electricidad; la térmica, calor. Las dos usan el mismo sol."}},{"slug":"energia-4.s1.p3","orden":3,"grupo":"energia-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol de Argentina","cuerpo":["La cantidad de energía solar que llega al suelo se llama irradiación. En la Puna y el noroeste argentino está entre las más altas del mundo, por la altura, el aire seco y los cielos despejados. Por eso allí se construyeron grandes parques solares, como el de Cauchari, en Jujuy, a más de 4.000 metros de altura.","Pero el sol sirve en casi todo el país: incluso en la región pampeana o en ciudades como Córdoba o Mendoza, un panel bien orientado genera mucha energía a lo largo del año."]},"solucion":{}},{"slug":"energia-4.s1.p4","orden":4,"grupo":"energia-4.s1.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la Puna es uno de los mejores lugares del mundo para la energía solar?","opciones":[{"id":"o1","texto":"Por la altura, el aire seco y los cielos despejados"},{"id":"o2","texto":"Porque allí el sol sale dos veces por día"},{"id":"o3","texto":"Porque hace mucho calor todo el año"},{"id":"o4","texto":"Porque hay mucha agua para enfriar los paneles"}]},"solucion":{"clave":["o1"],"explicacion":"La radiación solar importa más que el calor. De hecho, los paneles rinden mejor con frío.","por_opcion":{"o3":"En la Puna hace frío: lo que importa es la radiación, no la temperatura."}}},{"slug":"energia-4.s1.p5","orden":5,"grupo":"energia-4.s1.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los paneles solares rinden mejor cuanto más calor hace.","razones":[{"id":"r1","texto":"Porque lo que importa es la luz; el calor los hace rendir un poco menos"},{"id":"r2","texto":"Porque los paneles funcionan con el calor del aire"},{"id":"r3","texto":"Porque de noche rinden más"}]},"solucion":{"valor":false,"explicacion":"Los paneles fotovoltaicos pierden algo de eficiencia con el calor. Lo que los hace rendir es la cantidad de luz, no la temperatura.","clave":["r1"]}},{"slug":"energia-4.s1.p6","orden":6,"grupo":"energia-4.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Orientación e inclinación","cuerpo":["En el hemisferio sur, los paneles rinden más si miran hacia el norte, con una inclinación parecida a la latitud del lugar. Las sombras de árboles, edificios o tanques de agua pueden bajar mucho la producción, incluso si tapan una parte chica del panel."]},"solucion":{}},{"slug":"energia-4.s1.p7","orden":7,"grupo":"energia-4.s1.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un panel solar en una casa genere más? Marcá todo.","opciones":[{"id":"o1","texto":"Que mire hacia el norte, en el hemisferio sur"},{"id":"o2","texto":"Que no tenga sombras durante el día"},{"id":"o3","texto":"Que tenga una inclinación adecuada"},{"id":"o4","texto":"Que esté limpio de polvo"},{"id":"o5","texto":"Que mire hacia el sur"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Norte, sin sombras, bien inclinado y limpio."}},{"slug":"energia-4.s1.p8","orden":8,"grupo":"energia-4.s1.p8","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto genera un techo","planteo":"Un sistema de 3 kW está en un lugar donde el sol equivale, en promedio, a 4,5 horas por día de luz plena.","pasos":["Por día: 3 kW × 4,5 h = 13,5 kWh.","Por año: 13,5 × 365 ≈ 4.930 kWh.","Con pérdidas del sistema de un 15 %: 4.930 × 0,85 ≈ 4.190 kWh."],"resultado":"Más de lo que usa en electricidad una casa típica con gas en un año. Las \"horas de sol pleno\" resumen cuánta luz llega en promedio."},"solucion":{}},{"slug":"energia-4.s1.p9","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 3 kW está en un lugar con 4,5 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":4928,"tolerancia":5,"explicacion":"3 × 4,5 × 365 ≈ 4.928 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p9.v2","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 5 kW está en un lugar con 5 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":9125,"tolerancia":5,"explicacion":"5 × 5 × 365 ≈ 9.125 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p9.v3","orden":9,"grupo":"energia-4.s1.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema solar de 2 kW está en un lugar con 4 horas de sol pleno por día en promedio. Sin contar pérdidas, ¿cuántos kWh genera por año? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":2920,"tolerancia":5,"explicacion":"2 × 4 × 365 ≈ 2.920 kWh por año, antes de descontar pérdidas del sistema."}},{"slug":"energia-4.s1.p10","orden":10,"grupo":"energia-4.s1.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un termotanque solar ahorra gas.","items":[{"id":"i1","texto":"El sol calienta el agua en el colector"},{"id":"i2","texto":"El agua caliente se guarda en un tanque aislado"},{"id":"i3","texto":"La ducha usa esa agua ya caliente"},{"id":"i4","texto":"El calefón o termotanque a gas se enciende mucho menos"},{"id":"i5","texto":"Se quema menos gas y se emite menos CO₂"},{"id":"i6","texto":"El termotanque solar genera gas con el sol"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una tecnología simple y probada que ataca uno de los grandes consumos de una casa: el agua caliente."}},{"slug":"energia-4.s1.p11","orden":11,"grupo":"energia-4.s1.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un termotanque solar produce electricidad para la casa.","razones":[{"id":"r1","texto":"Porque calienta agua, no genera electricidad"},{"id":"r2","texto":"Porque tiene paneles fotovoltaicos adentro"},{"id":"r3","texto":"Porque funciona a gas"}]},"solucion":{"valor":false,"explicacion":"Produce calor: calienta agua directamente con el sol. La electricidad la producen los paneles fotovoltaicos.","clave":["r1"]}},{"slug":"energia-4.s1.p12","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 20 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 60 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":144,"tolerancia":2.88,"explicacion":"20 × 0,6 × 12 = 144 m³ por año. Con 1,9 kg de CO₂ por m³, más de 273 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p12.v2","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 25 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 50 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":150,"tolerancia":3,"explicacion":"25 × 0,5 × 12 = 150 m³ por año. Con 1,9 kg de CO₂ por m³, más de 285 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p12.v3","orden":12,"grupo":"energia-4.s1.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa usa 15 m³ de gas por mes para calentar agua. Si un termotanque solar cubre el 70 % del agua caliente, ¿cuántos m³ de gas ahorra por año?","unidad":"m³","decimales":1},"solucion":{"valor":126,"tolerancia":2.52,"explicacion":"15 × 0,7 × 12 = 126 m³ por año. Con 1,9 kg de CO₂ por m³, más de 239 kg de CO₂ evitados."}},{"slug":"energia-4.s1.p13","orden":13,"grupo":"energia-4.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Nuestros paneles rinden más orientados al norte."},{"id":"s2","texto":"Funcionan igual de bien a la sombra de un árbol."},{"id":"s3","texto":"El termotanque solar ahorra gas en el agua caliente."},{"id":"s4","texto":"Los paneles generan más en los días de más calor, aunque esté nublado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Conocer cómo funciona el sol evita promesas engañosas.","por_opcion":{"s2":"Las sombras bajan mucho la producción.","s4":"Lo que importa es la luz; con nubes generan menos."}}},{"slug":"energia-4.s1.p14","orden":14,"grupo":"energia-4.s1.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía solar que llega al suelo se llama {{0}}; en el hemisferio sur los paneles conviene orientarlos al {{1}}; y un termotanque solar ahorra {{2}}.","banco":[{"id":"w1","texto":"irradiación"},{"id":"w2","texto":"norte"},{"id":"w3","texto":"gas"},{"id":"w4","texto":"evaporación"},{"id":"w5","texto":"sur"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para aprovechar bien la energía del sol."}},{"slug":"energia-4.s1.p15","orden":15,"grupo":"energia-4.s1.p15","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas ubicaciones por la energía solar que suelen recibir por año, de más a menos.","items":[{"id":"i1","texto":"Puna jujeña"},{"id":"i2","texto":"Mendoza"},{"id":"i3","texto":"Buenos Aires"},{"id":"i4","texto":"Ushuaia"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El noroeste y Cuyo son privilegiados, pero el sol sirve en casi todo el país.","valores":{"i1":"de las más altas del mundo","i2":"muy alta","i3":"buena","i4":"más baja"}}}]},{"slug":"energia-4.s2","orden":2,"tipo":"leccion","titulo_es":"La energía del viento","bajada_es":"Aerogeneradores, el viento patagónico y el factor de capacidad.","minutos":12,"pasos":[{"slug":"energia-4.s2.p1","orden":1,"grupo":"energia-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo funciona un aerogenerador","cuerpo":["Un aerogenerador moderno tiene una torre de más de 100 metros y palas enormes. El viento hace girar las palas, que mueven un generador en la góndola, arriba de la torre. La potencia que se puede sacar del viento crece muchísimo con la velocidad: si el viento sopla el doble de rápido, la energía disponible es unas ocho veces mayor.","Por eso importa tanto dónde se instalan: unos pocos kilómetros por hora de diferencia en el viento promedio cambian mucho la producción."]},"solucion":{}},{"slug":"energia-4.s2.p2","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 2 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":8,"tolerancia":0.1,"explicacion":"2³ = 8. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p2.v2","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 1,5 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.4,"tolerancia":0.1,"explicacion":"1,5³ = 3,4. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p2.v3","orden":2,"grupo":"energia-4.s2.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía disponible en el viento crece con el cubo de la velocidad. Si el viento sopla 3 veces más rápido, ¿cuántas veces más energía hay disponible? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":27,"tolerancia":0.1,"explicacion":"3³ = 27. Por eso los mejores lugares de viento valen tanto."}},{"slug":"energia-4.s2.p3","orden":3,"grupo":"energia-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El viento patagónico","cuerpo":["La Patagonia tiene algunos de los vientos más fuertes y constantes del mundo. Allí, algunos parques eólicos producen en un año cerca de la mitad de lo que producirían si funcionaran a plena potencia todo el tiempo, un rendimiento muy alto a nivel mundial. También hay parques en la provincia de Buenos Aires y en otras regiones."]},"solucion":{}},{"slug":"energia-4.s2.p4","orden":4,"grupo":"energia-4.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El factor de capacidad","cuerpo":["Ningún generador funciona siempre a su potencia máxima. El factor de capacidad es la energía que produce en un año dividida por la que produciría a potencia máxima las 8.760 horas del año. Un parque solar puede tener un factor de 20 a 30 %; un buen parque eólico patagónico, cerca del 45 al 50 %; una central nuclear, más del 80 %."],"destacado":{"valor":"Factor de capacidad","texto":"= energía real del año ÷ (potencia máxima × 8.760 horas)."}},"solucion":{}},{"slug":"energia-4.s2.p5","orden":5,"grupo":"energia-4.s2.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto genera un parque eólico","planteo":"Un parque de 100 MW en la Patagonia tiene un factor de capacidad del 45 %.","pasos":["A potencia máxima todo el año: 100 MW × 8.760 h = 876.000 MWh.","Con factor 45 %: 876.000 × 0,45 = 394.200 MWh.","Si una casa usa 3 MWh por año: 394.200 ÷ 3 ≈ 131.400 casas."],"resultado":"Un solo parque puede abastecer el consumo eléctrico de más de cien mil hogares."},"solucion":{}},{"slug":"energia-4.s2.p6","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 100 MW tiene un factor de capacidad del 45 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":394200,"tolerancia":7884,"explicacion":"100 × 8.760 × 0,45 = 394.200 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p6.v2","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 50 MW tiene un factor de capacidad del 40 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":175200,"tolerancia":3504,"explicacion":"50 × 8.760 × 0,4 = 175.200 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p6.v3","orden":6,"grupo":"energia-4.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 200 MW tiene un factor de capacidad del 50 %. ¿Cuántos MWh genera por año? (8.760 horas)","unidad":"MWh","decimales":0},"solucion":{"valor":876000,"tolerancia":17520,"explicacion":"200 × 8.760 × 0,5 = 876.000 MWh por año: el consumo de miles de hogares."}},{"slug":"energia-4.s2.p7","orden":7,"grupo":"energia-4.s2.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas centrales por su factor de capacidad típico, de mayor a menor.","items":[{"id":"i1","texto":"Central nuclear"},{"id":"i2","texto":"Parque eólico patagónico"},{"id":"i3","texto":"Parque solar en la Puna"},{"id":"i4","texto":"Paneles en un techo de la llanura"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El factor de capacidad no dice si una fuente es buena o mala: dice cuántas horas equivalentes genera.","valores":{"i1":"más del 80 %","i2":"≈ 45-50 %","i3":"≈ 25-30 %","i4":"≈ 15-20 %"}}},{"slug":"energia-4.s2.p8","orden":8,"grupo":"energia-4.s2.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un parque eólico de 100 MW genera 100 MW todo el tiempo.","razones":[{"id":"r1","texto":"Porque depende del viento: el factor de capacidad resume cuánto genera"},{"id":"r2","texto":"Porque los parques eólicos nunca generan"},{"id":"r3","texto":"Porque 100 MW es la energía de todo el año"}]},"solucion":{"valor":false,"explicacion":"Genera según el viento. En un año, produce una fracción de lo que produciría a potencia máxima: esa fracción es el factor de capacidad.","clave":["r1"]}},{"slug":"energia-4.s2.p9","orden":9,"grupo":"energia-4.s2.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su significado.","izquierda":[{"id":"a1","texto":"Potencia instalada"},{"id":"a2","texto":"Factor de capacidad"},{"id":"a3","texto":"Energía anual"},{"id":"a4","texto":"Horas de sol pleno"}],"derecha":[{"id":"b1","texto":"Lo máximo que puede generar en un momento"},{"id":"b2","texto":"Fracción de la energía máxima que genera en un año"},{"id":"b3","texto":"Lo que efectivamente genera en un año"},{"id":"b4","texto":"Equivalente diario de luz a máxima intensidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Potencia y energía otra vez, como en el tronco: la potencia es la capacidad; la energía, lo que realmente se genera."}},{"slug":"energia-4.s2.p10","orden":10,"grupo":"energia-4.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un lugar sea bueno para un parque eólico? Marcá todo.","opciones":[{"id":"o1","texto":"Vientos fuertes y constantes"},{"id":"o2","texto":"Pocas turbulencias"},{"id":"o3","texto":"Acceso a una línea eléctrica cercana"},{"id":"o4","texto":"Evitar rutas migratorias importantes de aves"},{"id":"o5","texto":"Muchos árboles altos alrededor"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Buen viento, conexión a la red y cuidado de la fauna."}},{"slug":"energia-4.s2.p11","orden":11,"grupo":"energia-4.s2.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que un parque eólico tenga un factor de capacidad del 50 %?","opciones":[{"id":"o1","texto":"Que en el año genera la mitad de su máximo posible"},{"id":"o2","texto":"Que la mitad de los aerogeneradores está rota"},{"id":"o3","texto":"Que funciona solo la mitad de los días del año"},{"id":"o4","texto":"Que genera el 50 % de la electricidad del país"}]},"solucion":{"clave":["o1"],"explicacion":"El factor de capacidad resume la variabilidad del viento en un solo número anual.","por_opcion":{"o3":"Funciona casi todos los días, pero a distintas potencias según el viento."}}},{"slug":"energia-4.s2.p12","orden":12,"grupo":"energia-4.s2.p12","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un dato de potencia o de energía?","grupos":[{"id":"g1","nombre":"Potencia (kW, MW)"},{"id":"g2","nombre":"Energía (kWh, MWh)"}],"items":[{"id":"i1","texto":"Parque eólico de 100 MW"},{"id":"i2","texto":"394.200 MWh generados en un año"},{"id":"i3","texto":"Paneles de 3 kW en un techo"},{"id":"i4","texto":"4.190 kWh generados por los paneles"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Como en el tronco: la potencia es la capacidad en un momento; la energía, lo que se genera en un tiempo."}},{"slug":"energia-4.s2.p13","orden":13,"grupo":"energia-4.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Patagonia tiene vientos de los mejores del mundo."},{"id":"s2","texto":"Si el viento sopla el doble de rápido, el parque genera el doble."},{"id":"s3","texto":"El factor de capacidad resume cuánto genera en el año."},{"id":"s4","texto":"Un parque de 100 MW genera 876.000 MWh por año siempre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Velocidad al cubo y factor de capacidad: las dos claves del viento.","por_opcion":{"s2":"La energía disponible crece con el cubo: unas ocho veces más.","s4":"Eso sería a potencia máxima todo el año; con el factor real, bastante menos."}}},{"slug":"energia-4.s2.p14","orden":14,"grupo":"energia-4.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La energía disponible en el viento crece con el {{0}} de su velocidad; la fracción de la energía máxima que genera una central en un año es su factor de {{1}}.","banco":[{"id":"w1","texto":"cubo"},{"id":"w2","texto":"capacidad"},{"id":"w3","texto":"doble"},{"id":"w4","texto":"emisión"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Las dos ideas clave de la energía eólica."}},{"slug":"energia-4.s2.p15","orden":15,"grupo":"energia-4.s2.p15","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas horas tiene un año, para calcular la energía máxima de una central.","min":100,"max":50000,"paso":1,"unidad":"horas","escala":"log"},"solucion":{"valor":8760,"banda":"log","explicacion":"365 × 24 = 8.760 horas. Es la base para calcular el factor de capacidad."}}]},{"slug":"energia-4.s3","orden":3,"tipo":"leccion","titulo_es":"Agua, biomasa y calor de la Tierra","bajada_es":"Pequeños aprovechamientos hidráulicos, biogás, biomasa y geotermia: las otras renovables.","minutos":11,"pasos":[{"slug":"energia-4.s3.p1","orden":1,"grupo":"energia-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Hidráulica chica y grande","cuerpo":["Las grandes represas generan mucha electricidad sin emitir CO₂ al funcionar, pero tienen impactos importantes: inundan valles, cortan ríos y afectan a peces migradores, como viste en la rama de Agua. Por eso la ley argentina de promoción de renovables considera renovables promovidas solo a los pequeños aprovechamientos hidráulicos, hasta cierta potencia.","Los pequeños aprovechamientos, en ríos y canales de riego, tienen menos impacto y sirven a pueblos y regiones."]},"solucion":{}},{"slug":"energia-4.s3.p2","orden":2,"grupo":"energia-4.s3.p2","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las grandes represas no tienen ningún impacto ambiental porque no emiten CO₂ al generar.","razones":[{"id":"r1","texto":"Porque inundan valles y cortan ríos, aunque no emitan al generar"},{"id":"r2","texto":"Porque las represas emiten más CO₂ que el carbón"},{"id":"r3","texto":"Porque las represas no usan agua"}]},"solucion":{"valor":false,"explicacion":"No emiten al generar, pero inundan valles, cortan ríos y afectan la fauna. Toda fuente tiene impactos; la pregunta es cuáles y cuánto.","clave":["r1"]}},{"slug":"energia-4.s3.p3","orden":3,"grupo":"energia-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Biomasa y biogás","cuerpo":["La biomasa es materia orgánica que se usa como energía: leña, restos de aserraderos, cáscaras de maní o de arroz, bagazo de caña. Se quema para generar calor o electricidad. Es renovable si lo que se usa vuelve a crecer y si no se desmontan bosques para obtenerla.","El biogás se produce cuando microbios descomponen residuos orgánicos sin oxígeno —estiércol, restos de alimentos, efluentes de industrias—, en equipos llamados biodigestores. Tiene metano, que se quema para generar energía. Así se evita que ese metano llegue a la atmósfera y se reemplaza gas fósil."]},"solucion":{}},{"slug":"energia-4.s3.p4","orden":4,"grupo":"energia-4.s3.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un biodigestor en un tambo.","items":[{"id":"i1","texto":"Se junta el estiércol de las vacas"},{"id":"i2","texto":"Se carga en un biodigestor sin oxígeno"},{"id":"i3","texto":"Los microbios producen biogás con metano"},{"id":"i4","texto":"El biogás se quema para generar electricidad o calor"},{"id":"i5","texto":"Lo que queda se usa como fertilizante"},{"id":"i6","texto":"El biodigestor convierte el estiércol en nafta"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un residuo que era un problema se convierte en energía y abono, y se evita metano."}},{"slug":"energia-4.s3.p5","orden":5,"grupo":"energia-4.s3.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es biomasa o biogás?","grupos":[{"id":"g1","nombre":"Biomasa"},{"id":"g2","nombre":"Biogás"}],"items":[{"id":"i1","texto":"Cáscaras de maní quemadas en una caldera"},{"id":"i2","texto":"Gas de un biodigestor con estiércol"},{"id":"i3","texto":"Restos de un aserradero"},{"id":"i4","texto":"Gas captado en un relleno sanitario"},{"id":"i5","texto":"Bagazo de caña de azúcar"},{"id":"i6","texto":"Gas de efluentes de una industria láctea"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La biomasa se quema directamente; el biogás se produce primero con microbios."}},{"slug":"energia-4.s3.p6","orden":6,"grupo":"energia-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El calor de la Tierra","cuerpo":["La geotermia aprovecha el calor del interior de la Tierra. En zonas volcánicas, como Copahue en Neuquén, hay agua y vapor a alta temperatura que podrían mover turbinas. Y en cualquier lugar, a pocos metros de profundidad, el suelo tiene una temperatura bastante estable, que las bombas de calor geotérmicas usan para calefaccionar y refrescar."]},"solucion":{}},{"slug":"energia-4.s3.p7","orden":7,"grupo":"energia-4.s3.p7","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con un ejemplo argentino.","izquierda":[{"id":"a1","texto":"Geotermia"},{"id":"a2","texto":"Biogás"},{"id":"a3","texto":"Biomasa"},{"id":"a4","texto":"Pequeño aprovechamiento hidráulico"}],"derecha":[{"id":"b1","texto":"Copahue, en Neuquén"},{"id":"b2","texto":"Biodigestores en tambos"},{"id":"b3","texto":"Cáscaras de maní en Córdoba"},{"id":"b4","texto":"Minicentral en un canal de riego"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las \"otras renovables\" también tienen lugar en el país."}},{"slug":"energia-4.s3.p8","orden":8,"grupo":"energia-4.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿En qué caso la biomasa NO sería sostenible?","opciones":[{"id":"o1","texto":"Si se desmonta bosque nativo para quemar la leña"},{"id":"o2","texto":"Si se usan restos de un aserradero"},{"id":"o3","texto":"Si se usan cáscaras que sobran de una industria"},{"id":"o4","texto":"Si se replanta lo que se cosecha"}]},"solucion":{"clave":["o1"],"explicacion":"Quemar bosque nativo libera carbono guardado por siglos y destruye biodiversidad.","por_opcion":{"o3":"Aprovechar un residuo que ya existe suele ser sostenible."}}},{"slug":"energia-4.s3.p9","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 200 vacas, el estiércol de cada vaca produce unos 1,5 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":300,"tolerancia":6,"explicacion":"200 × 1,5 = 300 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p9.v2","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 500 vacas, el estiércol de cada vaca produce unos 1,2 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":600,"tolerancia":12,"explicacion":"500 × 1,2 = 600 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p9.v3","orden":9,"grupo":"energia-4.s3.p9","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un tambo con 100 vacas, el estiércol de cada vaca produce unos 1,8 m³ de biogás por día. ¿Cuántos m³ de biogás por día produce el tambo?","unidad":"m³","decimales":1},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"100 × 1,8 = 180 m³ por día de un combustible renovable que antes era un problema."}},{"slug":"energia-4.s3.p10","orden":10,"grupo":"energia-4.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tiene el biogás de residuos? Marcá todos.","opciones":[{"id":"o1","texto":"Evita que el metano llegue a la atmósfera"},{"id":"o2","texto":"Reemplaza gas fósil"},{"id":"o3","texto":"Deja un fertilizante"},{"id":"o4","texto":"Reduce olores y contaminación de los residuos"},{"id":"o5","texto":"Aumenta el metano en el aire"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Energía, abono y menos contaminación en una sola tecnología."}},{"slug":"energia-4.s3.p11","orden":11,"grupo":"energia-4.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Captar el biogás de un relleno sanitario y usarlo para generar electricidad evita que parte del metano llegue a la atmósfera.","razones":[{"id":"r1","texto":"Porque el metano se quema y se aprovecha en lugar de escaparse"},{"id":"r2","texto":"Porque los rellenos no producen metano"},{"id":"r3","texto":"Porque quemar metano produce más metano"}]},"solucion":{"valor":true,"explicacion":"El metano se quema y se convierte en CO₂, que calienta mucho menos, y además se aprovecha su energía.","clave":["r1"]}},{"slug":"energia-4.s3.p12","orden":12,"grupo":"energia-4.s3.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la ley argentina de promoción de renovables incluye solo los pequeños aprovechamientos hidráulicos?","opciones":[{"id":"o1","texto":"Porque las grandes represas tienen impactos mayores"},{"id":"o2","texto":"Porque las grandes represas no generan electricidad"},{"id":"o3","texto":"Porque el agua de los ríos grandes no es renovable"},{"id":"o4","texto":"Porque en Argentina no hay ríos grandes"}]},"solucion":{"clave":["o1"],"explicacion":"La ley busca promover fuentes con menos impacto; las grandes represas ya tienen su propio esquema.","por_opcion":{"o3":"El agua es renovable; lo que pesa son los impactos de las obras grandes."}}},{"slug":"energia-4.s3.p13","orden":13,"grupo":"energia-4.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El biogás se produce con microbios sin oxígeno."},{"id":"s2","texto":"Toda la biomasa es sostenible, venga de donde venga."},{"id":"s3","texto":"En Copahue hay recursos geotérmicos."},{"id":"s4","texto":"La geotermia solo existe en otros países."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las renovables también tienen condiciones para ser sostenibles.","por_opcion":{"s2":"No si se desmontan bosques nativos para obtenerla.","s4":"Argentina tiene recursos geotérmicos, como en Neuquén."}}},{"slug":"energia-4.s3.p14","orden":14,"grupo":"energia-4.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La materia orgánica que se usa como energía es {{0}}; el gas que se obtiene de residuos en un biodigestor es {{1}}; y el calor de la Tierra se aprovecha con la {{2}}.","banco":[{"id":"w1","texto":"biomasa"},{"id":"w2","texto":"biogás"},{"id":"w3","texto":"geotermia"},{"id":"w4","texto":"petróleo"},{"id":"w5","texto":"propano"},{"id":"w6","texto":"hidráulica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres renovables menos conocidas, en una línea."}}]},{"slug":"energia-4.s4","orden":4,"tipo":"leccion","titulo_es":"Cuando no hay sol ni viento","bajada_es":"Variabilidad, complementariedad, almacenamiento y redes: cómo se sostiene un sistema con muchas renovables.","minutos":11,"pasos":[{"slug":"energia-4.s4.p1","orden":1,"grupo":"energia-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Variables, pero predecibles","cuerpo":["El sol y el viento varían: el sol no genera de noche y baja con nubes; el viento cambia de un día a otro. Pero son bastante predecibles con pronósticos, y se complementan: en muchos lugares el viento sopla más de noche o en invierno, cuando el sol rinde menos.","Un sistema eléctrico con muchas renovables combina varias herramientas: diversidad de fuentes y lugares, redes que las conecten, almacenamiento, centrales flexibles de respaldo y gestión de la demanda."]},"solucion":{}},{"slug":"energia-4.s4.p2","orden":2,"grupo":"energia-4.s4.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas ayudan a integrar mucha energía solar y eólica a la red? Marcá todas.","opciones":[{"id":"o1","texto":"Combinar fuentes y lugares distintos"},{"id":"o2","texto":"Redes que conecten regiones"},{"id":"o3","texto":"Almacenamiento en baterías o bombeo"},{"id":"o4","texto":"Mover consumos a las horas de más generación"},{"id":"o5","texto":"Apagar la red cuando no hay sol"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Diversidad, redes, almacenamiento y demanda flexible: las cuatro patas del sistema."}},{"slug":"energia-4.s4.p3","orden":3,"grupo":"energia-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Almacenar energía","cuerpo":["Las baterías guardan electricidad para usarla horas después: se cargan al mediodía con solar y se descargan a la noche. Las centrales hidroeléctricas de bombeo hacen algo parecido a gran escala: cuando sobra energía, bombean agua a un embalse alto; cuando falta, la dejan caer y generan. En Córdoba, el complejo Río Grande funciona así desde hace décadas."]},"solucion":{}},{"slug":"energia-4.s4.p4","orden":4,"grupo":"energia-4.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el ciclo de una central de bombeo.","items":[{"id":"i1","texto":"Sobra electricidad en la red, por ejemplo de noche"},{"id":"i2","texto":"Se usa para bombear agua a un embalse alto"},{"id":"i3","texto":"El agua queda guardada arriba"},{"id":"i4","texto":"Cuando falta electricidad, el agua baja por las turbinas"},{"id":"i5","texto":"Se genera electricidad en el momento de más demanda"},{"id":"i6","texto":"El agua sube sola al embalse de noche"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una \"batería de agua\": guarda energía como altura."}},{"slug":"energia-4.s4.p5","orden":5,"grupo":"energia-4.s4.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una central de bombeo produce más energía de la que usa para bombear.","razones":[{"id":"r1","texto":"Porque pierde una parte: su valor es mover energía en el tiempo"},{"id":"r2","texto":"Porque el agua genera energía de la nada"},{"id":"r3","texto":"Porque el bombeo no usa electricidad"}]},"solucion":{"valor":false,"explicacion":"Pierde una parte en el proceso: devuelve alrededor del 70 a 80 % de lo que usó. Su valor está en mover energía de cuando sobra a cuando falta.","clave":["r1"]}},{"slug":"energia-4.s4.p6","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 100 MWh para subir agua y devuelve el 75 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"100 × 75 ÷ 100 = 75 MWh. Se pierden 25, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p6.v2","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 250 MWh para subir agua y devuelve el 80 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"250 × 80 ÷ 100 = 200 MWh. Se pierden 50, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p6.v3","orden":6,"grupo":"energia-4.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una central de bombeo usa 80 MWh para subir agua y devuelve el 70 % al generar. ¿Cuántos MWh devuelve?","unidad":"MWh","decimales":0},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"80 × 70 ÷ 100 = 56 MWh. Se pierden 24, pero se gana poder usar la energía cuando más se necesita."}},{"slug":"energia-4.s4.p7","orden":7,"grupo":"energia-4.s4.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta herramienta es almacenamiento, respaldo o gestión de la demanda?","grupos":[{"id":"g1","nombre":"Almacenamiento"},{"id":"g2","nombre":"Respaldo"},{"id":"g3","nombre":"Gestión de la demanda"}],"items":[{"id":"i1","texto":"Baterías junto a un parque solar"},{"id":"i2","texto":"Turbina de gas que se enciende rápido"},{"id":"i3","texto":"Cargar autos eléctricos al mediodía"},{"id":"i4","texto":"Central de bombeo"},{"id":"i5","texto":"Represa que regula cuánta agua turbina"},{"id":"i6","texto":"Tarifas más baratas cuando sobra viento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Tres formas distintas de equilibrar un sistema con mucho sol y viento."}},{"slug":"energia-4.s4.p8","orden":8,"grupo":"energia-4.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Redes que conectan","cuerpo":["Cuando hay viento en la Patagonia pero no en Buenos Aires, o sol en el norte pero nubes en el centro, una red bien interconectada permite llevar la energía de donde sobra a donde falta. Por eso ampliar las líneas de transmisión es clave para sumar renovables: en Argentina, la falta de capacidad de transmisión llegó a limitar la construcción de nuevos parques."]},"solucion":{}},{"slug":"energia-4.s4.p9","orden":9,"grupo":"energia-4.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la capacidad de las líneas de transmisión puede frenar nuevos parques eólicos?","opciones":[{"id":"o1","texto":"Porque sin líneas no se puede llevar su energía a las ciudades"},{"id":"o2","texto":"Porque las líneas generan viento en contra"},{"id":"o3","texto":"Porque los parques eólicos no se conectan a la red"},{"id":"o4","texto":"Porque las líneas solo transportan gas"}]},"solucion":{"clave":["o1"],"explicacion":"Generar donde hay viento sirve si se puede transportar la energía hasta donde se consume.","por_opcion":{"o3":"Sí se conectan; el problema es que las líneas existentes pueden estar al límite."}}},{"slug":"energia-4.s4.p10","orden":10,"grupo":"energia-4.s4.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con su solución.","izquierda":[{"id":"a1","texto":"No hay sol a la noche"},{"id":"a2","texto":"Una región sin viento hoy"},{"id":"a3","texto":"Pico de demanda de pocas horas"},{"id":"a4","texto":"Sobra energía al mediodía"}],"derecha":[{"id":"b1","texto":"Baterías cargadas al mediodía"},{"id":"b2","texto":"Energía de otra región por la red"},{"id":"b3","texto":"Central de respaldo que se enciende rápido"},{"id":"b4","texto":"Mover consumos flexibles a esa hora"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada desafío de la variabilidad tiene una o varias respuestas."}},{"slug":"energia-4.s4.p11","orden":11,"grupo":"energia-4.s4.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la energía usada para bombear devuelve una central de bombeo al generar.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":75,"banda":"lineal","explicacion":"Alrededor del 70 al 80 %. Se pierde una parte, pero se gana poder usar la energía cuando más falta."}},{"slug":"energia-4.s4.p12","orden":12,"grupo":"energia-4.s4.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En muchos lugares, el viento y el sol se complementan: el viento suele soplar más de noche o en invierno, cuando el sol rinde menos.","razones":[{"id":"r1","texto":"Porque generan en momentos distintos y se compensan"},{"id":"r2","texto":"Porque el viento solo sopla al mediodía"},{"id":"r3","texto":"Porque sol y viento generan siempre a la vez"}]},"solucion":{"valor":true,"explicacion":"Combinar fuentes que generan en momentos distintos hace más estable el sistema.","clave":["r1"]}},{"slug":"energia-4.s4.p13","orden":13,"grupo":"energia-4.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El sol y el viento varían, pero se pueden pronosticar."},{"id":"s2","texto":"Como el sol no sale de noche, las renovables nunca podrán aportar mucho."},{"id":"s3","texto":"Las centrales de bombeo guardan energía como agua en altura."},{"id":"s4","texto":"Las baterías generan energía por sí mismas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La variabilidad es un desafío técnico con soluciones conocidas.","por_opcion":{"s2":"Con almacenamiento, redes, diversidad y demanda flexible, pueden aportar una parte muy grande.","s4":"Guardan energía generada antes; no la producen."}}},{"slug":"energia-4.s4.p14","orden":14,"grupo":"energia-4.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las centrales de {{0}} guardan energía como agua en altura; las {{1}} se cargan con sol al mediodía; y las líneas de {{2}} llevan energía de una región a otra.","banco":[{"id":"w1","texto":"bombeo"},{"id":"w2","texto":"baterías"},{"id":"w3","texto":"transmisión"},{"id":"w4","texto":"carbón"},{"id":"w5","texto":"turbinas"},{"id":"w6","texto":"agua"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres piezas para sostener un sistema con muchas renovables."}}]},{"slug":"energia-4.s5","orden":5,"tipo":"leccion","titulo_es":"Costos, beneficios e impactos","bajada_es":"Por qué las renovables se volvieron tan baratas, qué empleos generan y qué impactos locales hay que cuidar.","minutos":11,"pasos":[{"slug":"energia-4.s5.p1","orden":1,"grupo":"energia-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una caída de costos histórica","cuerpo":["Según IRENA, la agencia internacional de energías renovables, entre 2010 y 2023 el costo de generar electricidad con paneles solares a gran escala cayó alrededor de un 90 % en promedio en el mundo, y el de la eólica en tierra, alrededor de un 70 %. Hoy, en muchos lugares, construir solar o eólica nueva es más barato que construir centrales fósiles nuevas.","La razón principal es la curva de aprendizaje: cada vez que se duplica la cantidad instalada, la tecnología mejora y se abarata."],"destacado":{"valor":"≈ 90 %","texto":"bajó el costo de la electricidad solar a gran escala entre 2010 y 2023, según IRENA."}},"solucion":{}},{"slug":"energia-4.s5.p2","orden":2,"grupo":"energia-4.s5.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuánto bajó el costo de la electricidad solar a gran escala entre 2010 y 2023, según IRENA.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":90,"banda":"lineal","explicacion":"Alrededor del 90 %. Una de las caídas de costos más rápidas de la historia de la energía."}},{"slug":"energia-4.s5.p3","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,46 dólares y el costo bajó un 90 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.046,"tolerancia":0.002,"explicacion":"0,46 × 0,1 ≈ 0,046 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p3.v2","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,4 dólares y el costo bajó un 85 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.06,"tolerancia":0.002,"explicacion":"0,4 × 0,15 ≈ 0,06 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p3.v3","orden":3,"grupo":"energia-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si generar un kWh solar costaba 0,5 dólares y el costo bajó un 88 %, ¿cuánto cuesta ahora? Redondeá a tres decimales.","unidad":"dólares por kWh","decimales":3},"solucion":{"valor":0.06,"tolerancia":0.002,"explicacion":"0,5 × 0,12 ≈ 0,06 dólares por kWh: una fracción de lo que costaba."}},{"slug":"energia-4.s5.p4","orden":4,"grupo":"energia-4.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la curva de aprendizaje.","items":[{"id":"i1","texto":"Se instalan más paneles en el mundo"},{"id":"i2","texto":"Las fábricas producen a mayor escala"},{"id":"i3","texto":"Mejoran la tecnología y los procesos"},{"id":"i4","texto":"Baja el costo de cada panel"},{"id":"i5","texto":"Se instalan todavía más paneles"},{"id":"i6","texto":"Cuantos más paneles se fabrican, más caros se vuelven"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un círculo virtuoso que explica por qué las renovables se abarataron tanto."}},{"slug":"energia-4.s5.p5","orden":5,"grupo":"energia-4.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Impactos locales","cuerpo":["Las renovables también tienen impactos que hay que evaluar y reducir: los parques eólicos pueden afectar a aves y murciélagos, sobre todo si se ubican en rutas migratorias; los grandes parques solares ocupan superficie y pueden afectar ambientes frágiles; las represas cortan ríos; y la fabricación de paneles, turbinas y baterías usa minerales cuya extracción tiene impactos, como verás en la rama Digital.","Por eso los proyectos renovables también pasan por evaluación de impacto ambiental, y se eligen ubicaciones y diseños que reduzcan esos efectos."]},"solucion":{}},{"slug":"energia-4.s5.p6","orden":6,"grupo":"energia-4.s5.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada fuente con un impacto a cuidar.","izquierda":[{"id":"a1","texto":"Eólica"},{"id":"a2","texto":"Solar a gran escala"},{"id":"a3","texto":"Gran hidráulica"},{"id":"a4","texto":"Baterías"}],"derecha":[{"id":"b1","texto":"Aves y murciélagos en rutas migratorias"},{"id":"b2","texto":"Ocupación de superficie en ambientes frágiles"},{"id":"b3","texto":"Ríos cortados y peces migradores"},{"id":"b4","texto":"Extracción de minerales como el litio"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Ninguna fuente es impacto cero. Lo importante es comparar y reducir."}},{"slug":"energia-4.s5.p7","orden":7,"grupo":"energia-4.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como las renovables no emiten CO₂ al generar, no necesitan evaluación de impacto ambiental.","razones":[{"id":"r1","texto":"Porque tienen otros impactos que hay que evaluar"},{"id":"r2","texto":"Porque la ley prohíbe evaluarlas"},{"id":"r3","texto":"Porque no ocupan ningún espacio"}]},"solucion":{"valor":false,"explicacion":"Tienen otros impactos —sobre fauna, suelo, agua y paisaje— que hay que evaluar y reducir antes de construir.","clave":["r1"]}},{"slug":"energia-4.s5.p8","orden":8,"grupo":"energia-4.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Beneficios más allá del clima","cuerpo":["Además de bajar emisiones, las renovables mejoran la calidad del aire (menos combustión), reducen la dependencia de importar combustibles, generan empleo en instalación y mantenimiento, y pueden llevar energía a lugares aislados, como escuelas rurales con paneles solares.","Cuando las comunidades locales participan y se benefician —con empleo, energía más barata o participación en los proyectos—, los proyectos suelen tener más apoyo."]},"solucion":{}},{"slug":"energia-4.s5.p9","orden":9,"grupo":"energia-4.s5.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios pueden traer las renovables? Marcá todos.","opciones":[{"id":"o1","texto":"Aire más limpio"},{"id":"o2","texto":"Menos importación de combustibles"},{"id":"o3","texto":"Empleo local"},{"id":"o4","texto":"Energía para lugares aislados"},{"id":"o5","texto":"Cero impactos de ningún tipo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Muchos beneficios, sin olvidar que también tienen impactos a cuidar."}},{"slug":"energia-4.s5.p10","orden":10,"grupo":"energia-4.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta decisión reduce el impacto de un proyecto renovable o lo aumenta?","grupos":[{"id":"g1","nombre":"Lo reduce"},{"id":"g2","nombre":"Lo aumenta"}],"items":[{"id":"i1","texto":"Ubicar el parque eólico lejos de rutas migratorias"},{"id":"i2","texto":"Desmontar bosque nativo para un parque solar"},{"id":"i3","texto":"Instalar paneles sobre techos y estacionamientos"},{"id":"i4","texto":"Instalar aerogeneradores en un corredor de aves"},{"id":"i5","texto":"Detener turbinas en momentos de paso de aves"},{"id":"i6","texto":"No consultar a las comunidades cercanas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Dónde y cómo se construye decide gran parte del impacto."}},{"slug":"energia-4.s5.p11","orden":11,"grupo":"energia-4.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para instalar paneles solares en una ciudad, ¿qué lugar suele tener menor impacto?","opciones":[{"id":"o1","texto":"Techos y playas de estacionamiento"},{"id":"o2","texto":"Una plaza con árboles nativos"},{"id":"o3","texto":"Un humedal urbano"},{"id":"o4","texto":"Un parque público con césped"}]},"solucion":{"clave":["o1"],"explicacion":"Los techos y estacionamientos ya son superficies construidas: aprovecharlos no quita espacio verde.","por_opcion":{"o3":"Rellenar o cubrir un humedal destruye un ecosistema valioso."}}},{"slug":"energia-4.s5.p12","orden":12,"grupo":"energia-4.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La solar y la eólica se abarataron mucho en la última década."},{"id":"s2","texto":"Por eso ya no hace falta evaluar sus impactos."},{"id":"s3","texto":"Las renovables pueden llevar energía a escuelas rurales aisladas."},{"id":"s4","texto":"La curva de aprendizaje hace que las tecnologías se encarezcan con el tiempo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Beneficios grandes, impactos que se pueden reducir.","por_opcion":{"s2":"Siguen necesitando evaluación: tienen impactos locales.","s4":"Al revés: al instalarse más, se abaratan."}}},{"slug":"energia-4.s5.p13","orden":13,"grupo":"energia-4.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Según IRENA, el costo de la solar a gran escala bajó cerca del {{0}} %; esa baja se explica por la curva de {{1}}.","banco":[{"id":"w1","texto":"90"},{"id":"w2","texto":"aprendizaje"},{"id":"w3","texto":"10"},{"id":"w4","texto":"demanda"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La historia económica de las renovables, en una línea."}}]},{"slug":"energia-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: energías renovables","bajada_es":"Sol, viento, otras renovables, almacenamiento y costos, mezclados.","minutos":8,"pasos":[{"slug":"energia-4.s6.p1","orden":1,"grupo":"energia-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Energías renovables». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el techo solar de la escuela","bajada_es":"Una escuela de Córdoba quiere instalar paneles solares. Con los números, evaluá el proyecto.","minutos":10,"pasos":[{"slug":"energia-4.s7.p1","orden":1,"grupo":"energia-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El proyecto","cuerpo":["La escuela consume 12.000 kWh de electricidad por año, casi todo de día. Tiene un techo que mira al norte, sin sombras, donde entran paneles por 8 kW. En su zona, el sol equivale a unas 5 horas de sol pleno por día en promedio, y el sistema pierde un 15 % entre cables, inversor y suciedad.","Con la ley de generación distribuida, lo que no consume puede volcarlo a la red. El factor de emisión de la red es de 0,35 kg de CO₂ por kWh."]},"solucion":{}},{"slug":"energia-4.s7.p2","orden":2,"grupo":"energia-4.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por año generarían los paneles antes de las pérdidas? (8 kW × 5 h × 365)","unidad":"kWh","decimales":0,"contexto":"8 kW de paneles; 5 horas de sol pleno por día."},"solucion":{"valor":14600,"tolerancia":292,"explicacion":"8 × 5 × 365 = 14.600 kWh por año antes de descontar pérdidas."}},{"slug":"energia-4.s7.p3","orden":3,"grupo":"energia-4.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con un 15 % de pérdidas, ¿cuántos kWh por año generarían?","unidad":"kWh","decimales":0,"contexto":"14.600 kWh antes de pérdidas; 15 % de pérdidas."},"solucion":{"valor":12410,"tolerancia":248.20000000000002,"explicacion":"14.600 × 0,85 = 12.410 kWh: un poco más de lo que consume la escuela en un año."}},{"slug":"energia-4.s7.p4","orden":4,"grupo":"energia-4.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂ por año se evitarían con esa generación? (0,35 kg por kWh) Redondeá al entero.","unidad":"kg de CO₂","decimales":0,"contexto":"12.410 kWh por año; 0,35 kg de CO₂ por kWh."},"solucion":{"valor":4344,"tolerancia":5,"explicacion":"12.410 × 0,35 ≈ 4.344 kg de CO₂ por año: más de 4 toneladas."}},{"slug":"energia-4.s7.p5","orden":5,"grupo":"energia-4.s7.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Como la escuela casi no consume en vacaciones, ¿qué pasa con la energía de enero?","opciones":[{"id":"o1","texto":"Se vuelca a la red y se compensa"},{"id":"o2","texto":"Se pierde sin que nadie la use"},{"id":"o3","texto":"Los paneles se apagan solos en vacaciones"},{"id":"o4","texto":"Se guarda en los cables hasta marzo"}]},"solucion":{"clave":["o1"],"explicacion":"La generación distribuida permite aprovechar los excedentes: otras casas los consumen.","por_opcion":{"o3":"Siguen generando: la ley permite volcar el excedente a la red."}}},{"slug":"energia-4.s7.p6","orden":6,"grupo":"energia-4.s7.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene revisar antes de instalar? Marcá todo.","opciones":[{"id":"o1","texto":"Que el techo resista el peso de los paneles"},{"id":"o2","texto":"Que no haya sombras a lo largo del año"},{"id":"o3","texto":"Los trámites de conexión con la distribuidora"},{"id":"o4","texto":"Quién se encarga de la limpieza y el mantenimiento"},{"id":"o5","texto":"Que los paneles miren al sur"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Estructura, sombras, trámites y mantenimiento: lo que asegura que el proyecto funcione años."}},{"slug":"energia-4.s7.p7","orden":7,"grupo":"energia-4.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que aparecen en la reunión de padres.","grupos":[{"id":"g1","nombre":"Con fundamento"},{"id":"g2","nombre":"Sin fundamento"}],"items":[{"id":"i1","texto":"La escuela consume sobre todo de día, cuando hay sol"},{"id":"i2","texto":"En invierno los paneles no generan nada"},{"id":"i3","texto":"Evitaría más de 4 toneladas de CO₂ por año"},{"id":"i4","texto":"Los paneles funcionan mejor mirando al sur"},{"id":"i5","texto":"Los chicos pueden aprender con los datos de generación"},{"id":"i6","texto":"Si hay un día nublado, se rompen"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Decidir con datos concretos y sin mitos sobre los paneles."}},{"slug":"energia-4.s7.p8","orden":8,"grupo":"energia-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela escribe el proyecto. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Instalaremos 8 kW en el techo que mira al norte."},{"id":"s2","texto":"Plantaremos árboles altos delante de los paneles para que se vean lindos."},{"id":"s3","texto":"Mostraremos en un pizarrón cuánto generan por día."},{"id":"s4","texto":"No haremos mantenimiento porque los paneles no se ensucian nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen proyecto solar se diseña para rendir y para enseñar.","por_opcion":{"s2":"Las sombras bajarían mucho la generación.","s4":"El polvo baja el rendimiento: conviene limpiarlos periódicamente."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-5","rama":"energia","orden":5,"nivel":3,"titulo_es":"Una red para las renovables","bajada_es":"Orden de despacho, curva del pato, baterías que valen por sus servicios, demanda que se mueve y líneas que faltan: cómo se opera una red con cada vez más sol y viento.","objetivos_es":["Explicar el orden de despacho y el costo marginal de la electricidad","Interpretar la curva del pato y el recorte de generación renovable","Distinguir potencia y energía en un sistema de almacenamiento y calcular su duración y pérdidas","Evaluar la flexibilidad de la demanda como recurso del sistema","Analizar la transmisión como condición para integrar renovables"],"repasa":["energia-3","energia-4","tronco-2","movilidad-4"],"requiere_tronco":3,"fuentes":["cammesa","iea-baterias-2024","bnef-baterias-2024","eia-curva-pato","almagba-2025","iea-renovables-2024","irena"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-5.s1","orden":1,"tipo":"leccion","titulo_es":"Quién genera primero","bajada_es":"El orden de despacho: por qué primero se usan las centrales más baratas de operar y qué cambia con las renovables.","minutos":11,"pasos":[{"slug":"energia-5.s1.p1","orden":1,"grupo":"energia-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El despacho","cuerpo":["En cada momento, la electricidad que se genera tiene que igualar a la que se consume. En Argentina, CAMMESA organiza el despacho: decide qué centrales generan en cada hora. Lo hace, en general, por orden de costo variable: primero las que menos cuesta hacer funcionar una hora más, y así hasta cubrir la demanda. A eso se lo llama orden de mérito.","El sol y el viento no tienen costo de combustible: su costo variable es casi cero. Por eso, cuando están disponibles, entran primero. Las centrales térmicas a gas o gasoil, que pagan combustible, quedan para el final."]},"solucion":{}},{"slug":"energia-5.s1.p2","orden":2,"grupo":"energia-5.s1.p2","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas centrales según su lugar típico en el orden de despacho, de la que entra primero a la que entra última.","items":[{"id":"i1","texto":"Parque eólico con viento"},{"id":"i2","texto":"Ciclo combinado a gas, eficiente"},{"id":"i3","texto":"Turbina a gas de ciclo abierto, menos eficiente"},{"id":"i4","texto":"Turbina a gasoil para los picos"}],"extremos":["Entra primero","Entra última"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Entran primero las de menor costo variable: el viento no paga combustible; entre las térmicas, las más eficientes gastan menos gas por MWh; el gasoil, el más caro, queda para las horas más exigentes."}},{"slug":"energia-5.s1.p3","orden":3,"grupo":"energia-5.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El costo marginal","cuerpo":["La última central que se necesita para cubrir la demanda en una hora marca el costo marginal del sistema en esa hora: es lo que cuesta producir el último megavatio-hora. En las horas de alta demanda entran centrales caras y el costo marginal sube mucho. Cuando sobra sol o viento, el costo marginal puede bajar muchísimo."]},"solucion":{}},{"slug":"energia-5.s1.p4","orden":4,"grupo":"energia-5.s1.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Una hora de despacho","planteo":"La demanda es de 900 MW. Hay 300 MW de eólica (costo variable 0), 400 MW de un ciclo combinado (50 dólares por MWh) y 400 MW de turbinas a gasoil (180 dólares por MWh).","pasos":["Primero entra la eólica: cubre 300 MW. Faltan 600.","Después, el ciclo combinado: cubre 400 MW. Faltan 200.","Las turbinas a gasoil cubren los 200 MW que faltan.","La última central en entrar es el gasoil: el costo marginal es de 180 dólares por MWh."],"resultado":"Con 200 MW más de viento, el gasoil no haría falta y el costo marginal bajaría a 50."},"solucion":{}},{"slug":"energia-5.s1.p5","orden":5,"grupo":"energia-5.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda es de 900 MW. La eólica aporta 300 MW, el ciclo combinado puede dar hasta 400 MW y el resto lo cubren turbinas a gasoil. ¿Cuántos MW tiene que aportar el gasoil?","unidad":"MW","decimales":0,"contexto":"Demanda 900 MW; eólica 300 MW; ciclo combinado hasta 400 MW."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"900 − 300 = 600 MW sin eólica; el ciclo combinado cubre 400; quedan 200 MW para el gasoil. Cada MW más de viento reduce ese gasoil."}},{"slug":"energia-5.s1.p5.v2","orden":5,"grupo":"energia-5.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda es de 1000 MW. La eólica aporta 500 MW, el ciclo combinado puede dar hasta 400 MW y el resto lo cubren turbinas a gasoil. ¿Cuántos MW tiene que aportar el gasoil?","unidad":"MW","decimales":0,"contexto":"Demanda 1000 MW; eólica 500 MW; ciclo combinado hasta 400 MW."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"1000 − 500 = 500 MW sin eólica; el ciclo combinado cubre 400; quedan 100 MW para el gasoil. Cada MW más de viento reduce ese gasoil."}},{"slug":"energia-5.s1.p5.v3","orden":5,"grupo":"energia-5.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda es de 800 MW. La eólica aporta 200 MW, el ciclo combinado puede dar hasta 400 MW y el resto lo cubren turbinas a gasoil. ¿Cuántos MW tiene que aportar el gasoil?","unidad":"MW","decimales":0,"contexto":"Demanda 800 MW; eólica 200 MW; ciclo combinado hasta 400 MW."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"800 − 200 = 600 MW sin eólica; el ciclo combinado cubre 400; quedan 200 MW para el gasoil. Cada MW más de viento reduce ese gasoil."}},{"slug":"energia-5.s1.p6","orden":6,"grupo":"energia-5.s1.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo más viento baja el costo de la electricidad.","items":[{"id":"i1","texto":"Sopla más viento y los parques generan más"},{"id":"i2","texto":"Entran primero, porque no pagan combustible"},{"id":"i3","texto":"Hace falta menos generación térmica"},{"id":"i4","texto":"La última central en entrar es más barata"},{"id":"i5","texto":"Baja el costo marginal del sistema"},{"id":"i6","texto":"El viento encarece el gas que queda"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso, en las horas de mucho viento o sol, el costo marginal cae."}},{"slug":"energia-5.s1.p7","orden":7,"grupo":"energia-5.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué define el costo marginal de la electricidad en una hora?","opciones":[{"id":"o1","texto":"La última central que se necesita para cubrir la demanda"},{"id":"o2","texto":"El promedio del costo de todas las centrales del país"},{"id":"o3","texto":"La central más barata disponible"},{"id":"o4","texto":"El precio de la electricidad del año anterior"}]},"solucion":{"clave":["o1"],"explicacion":"Es el costo del último megavatio-hora: el que hace falta para cerrar el balance en esa hora.","por_opcion":{"o3":"La más barata entra primero; el costo marginal lo marca la última."}}},{"slug":"energia-5.s1.p8","orden":8,"grupo":"energia-5.s1.p8","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el sol y el viento no pagan combustible, entran primero en el despacho cuando están disponibles.","razones":[{"id":"r1","texto":"Porque su costo variable es casi cero"},{"id":"r2","texto":"Porque siempre generan la misma potencia"},{"id":"r3","texto":"Porque la ley obliga a apagar las térmicas"}]},"solucion":{"valor":true,"explicacion":"Su costo variable es casi cero. Por eso desplazan a las centrales que queman combustible y bajan el costo marginal.","clave":["r1"]}},{"slug":"energia-5.s1.p9","orden":9,"grupo":"energia-5.s1.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un costo fijo o un costo variable de una central?","grupos":[{"id":"g1","nombre":"Costo fijo"},{"id":"g2","nombre":"Costo variable"}],"items":[{"id":"i1","texto":"Construir el parque eólico"},{"id":"i2","texto":"El gas que quema una térmica por cada MWh"},{"id":"i3","texto":"Pagar el préstamo de la obra"},{"id":"i4","texto":"El gasoil de una turbina de pico"},{"id":"i5","texto":"Mantener la central aunque no funcione"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"El despacho mira el costo variable; la decisión de construir mira también el fijo."}},{"slug":"energia-5.s1.p10","orden":10,"grupo":"energia-5.s1.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Despacho"},{"id":"a2","texto":"Orden de mérito"},{"id":"a3","texto":"Costo marginal"},{"id":"a4","texto":"CAMMESA"}],"derecha":[{"id":"b1","texto":"Decidir qué centrales generan en cada hora"},{"id":"b2","texto":"Del menor al mayor costo variable"},{"id":"b3","texto":"Costo del último MWh necesario"},{"id":"b4","texto":"Organiza el despacho en Argentina"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El vocabulario básico de cómo funciona un mercado eléctrico."}},{"slug":"energia-5.s1.p11","orden":11,"grupo":"energia-5.s1.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué suele pasar en una hora de mucho viento y poca demanda? Marcá todo.","opciones":[{"id":"o1","texto":"Baja el costo marginal"},{"id":"o2","texto":"Se usan menos centrales térmicas"},{"id":"o3","texto":"Bajan las emisiones de esa hora"},{"id":"o4","texto":"Entran primero las turbinas a gasoil"},{"id":"o5","texto":"Sube el costo marginal"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El viento abundante empuja fuera del despacho a las centrales más caras y más contaminantes."}},{"slug":"energia-5.s1.p12","orden":12,"grupo":"energia-5.s1.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas horas según el costo marginal esperado, de menor a mayor.","items":[{"id":"i1","texto":"Madrugada con mucho viento y poca demanda"},{"id":"i2","texto":"Mediodía soleado de primavera"},{"id":"i3","texto":"Tarde de invierno con demanda media"},{"id":"i4","texto":"Noche de ola de calor sin viento"}],"extremos":["Más bajo","Más alto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más demanda y menos renovables, más caras son las últimas centrales que entran.","valores":{"i1":"muy bajo","i2":"bajo","i3":"medio","i4":"muy alto"}}},{"slug":"energia-5.s1.p13","orden":13,"grupo":"energia-5.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"CAMMESA organiza el despacho eléctrico en Argentina."},{"id":"s2","texto":"El costo marginal lo marca la central más barata."},{"id":"s3","texto":"Las renovables tienen un costo variable casi nulo."},{"id":"s4","texto":"Las turbinas a gasoil son las primeras en entrar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender el despacho ayuda a ver por qué las renovables cambian los precios.","por_opcion":{"s2":"Lo marca la última central necesaria, que suele ser la más cara en funcionamiento.","s4":"Suelen ser las últimas: su costo variable es alto."}}},{"slug":"energia-5.s1.p14","orden":14,"grupo":"energia-5.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Ordenar las centrales del menor al mayor costo variable es el orden de {{0}}; el costo del último MWh necesario es el costo {{1}}; y en Argentina el despacho lo organiza {{2}}.","banco":[{"id":"w1","texto":"mérito"},{"id":"w2","texto":"marginal"},{"id":"w3","texto":"CAMMESA"},{"id":"w4","texto":"llegada"},{"id":"w5","texto":"promedio"},{"id":"w6","texto":"ENARGAS"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para entender cómo se decide quién genera."}}]},{"slug":"energia-5.s2","orden":2,"tipo":"leccion","titulo_es":"Cuando sobra sol","bajada_es":"Pronósticos, la curva del pato y el recorte de generación: los desafíos de un sistema con mucho sol y viento.","minutos":11,"pasos":[{"slug":"energia-5.s2.p1","orden":1,"grupo":"energia-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Variable pero predecible","cuerpo":["El sol y el viento varían, pero no al azar: se pronostican con modelos meteorológicos, y el pronóstico para las próximas horas suele ser bastante preciso. Además, combinar muchos parques en lugares distintos suaviza la variación: si una nube tapa un parque solar, otros siguen generando. El viento y el sol también se complementan: en muchos lugares, el viento sopla más de noche o en invierno."]},"solucion":{}},{"slug":"energia-5.s2.p2","orden":2,"grupo":"energia-5.s2.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a manejar la variabilidad del sol y el viento? Marcá todo.","opciones":[{"id":"o1","texto":"Pronósticos meteorológicos de horas y días"},{"id":"o2","texto":"Parques en lugares distintos"},{"id":"o3","texto":"Combinar eólica y solar"},{"id":"o4","texto":"Construir todos los parques en el mismo lugar"},{"id":"o5","texto":"Ignorar los pronósticos"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La diversidad geográfica y tecnológica es una forma barata de flexibilidad."}},{"slug":"energia-5.s2.p3","orden":3,"grupo":"energia-5.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La curva del pato","cuerpo":["En lugares con mucha energía solar, como California, la demanda que tienen que cubrir las demás centrales cae mucho al mediodía (porque el sol cubre gran parte) y sube de golpe al atardecer, cuando el sol se va y la gente vuelve a casa. Dibujada, esa curva parece un pato: panza baja al mediodía y cuello empinado a la tarde. Cuanta más solar, más profunda la panza y más empinado el cuello, que hay que cubrir con centrales rápidas o baterías."]},"solucion":{}},{"slug":"energia-5.s2.p4","orden":4,"grupo":"energia-5.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la curva del pato.","items":[{"id":"i1","texto":"Se instala mucha energía solar"},{"id":"i2","texto":"Al mediodía el sol cubre gran parte de la demanda"},{"id":"i3","texto":"Las demás centrales casi no hacen falta a esa hora"},{"id":"i4","texto":"Al atardecer el sol se va y la demanda sube"},{"id":"i5","texto":"Hay que sumar mucha potencia en poco tiempo"},{"id":"i6","texto":"A la noche el sol genera más que al mediodía"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El desafío no es la energía total, sino la rampa del atardecer."}},{"slug":"energia-5.s2.p5","orden":5,"grupo":"energia-5.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda que deben cubrir las centrales no solares pasa de 4.000 MW a las 17 a 13.000 MW a las 20. ¿Cuántos MW por hora tienen que sumar, en promedio?","unidad":"MW por hora","decimales":0,"contexto":"De 4000 a 13000 MW en 3 horas."},"solucion":{"valor":3000,"tolerancia":1,"explicacion":"(13.000 − 4.000) ÷ 3 ≈ 3.000 MW por hora. Esa rampa exige centrales rápidas, baterías o demanda flexible."}},{"slug":"energia-5.s2.p5.v2","orden":5,"grupo":"energia-5.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda que deben cubrir las centrales no solares pasa de 3.000 MW a las 17 a 9.000 MW a las 21. ¿Cuántos MW por hora tienen que sumar, en promedio?","unidad":"MW por hora","decimales":0,"contexto":"De 3000 a 9000 MW en 4 horas."},"solucion":{"valor":1500,"tolerancia":1,"explicacion":"(9.000 − 3.000) ÷ 4 ≈ 1.500 MW por hora. Esa rampa exige centrales rápidas, baterías o demanda flexible."}},{"slug":"energia-5.s2.p5.v3","orden":5,"grupo":"energia-5.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La demanda que deben cubrir las centrales no solares pasa de 5.000 MW a las 17 a 14.000 MW a las 20. ¿Cuántos MW por hora tienen que sumar, en promedio?","unidad":"MW por hora","decimales":0,"contexto":"De 5000 a 14000 MW en 3 horas."},"solucion":{"valor":3000,"tolerancia":1,"explicacion":"(14.000 − 5.000) ÷ 3 ≈ 3.000 MW por hora. Esa rampa exige centrales rápidas, baterías o demanda flexible."}},{"slug":"energia-5.s2.p6","orden":6,"grupo":"energia-5.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Recortar","cuerpo":["Cuando se genera más energía renovable de la que se puede consumir o transportar, los parques tienen que reducir su producción: se llama recorte o vertimiento. Es energía limpia que se desperdicia. Ocurre por falta de demanda en esas horas, por falta de líneas de transmisión para llevarla a donde se necesita, o por restricciones técnicas de la red. Almacenar, mover demanda y construir líneas reducen el recorte."]},"solucion":{}},{"slug":"energia-5.s2.p7","orden":7,"grupo":"energia-5.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta causa de recorte se debe a la demanda o a la red?","grupos":[{"id":"g1","nombre":"Poca demanda en esa hora"},{"id":"g2","nombre":"Límite de la red"}],"items":[{"id":"i1","texto":"Un domingo al mediodía con mucho sol y poco consumo"},{"id":"i2","texto":"La línea que sale de la Patagonia ya está llena"},{"id":"i3","texto":"Una madrugada ventosa con las fábricas cerradas"},{"id":"i4","texto":"Un transformador que no admite más potencia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Cada causa tiene su solución: almacenar o mover demanda para una; construir red para la otra."}},{"slug":"energia-5.s2.p8","orden":8,"grupo":"energia-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un conjunto de parques podría generar 5.000 MWh en un mes, pero se recortan 250 MWh. ¿Qué porcentaje de la energía posible se perdió?","unidad":"%","decimales":1,"contexto":"250 MWh recortados de 5000 MWh posibles."},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"250 ÷ 5.000 × 100 = 5 %. Energía limpia que ya estaba disponible y se desperdició."}},{"slug":"energia-5.s2.p8.v2","orden":8,"grupo":"energia-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un conjunto de parques podría generar 8.000 MWh en un mes, pero se recortan 640 MWh. ¿Qué porcentaje de la energía posible se perdió?","unidad":"%","decimales":1,"contexto":"640 MWh recortados de 8000 MWh posibles."},"solucion":{"valor":8,"tolerancia":0.1,"explicacion":"640 ÷ 8.000 × 100 = 8 %. Energía limpia que ya estaba disponible y se desperdició."}},{"slug":"energia-5.s2.p8.v3","orden":8,"grupo":"energia-5.s2.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un conjunto de parques podría generar 3.000 MWh en un mes, pero se recortan 90 MWh. ¿Qué porcentaje de la energía posible se perdió?","unidad":"%","decimales":1,"contexto":"90 MWh recortados de 3000 MWh posibles."},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"90 ÷ 3.000 × 100 = 3 %. Energía limpia que ya estaba disponible y se desperdició."}},{"slug":"energia-5.s2.p9","orden":9,"grupo":"energia-5.s2.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si hay recorte de energía renovable, significa que ya hay demasiadas renovables y no conviene sumar más.","razones":[{"id":"r1","texto":"Porque suele indicar falta de flexibilidad, no exceso"},{"id":"r2","texto":"Porque el recorte nunca ocurre"},{"id":"r3","texto":"Porque las renovables no se pueden recortar"}]},"solucion":{"valor":false,"explicacion":"El recorte suele indicar que falta flexibilidad —almacenamiento, demanda que se mueve, líneas—, no que sobren renovables. Resolver eso permite aprovechar la energía.","clave":["r1"]}},{"slug":"energia-5.s2.p10","orden":10,"grupo":"energia-5.s2.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un sistema con mucha solar, ¿cuándo es más difícil cubrir la demanda con otras centrales?","opciones":[{"id":"o1","texto":"Al atardecer, cuando el sol baja y la demanda sube"},{"id":"o2","texto":"Al mediodía, cuando el sol está más alto"},{"id":"o3","texto":"A las 3 de la mañana, cuando todos duermen"},{"id":"o4","texto":"Los domingos a las 10"}]},"solucion":{"clave":["o1"],"explicacion":"El cuello del pato es la hora crítica: mucha potencia que aparece en poco tiempo.","por_opcion":{"o3":"La demanda es baja; el desafío es la rampa del atardecer."}}},{"slug":"energia-5.s2.p11","orden":11,"grupo":"energia-5.s2.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué ventaja tiene combinar un parque solar con uno eólico donde el viento sopla más de noche?","opciones":[{"id":"o1","texto":"Cubren horas distintas y suavizan la generación"},{"id":"o2","texto":"Duplican la generación al mediodía"},{"id":"o3","texto":"Eliminan por completo la necesidad de red"},{"id":"o4","texto":"Funcionan con el mismo recurso natural"}]},"solucion":{"clave":["o1"],"explicacion":"La complementariedad reduce los huecos sin generación y aprovecha mejor las líneas.","por_opcion":{"o3":"Siguen necesitando red; lo que mejora es la estabilidad del aporte."}}},{"slug":"energia-5.s2.p12","orden":12,"grupo":"energia-5.s2.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Curva del pato"},{"id":"a2","texto":"Recorte"},{"id":"a3","texto":"Rampa"},{"id":"a4","texto":"Complementariedad"}],"derecha":[{"id":"b1","texto":"Demanda neta baja al mediodía y rampa al atardecer"},{"id":"b2","texto":"Reducir la generación renovable que no se puede usar"},{"id":"b3","texto":"Aumento rápido de la potencia necesaria"},{"id":"b4","texto":"Fuentes que generan en momentos distintos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario para entender la operación de una red con mucho sol y viento."}},{"slug":"energia-5.s2.p13","orden":13,"grupo":"energia-5.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La curva del pato se vuelve más profunda con más solar."},{"id":"s2","texto":"El viento y el sol cambian al azar y no se pueden prever."},{"id":"s3","texto":"El recorte desperdicia energía limpia."},{"id":"s4","texto":"Juntar todos los parques en un solo lugar reduce la variabilidad."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los desafíos de las renovables son reales y tienen soluciones conocidas.","por_opcion":{"s2":"Se pronostican con bastante precisión para las próximas horas.","s4":"La reduce distribuirlos en lugares distintos."}}},{"slug":"energia-5.s2.p14","orden":14,"grupo":"energia-5.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La curva con panza al mediodía y cuello al atardecer se llama curva del {{0}}; reducir la generación renovable que no se puede usar es un {{1}}; y combinar sol y viento aprovecha su {{2}}.","banco":[{"id":"w1","texto":"pato"},{"id":"w2","texto":"recorte"},{"id":"w3","texto":"complementariedad"},{"id":"w4","texto":"cisne"},{"id":"w5","texto":"bono"},{"id":"w6","texto":"rivalidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para operar una red con muchas renovables."}}]},{"slug":"energia-5.s3","orden":3,"tipo":"leccion","titulo_es":"Qué hacen las baterías","bajada_es":"Potencia y energía, horas de duración, pérdidas y los distintos servicios que un sistema de almacenamiento le presta a la red.","minutos":12,"pasos":[{"slug":"energia-5.s3.p1","orden":1,"grupo":"energia-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Potencia y energía, otra vez","cuerpo":["Un sistema de baterías se describe con dos números. La potencia, en megavatios (MW), dice cuánta energía puede entregar por hora: qué tan \"ancho\" es el caño. La energía, en megavatios-hora (MWh), dice cuánta energía guarda: qué tan grande es el tanque. Dividiendo energía por potencia se obtiene la duración: un sistema de 100 MW y 400 MWh puede entregar su potencia máxima durante 4 horas."]},"solucion":{}},{"slug":"energia-5.s3.p2","orden":2,"grupo":"energia-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de baterías tiene 100 MW de potencia y 400 MWh de energía. ¿Cuántas horas puede entregar su potencia máxima?","unidad":"horas","decimales":0,"contexto":"Potencia 100 MW; energía 400 MWh."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"400 MWh ÷ 100 MW = 4 horas. Lo viste en el tronco: potencia y energía son cosas distintas."}},{"slug":"energia-5.s3.p2.v2","orden":2,"grupo":"energia-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de baterías tiene 50 MW de potencia y 100 MWh de energía. ¿Cuántas horas puede entregar su potencia máxima?","unidad":"horas","decimales":0,"contexto":"Potencia 50 MW; energía 100 MWh."},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"100 MWh ÷ 50 MW = 2 horas. Lo viste en el tronco: potencia y energía son cosas distintas."}},{"slug":"energia-5.s3.p2.v3","orden":2,"grupo":"energia-5.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un sistema de baterías tiene 200 MW de potencia y 800 MWh de energía. ¿Cuántas horas puede entregar su potencia máxima?","unidad":"horas","decimales":0,"contexto":"Potencia 200 MW; energía 800 MWh."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"800 MWh ÷ 200 MW = 4 horas. Lo viste en el tronco: potencia y energía son cosas distintas."}},{"slug":"energia-5.s3.p3","orden":3,"grupo":"energia-5.s3.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una batería de 100 MW y 200 MWh, ¿qué puede hacer?","opciones":[{"id":"o1","texto":"Entregar 100 MW durante 2 horas"},{"id":"o2","texto":"Entregar 200 MW durante 1 hora"},{"id":"o3","texto":"Entregar 100 MW durante 200 horas"},{"id":"o4","texto":"Entregar 2 MW durante 100 horas, como máximo"}]},"solucion":{"clave":["o1"],"explicacion":"La potencia limita cuánto entrega por hora; la energía, cuánto tiempo.","por_opcion":{"o3":"Confunde potencia con energía: 200 MWh ÷ 100 MW = 2 horas."}}},{"slug":"energia-5.s3.p4","orden":4,"grupo":"energia-5.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nada es gratis: las pérdidas","cuerpo":["Al cargar y descargar una batería se pierde algo de energía como calor. Las baterías de litio devuelven cerca del 85 al 90 % de lo que se les carga; las centrales de bombeo, que suben agua a un embalse para luego turbinarla, alrededor del 75 al 80 %. Aun así, guardar energía barata y limpia para usarla cuando hace falta suele valer la pena."]},"solucion":{}},{"slug":"energia-5.s3.p5","orden":5,"grupo":"energia-5.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se cargan 100 MWh en un sistema de almacenamiento con una eficiencia de ida y vuelta del 88 %, ¿cuántos MWh se recuperan?","unidad":"MWh","decimales":0,"contexto":"100 MWh cargados; eficiencia del 88 %."},"solucion":{"valor":88,"tolerancia":1.76,"explicacion":"100 × 88 % = 88 MWh. El resto se pierde como calor en la carga y la descarga."}},{"slug":"energia-5.s3.p5.v2","orden":5,"grupo":"energia-5.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se cargan 400 MWh en un sistema de almacenamiento con una eficiencia de ida y vuelta del 85 %, ¿cuántos MWh se recuperan?","unidad":"MWh","decimales":0,"contexto":"400 MWh cargados; eficiencia del 85 %."},"solucion":{"valor":340,"tolerancia":6.8,"explicacion":"400 × 85 % = 340 MWh. El resto se pierde como calor en la carga y la descarga."}},{"slug":"energia-5.s3.p5.v3","orden":5,"grupo":"energia-5.s3.p5","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se cargan 250 MWh en un sistema de almacenamiento con una eficiencia de ida y vuelta del 80 %, ¿cuántos MWh se recuperan?","unidad":"MWh","decimales":0,"contexto":"250 MWh cargados; eficiencia del 80 %."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"250 × 80 % = 200 MWh. El resto se pierde como calor en la carga y la descarga."}},{"slug":"energia-5.s3.p6","orden":6,"grupo":"energia-5.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchos servicios","cuerpo":["Las baterías no solo \"guardan el sol para la noche\". Pueden comprar energía cuando es barata y venderla cuando es cara (arbitraje), cubrir los picos de demanda y evitar encender centrales caras, responder en fracciones de segundo cuando falla una central para sostener la frecuencia de la red, y aliviar líneas o transformadores saturados sin tener que ampliarlos enseguida. En Argentina, la licitación AlmaGBA de 2025 buscó justamente eso para el Área Metropolitana: se ofrecieron más de 1.300 MW y se adjudicaron unos 667 MW, por encima de los 500 MW previstos."]},"solucion":{}},{"slug":"energia-5.s3.p7","orden":7,"grupo":"energia-5.s3.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada servicio con lo que hace la batería.","izquierda":[{"id":"a1","texto":"Arbitraje"},{"id":"a2","texto":"Cubrir picos"},{"id":"a3","texto":"Reserva rápida"},{"id":"a4","texto":"Alivio de red"}],"derecha":[{"id":"b1","texto":"Carga barato y descarga cuando es caro"},{"id":"b2","texto":"Entrega potencia en las horas de máxima demanda"},{"id":"b3","texto":"Responde en segundos si falla una central"},{"id":"b4","texto":"Evita saturar una línea o un transformador"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una misma batería puede prestar varios servicios, y eso define si es rentable."}},{"slug":"energia-5.s3.p8","orden":8,"grupo":"energia-5.s3.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una batería carga 100 MWh a 20 dólares por MWh y, con una eficiencia del 88 %, descarga lo recuperado a 120 dólares por MWh. ¿Cuántos dólares gana en ese ciclo?","unidad":"dólares","decimales":0,"contexto":"Carga 100 MWh a 20; vende a 120; eficiencia 88 %."},"solucion":{"valor":8560,"tolerancia":1,"explicacion":"Vende 100 × 0,88 = 88 MWh × 120 = 10.560; pagó 100 × 20 = 2.000. Gana 8.560 dólares. La diferencia de precios paga las pérdidas."}},{"slug":"energia-5.s3.p8.v2","orden":8,"grupo":"energia-5.s3.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una batería carga 200 MWh a 30 dólares por MWh y, con una eficiencia del 85 %, descarga lo recuperado a 100 dólares por MWh. ¿Cuántos dólares gana en ese ciclo?","unidad":"dólares","decimales":0,"contexto":"Carga 200 MWh a 30; vende a 100; eficiencia 85 %."},"solucion":{"valor":11000,"tolerancia":1,"explicacion":"Vende 200 × 0,85 = 170 MWh × 100 = 17.000; pagó 200 × 30 = 6.000. Gana 11.000 dólares. La diferencia de precios paga las pérdidas."}},{"slug":"energia-5.s3.p8.v3","orden":8,"grupo":"energia-5.s3.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una batería carga 50 MWh a 10 dólares por MWh y, con una eficiencia del 90 %, descarga lo recuperado a 150 dólares por MWh. ¿Cuántos dólares gana en ese ciclo?","unidad":"dólares","decimales":0,"contexto":"Carga 50 MWh a 10; vende a 150; eficiencia 90 %."},"solucion":{"valor":6250,"tolerancia":1,"explicacion":"Vende 50 × 0,9 = 45 MWh × 150 = 6.750; pagó 50 × 10 = 500. Gana 6.250 dólares. La diferencia de precios paga las pérdidas."}},{"slug":"energia-5.s3.p9","orden":9,"grupo":"energia-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cada vez más baratas","cuerpo":["Según la Agencia Internacional de Energía, el costo de las baterías de litio cayó alrededor de un 90 % en menos de quince años, y en 2023 el almacenamiento con baterías en el sector eléctrico creció más del 130 %. BloombergNEF informó que en 2024 el precio promedio de los paquetes de baterías bajó a unos 115 dólares por kWh. Esa caída explica por qué las baterías pasaron de ser una rareza a una pieza común de las redes."]},"solucion":{}},{"slug":"energia-5.s3.p10","orden":10,"grupo":"energia-5.s3.p10","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuánto cayó el costo de las baterías de litio en menos de quince años, según la AIE.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":90,"banda":"lineal","explicacion":"Alrededor de un 90 %. Esa caída es comparable a la de los paneles solares, y cambió la economía de las redes."}},{"slug":"energia-5.s3.p11","orden":11,"grupo":"energia-5.s3.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una batería de 4 horas puede reemplazar por completo a las centrales que se usan en una semana sin viento.","razones":[{"id":"r1","texto":"Porque cubre horas, no semanas"},{"id":"r2","texto":"Porque las baterías no pueden entregar energía"},{"id":"r3","texto":"Porque en una semana sin viento no hay demanda"}]},"solucion":{"valor":false,"explicacion":"Cubre horas, no semanas. Para períodos largos hacen falta otras soluciones: embalses, centrales despachables, intercambio entre regiones o almacenamiento de larga duración.","clave":["r1"]}},{"slug":"energia-5.s3.p12","orden":12,"grupo":"energia-5.s3.p12","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el funcionamiento de una central de bombeo.","items":[{"id":"i1","texto":"Sobra energía barata en la red"},{"id":"i2","texto":"Se bombea agua a un embalse más alto"},{"id":"i3","texto":"El agua queda guardada como energía"},{"id":"i4","texto":"En el pico, el agua baja por las turbinas"},{"id":"i5","texto":"Se genera electricidad cuando más se necesita"},{"id":"i6","texto":"El agua sube sola por la pendiente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es la forma de almacenamiento más antigua a gran escala, y todavía una de las más usadas."}},{"slug":"energia-5.s3.p13","orden":13,"grupo":"energia-5.s3.p13","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para qué horizonte de tiempo sirve mejor cada tecnología?","grupos":[{"id":"g1","nombre":"Segundos a horas"},{"id":"g2","nombre":"Horas a días"},{"id":"g3","nombre":"Semanas a estaciones"}],"items":[{"id":"i1","texto":"Baterías de litio"},{"id":"i2","texto":"Centrales de bombeo"},{"id":"i3","texto":"Grandes embalses con reserva de agua"},{"id":"i4","texto":"Volantes de inercia"},{"id":"i5","texto":"Embalses hidroeléctricos"},{"id":"i6","texto":"Combustibles almacenables, como el gas o el hidrógeno"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"No hay una sola tecnología de almacenamiento: cada una cubre un horizonte distinto."}},{"slug":"energia-5.s3.p14","orden":14,"grupo":"energia-5.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La duración de una batería es su energía dividida por su potencia."},{"id":"s2","texto":"Una batería devuelve el 100 % de lo que se le carga."},{"id":"s3","texto":"Las baterías pueden sostener la frecuencia en segundos."},{"id":"s4","texto":"Las baterías solo sirven para guardar sol para la noche."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las baterías son mucho más versátiles que \"un tanque de sol\".","por_opcion":{"s2":"Las de litio devuelven cerca del 85 al 90 %.","s4":"También hacen arbitraje, cubren picos, dan reserva y alivian la red."}}},{"slug":"energia-5.s3.p15","orden":15,"grupo":"energia-5.s3.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La capacidad de entrega de una batería se mide en {{0}}; lo que guarda se mide en {{1}}; y comprar barato para vender caro es hacer {{2}}.","banco":[{"id":"w1","texto":"MW"},{"id":"w2","texto":"MWh"},{"id":"w3","texto":"arbitraje"},{"id":"w4","texto":"kg"},{"id":"w5","texto":"litros"},{"id":"w6","texto":"reciclaje"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para entender el almacenamiento."}}]},{"slug":"energia-5.s4","orden":4,"tipo":"leccion","titulo_es":"Demanda que se mueve y líneas que faltan","bajada_es":"Flexibilidad del consumo, tarifas por horario, autos que cargan de noche y la transmisión como cuello de botella.","minutos":11,"pasos":[{"slug":"energia-5.s4.p1","orden":1,"grupo":"energia-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La demanda también puede moverse","cuerpo":["Durante un siglo, la red se pensó así: la demanda hace lo que quiere y la generación la sigue. Pero muchos consumos pueden moverse unas horas sin que nadie lo note: calentar agua, cargar un auto eléctrico, enfriar una cámara frigorífica, bombear agua a un tanque, algunos procesos industriales. Moverlos a las horas con más sol o viento, o sacarlos de las horas pico, es flexibilidad de la demanda."]},"solucion":{}},{"slug":"energia-5.s4.p2","orden":2,"grupo":"energia-5.s4.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este consumo se puede mover unas horas o no?","grupos":[{"id":"g1","nombre":"Se puede mover"},{"id":"g2","nombre":"Difícil de mover"}],"items":[{"id":"i1","texto":"Cargar un auto eléctrico"},{"id":"i2","texto":"La luz de un quirófano"},{"id":"i3","texto":"Calentar agua en un termotanque eléctrico"},{"id":"i4","texto":"Un respirador en una casa"},{"id":"i5","texto":"Bombear agua a un tanque elevado"},{"id":"i6","texto":"Los semáforos de una ciudad"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"No todo se puede mover, pero lo que sí se puede es un recurso enorme y barato."}},{"slug":"energia-5.s4.p3","orden":3,"grupo":"energia-5.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Precios que cambian por hora","cuerpo":["Una forma de mover la demanda son las tarifas por horario: la electricidad es más cara en las horas pico y más barata cuando sobra. Otra son los programas en los que grandes usuarios reducen su consumo cuando el sistema lo pide, a cambio de un pago. Con medidores inteligentes y aparatos programables, esto puede hacerse de forma automática."]},"solucion":{}},{"slug":"energia-5.s4.p4","orden":4,"grupo":"energia-5.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 300 kWh por mes. Si la tarifa es de 180 pesos por kWh en horario pico y 90 de madrugada, ¿cuántos pesos por mes ahorra cargando de madrugada?","unidad":"pesos","decimales":0,"contexto":"300 kWh; 180 y 90 pesos por kWh."},"solucion":{"valor":27000,"tolerancia":540,"explicacion":"300 × (180 − 90) = 27.000 pesos por mes. Tarifas de ejemplo: la señal de precio premia mover el consumo."}},{"slug":"energia-5.s4.p4.v2","orden":4,"grupo":"energia-5.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 200 kWh por mes. Si la tarifa es de 200 pesos por kWh en horario pico y 80 de madrugada, ¿cuántos pesos por mes ahorra cargando de madrugada?","unidad":"pesos","decimales":0,"contexto":"200 kWh; 200 y 80 pesos por kWh."},"solucion":{"valor":24000,"tolerancia":480,"explicacion":"200 × (200 − 80) = 24.000 pesos por mes. Tarifas de ejemplo: la señal de precio premia mover el consumo."}},{"slug":"energia-5.s4.p4.v3","orden":4,"grupo":"energia-5.s4.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 400 kWh por mes. Si la tarifa es de 150 pesos por kWh en horario pico y 70 de madrugada, ¿cuántos pesos por mes ahorra cargando de madrugada?","unidad":"pesos","decimales":0,"contexto":"400 kWh; 150 y 70 pesos por kWh."},"solucion":{"valor":32000,"tolerancia":640,"explicacion":"400 × (150 − 70) = 32.000 pesos por mes. Tarifas de ejemplo: la señal de precio premia mover el consumo."}},{"slug":"energia-5.s4.p5","orden":5,"grupo":"energia-5.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la carga inteligente de autos ayuda a la red.","items":[{"id":"i1","texto":"Muchos autos eléctricos se conectan al llegar a casa"},{"id":"i2","texto":"Si todos cargan a las 19, se suma demanda al pico"},{"id":"i3","texto":"Con carga programada, esperan a la madrugada o al mediodía"},{"id":"i4","texto":"Absorben energía cuando sobra"},{"id":"i5","texto":"La red usa mejor su capacidad y se recorta menos"},{"id":"i6","texto":"Los autos generan electricidad al estacionar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo que podía ser un problema se vuelve una ayuda, según cuándo se carga."}},{"slug":"energia-5.s4.p6","orden":6,"grupo":"energia-5.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La transmisión, el cuello de botella","cuerpo":["Los mejores lugares para generar no siempre están cerca de donde se consume: el viento más fuerte está en la Patagonia y el sol más intenso en el noroeste, mientras que la mayor demanda está en el centro del país. Llevar esa energía requiere líneas de alta tensión, que tardan años en construirse. En Argentina, la falta de capacidad de transmisión en algunas regiones limitó la conexión de nuevos parques renovables."]},"solucion":{}},{"slug":"energia-5.s4.p7","orden":7,"grupo":"energia-5.s4.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la falta de líneas de transmisión frena nuevas renovables en Argentina?","opciones":[{"id":"o1","texto":"Los mejores recursos están lejos de la demanda"},{"id":"o2","texto":"Porque las renovables no necesitan cables"},{"id":"o3","texto":"Porque en el centro del país no se consume electricidad"},{"id":"o4","texto":"Porque las líneas solo transportan electricidad de gas"}]},"solucion":{"clave":["o1"],"explicacion":"Sin líneas, la mejor energía del país no puede llegar a donde se la necesita.","por_opcion":{"o3":"Es al revés: la mayor demanda está en el centro."}}},{"slug":"energia-5.s4.p8","orden":8,"grupo":"energia-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea de transmisión puede llevar 1.000 MW y ya lleva 950 MW en las horas de mucho viento. ¿Cuántos MW de parques nuevos podría sumar sin ampliarla?","unidad":"MW","decimales":0,"contexto":"Capacidad 1000 MW; ocupación 950 MW."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"1.000 − 950 = 50 MW. Más allá de eso, cada parque nuevo sería recortado en las horas de mucho viento."}},{"slug":"energia-5.s4.p8.v2","orden":8,"grupo":"energia-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea de transmisión puede llevar 800 MW y ya lleva 760 MW en las horas de mucho viento. ¿Cuántos MW de parques nuevos podría sumar sin ampliarla?","unidad":"MW","decimales":0,"contexto":"Capacidad 800 MW; ocupación 760 MW."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"800 − 760 = 40 MW. Más allá de eso, cada parque nuevo sería recortado en las horas de mucho viento."}},{"slug":"energia-5.s4.p8.v3","orden":8,"grupo":"energia-5.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una línea de transmisión puede llevar 1.500 MW y ya lleva 1.350 MW en las horas de mucho viento. ¿Cuántos MW de parques nuevos podría sumar sin ampliarla?","unidad":"MW","decimales":0,"contexto":"Capacidad 1500 MW; ocupación 1350 MW."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"1.500 − 1.350 = 150 MW. Más allá de eso, cada parque nuevo sería recortado en las horas de mucho viento."}},{"slug":"energia-5.s4.p9","orden":9,"grupo":"energia-5.s4.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada consumo con el mejor momento para hacerlo en una red con mucho sol.","izquierda":[{"id":"a1","texto":"Cargar un auto eléctrico"},{"id":"a2","texto":"Calentar agua en un termotanque eléctrico"},{"id":"a3","texto":"Bombear agua a un tanque elevado"},{"id":"a4","texto":"Enfriar una cámara frigorífica"}],"derecha":[{"id":"b1","texto":"Mediodía soleado o madrugada"},{"id":"b2","texto":"Horas de más sol"},{"id":"b3","texto":"Horas de poca demanda"},{"id":"b4","texto":"Antes del pico, para no enfriar durante el pico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Muchos consumos pueden adelantarse o atrasarse sin perder su servicio."}},{"slug":"energia-5.s4.p10","orden":10,"grupo":"energia-5.s4.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas soluciones según cuánto tiempo suelen tardar en implementarse, de la más rápida a la más lenta.","items":[{"id":"i1","texto":"Tarifa por horario para cargar autos"},{"id":"i2","texto":"Baterías junto a un transformador saturado"},{"id":"i3","texto":"Parque eólico nuevo"},{"id":"i4","texto":"Línea de alta tensión de cientos de kilómetros"}],"extremos":["Más rápida","Más lenta"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las soluciones rápidas compran tiempo mientras se construyen las lentas.","valores":{"i1":"meses","i2":"uno o dos años","i3":"dos o tres años","i4":"muchos años"}}},{"slug":"energia-5.s4.p11","orden":11,"grupo":"energia-5.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una línea de transmisión nueva beneficia solo a la región donde se generan las renovables.","razones":[{"id":"r1","texto":"Porque beneficia a todo el sistema, incluidos los consumidores"},{"id":"r2","texto":"Porque las líneas solo sirven para exportar"},{"id":"r3","texto":"Porque la transmisión no afecta los precios"}]},"solucion":{"valor":false,"explicacion":"Permite llevar energía barata y limpia a los centros de consumo, reduce el recorte y hace más confiable todo el sistema.","clave":["r1"]}},{"slug":"energia-5.s4.p12","orden":12,"grupo":"energia-5.s4.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas aportan flexibilidad a un sistema eléctrico? Marcá todas.","opciones":[{"id":"o1","texto":"Tarifas por horario"},{"id":"o2","texto":"Carga programada de autos eléctricos"},{"id":"o3","texto":"Líneas que unen regiones"},{"id":"o4","texto":"Baterías"},{"id":"o5","texto":"Prohibir que la demanda cambie"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La flexibilidad viene de la demanda, del almacenamiento y de la red, no solo de las centrales."}},{"slug":"energia-5.s4.p13","orden":13,"grupo":"energia-5.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta y marcá lo que no se sostiene.","segmentos":[{"id":"s1","texto":"Programaremos la carga de los colectivos eléctricos de madrugada."},{"id":"s2","texto":"No hacen falta líneas: la energía patagónica llegará sola a Buenos Aires."},{"id":"s3","texto":"Ofreceremos tarifas más bajas en horas de mucho sol."},{"id":"s4","texto":"Todos los consumos se pueden mover sin problema."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La flexibilidad es poderosa, pero tiene límites que hay que respetar.","por_opcion":{"s2":"Sin líneas de transmisión, la energía no llega.","s4":"Algunos, como un respirador o un quirófano, no se pueden mover."}}},{"slug":"energia-5.s4.p14","orden":14,"grupo":"energia-5.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Mover consumos a las horas con más sol o viento es flexibilidad de la {{0}}; las tarifas que cambian por hora se llaman tarifas por {{1}}; y en Argentina muchas renovables esperan líneas de {{2}}.","banco":[{"id":"w1","texto":"demanda"},{"id":"w2","texto":"horario"},{"id":"w3","texto":"transmisión"},{"id":"w4","texto":"oferta"},{"id":"w5","texto":"color"},{"id":"w6","texto":"teléfono"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la flexibilidad y la red."}}]},{"slug":"energia-5.s5","orden":5,"tipo":"leccion","titulo_es":"Planificar una red limpia y confiable","bajada_es":"Combinar soluciones, medir la confiabilidad y avanzar por etapas sin apagones.","minutos":10,"pasos":[{"slug":"energia-5.s5.p1","orden":1,"grupo":"energia-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La confiabilidad","cuerpo":["Una red tiene que ser limpia y barata, pero sobre todo confiable: que haya electricidad cuando se la necesita, incluso en la ola de calor más fuerte o en la semana con menos viento. Por eso los planificadores miran los peores momentos, no los promedios. Un sistema con muchas renovables necesita suficiente capacidad firme —centrales despachables, embalses, baterías, importación o demanda que se puede reducir— para cubrir esos momentos."]},"solucion":{}},{"slug":"energia-5.s5.p2","orden":2,"grupo":"energia-5.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los planificadores miran los peores momentos y no los promedios?","opciones":[{"id":"o1","texto":"Un apagón en el peor momento sale muy caro"},{"id":"o2","texto":"Porque los promedios siempre están mal calculados"},{"id":"o3","texto":"Porque los peores momentos nunca ocurren"},{"id":"o4","texto":"Porque así se construyen menos centrales"}]},"solucion":{"clave":["o1"],"explicacion":"La confiabilidad se juega en las horas más exigentes del año.","por_opcion":{"o3":"Ocurren: olas de calor, semanas sin viento, fallas."}}},{"slug":"energia-5.s5.p3","orden":3,"grupo":"energia-5.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una cartera de soluciones","cuerpo":["No hay una solución única. Los estudios de agencias como la Agencia Internacional de Energía y la IRENA coinciden en que los sistemas con mucha energía renovable combinan varias herramientas: diversidad de fuentes y lugares, pronósticos, redes más fuertes e interconectadas, almacenamiento de distintas duraciones, demanda flexible y centrales que puedan cubrir los momentos críticos, que con el tiempo usen menos combustible fósil."]},"solucion":{}},{"slug":"energia-5.s5.p4","orden":4,"grupo":"energia-5.s5.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué incluye una cartera de soluciones para un sistema con mucha energía renovable? Marcá todo.","opciones":[{"id":"o1","texto":"Fuentes y lugares diversos"},{"id":"o2","texto":"Redes más fuertes e interconectadas"},{"id":"o3","texto":"Almacenamiento de distintas duraciones"},{"id":"o4","texto":"Demanda flexible"},{"id":"o5","texto":"Depender de una sola tecnología"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La diversidad hace al sistema más robusto frente a lo imprevisto."}},{"slug":"energia-5.s5.p5","orden":5,"grupo":"energia-5.s5.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená una estrategia por etapas para integrar más renovables a una red.","items":[{"id":"i1","texto":"Sumar renovables donde la red todavía tiene capacidad"},{"id":"i2","texto":"Mejorar los pronósticos y el despacho"},{"id":"i3","texto":"Agregar baterías y tarifas que muevan la demanda"},{"id":"i4","texto":"Construir las líneas que conectan los mejores recursos"},{"id":"i5","texto":"Reemplazar gradualmente la generación fósil"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada etapa prepara a la red para la siguiente, sin arriesgar la confiabilidad."}},{"slug":"energia-5.s5.p6","orden":6,"grupo":"energia-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El pico de demanda esperado es de 2.000 MW y la capacidad firme disponible es de 1.700 MW. ¿Cuántos MW firmes faltan para cubrir el pico?","unidad":"MW","decimales":0,"contexto":"Pico 2000 MW; capacidad firme 1700 MW."},"solucion":{"valor":300,"tolerancia":6,"explicacion":"2.000 − 1.700 = 300 MW. Pueden venir de baterías, demanda que se reduce en el pico, importación o centrales despachables."}},{"slug":"energia-5.s5.p6.v2","orden":6,"grupo":"energia-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El pico de demanda esperado es de 1.500 MW y la capacidad firme disponible es de 1.350 MW. ¿Cuántos MW firmes faltan para cubrir el pico?","unidad":"MW","decimales":0,"contexto":"Pico 1500 MW; capacidad firme 1350 MW."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"1.500 − 1.350 = 150 MW. Pueden venir de baterías, demanda que se reduce en el pico, importación o centrales despachables."}},{"slug":"energia-5.s5.p6.v3","orden":6,"grupo":"energia-5.s5.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El pico de demanda esperado es de 3.000 MW y la capacidad firme disponible es de 2.400 MW. ¿Cuántos MW firmes faltan para cubrir el pico?","unidad":"MW","decimales":0,"contexto":"Pico 3000 MW; capacidad firme 2400 MW."},"solucion":{"valor":600,"tolerancia":12,"explicacion":"3.000 − 2.400 = 600 MW. Pueden venir de baterías, demanda que se reduce en el pico, importación o centrales despachables."}},{"slug":"energia-5.s5.p7","orden":7,"grupo":"energia-5.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta fuente aporta capacidad firme para el pico o no?","grupos":[{"id":"g1","nombre":"Aporta capacidad firme"},{"id":"g2","nombre":"No es firme por sí sola"}],"items":[{"id":"i1","texto":"Batería cargada antes del pico"},{"id":"i2","texto":"Parque solar en un pico nocturno"},{"id":"i3","texto":"Embalse con agua disponible"},{"id":"i4","texto":"Parque eólico en una tarde sin viento"},{"id":"i5","texto":"Demanda industrial que se compromete a reducirse"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Lo firme es lo que está disponible cuando se lo necesita, pase lo que pase con el clima."}},{"slug":"energia-5.s5.p8","orden":8,"grupo":"energia-5.s5.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un sistema con mucha energía renovable no puede ser confiable.","razones":[{"id":"r1","texto":"Porque la confiabilidad depende del diseño del sistema"},{"id":"r2","texto":"Porque las renovables no generan electricidad"},{"id":"r3","texto":"Porque los sistemas fósiles nunca fallan"}]},"solucion":{"valor":false,"explicacion":"Con una cartera de soluciones —redes, almacenamiento, demanda flexible y capacidad firme— puede serlo. La confiabilidad depende del diseño, no solo de la fuente.","clave":["r1"]}},{"slug":"energia-5.s5.p9","orden":9,"grupo":"energia-5.s5.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la diversidad hace más robusta a la red.","items":[{"id":"i1","texto":"Hay sol, viento, agua y otras fuentes en distintos lugares"},{"id":"i2","texto":"Es poco probable que todas fallen a la vez"},{"id":"i3","texto":"Cuando una baja, otras compensan"},{"id":"i4","texto":"Se necesita menos respaldo caro"},{"id":"i5","texto":"La red es más confiable y más barata"},{"id":"i6","texto":"Todas las fuentes fallan siempre al mismo tiempo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"No poner todos los huevos en la misma canasta, aplicado a la energía."}},{"slug":"energia-5.s5.p10","orden":10,"grupo":"energia-5.s5.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una solución.","izquierda":[{"id":"a1","texto":"Rampa del atardecer"},{"id":"a2","texto":"Recorte por líneas llenas"},{"id":"a3","texto":"Pico de demanda en ola de calor"},{"id":"a4","texto":"Semana sin viento"}],"derecha":[{"id":"b1","texto":"Baterías y centrales rápidas"},{"id":"b2","texto":"Nuevas líneas de transmisión"},{"id":"b3","texto":"Demanda que se reduce en el pico"},{"id":"b4","texto":"Embalses y capacidad firme"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada desafío tiene herramientas específicas."}},{"slug":"energia-5.s5.p11","orden":11,"grupo":"energia-5.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos recursos de menor a mayor costo típico para cubrir unas pocas horas de pico al año.","items":[{"id":"i1","texto":"Pedir a grandes usuarios que reduzcan el consumo"},{"id":"i2","texto":"Descargar baterías que ya existen"},{"id":"i3","texto":"Encender turbinas a gasoil"},{"id":"i4","texto":"Construir una central nueva solo para esas horas"}],"extremos":["Más barato","Más caro"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Para pocas horas al año, lo más barato suele ser gestionar la demanda y usar lo que ya existe.","valores":{"i1":"muy bajo","i2":"bajo","i3":"alto","i4":"muy alto"}}},{"slug":"energia-5.s5.p12","orden":12,"grupo":"energia-5.s5.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan energético provincial y marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Evaluaremos la red en la peor semana del año, no solo en promedio."},{"id":"s2","texto":"Sumaremos parques aunque no haya líneas para llevar su energía."},{"id":"s3","texto":"Combinaremos baterías, demanda flexible y centrales de respaldo."},{"id":"s4","texto":"Apagaremos todas las térmicas mañana, sin respaldo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Planificar bien es avanzar rápido sin poner en riesgo el suministro.","por_opcion":{"s2":"Se recortaría su generación; hay que planificar la red a la par.","s4":"La transición debe ser gradual y garantizar la confiabilidad."}}},{"slug":"energia-5.s5.p13","orden":13,"grupo":"energia-5.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Que haya electricidad incluso en el peor momento es la {{0}} de la red; lo que está disponible pase lo que pase con el clima es capacidad {{1}}; y combinar muchas herramientas es armar una {{2}} de soluciones.","banco":[{"id":"w1","texto":"confiabilidad"},{"id":"w2","texto":"firme"},{"id":"w3","texto":"cartera"},{"id":"w4","texto":"estética"},{"id":"w5","texto":"variable"},{"id":"w6","texto":"receta"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para planificar una red limpia y confiable."}}]},{"slug":"energia-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: una red para las renovables","bajada_es":"Despacho, curva del pato, baterías, flexibilidad, transmisión y confiabilidad, mezclados.","minutos":8,"pasos":[{"slug":"energia-5.s6.p1","orden":1,"grupo":"energia-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Una red para las renovables». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"energia-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la noche sin viento","bajada_es":"Una provincia con mucho sol y viento quiere dejar de depender de sus turbinas a gasoil en las noches de verano. Con los datos, diseñá la solución.","minutos":10,"pasos":[{"slug":"energia-5.s7.p1","orden":1,"grupo":"energia-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["En una noche típica de verano sin viento, entre las 19 y las 23 la provincia necesita 300 MW más de lo que pueden dar sus centrales firmes, y hoy los cubre con turbinas a gasoil. Durante el día, con mucho sol, se recortan en promedio 900 MWh de energía solar porque no hay demanda ni líneas para llevarla. La distribuidora propone baterías; una cámara industrial ofrece reducir 60 MW en esas horas a cambio de un pago."]},"solucion":{}},{"slug":"energia-5.s7.p2","orden":2,"grupo":"energia-5.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si las industrias reducen 60 MW, ¿cuántos MW quedan por cubrir entre las 19 y las 23?","unidad":"MW","decimales":0,"contexto":"Faltan 300 MW; la industria reduce 60 MW."},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"300 − 60 = 240 MW. La flexibilidad de la demanda achica el problema antes de invertir."}},{"slug":"energia-5.s7.p3","orden":3,"grupo":"energia-5.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos MWh de baterías hacen falta para entregar 240 MW durante 4 horas?","unidad":"MWh","decimales":0,"contexto":"240 MW durante 4 horas, de 19 a 23."},"solucion":{"valor":960,"tolerancia":19.2,"explicacion":"240 MW × 4 horas = 960 MWh. Un sistema de 240 MW y 960 MWh."}},{"slug":"energia-5.s7.p4","orden":4,"grupo":"energia-5.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esas baterías se cargan con la solar que hoy se recorta, con una eficiencia del 88 %, ¿cuántos MWh recortados harían falta para cargarlas? Redondeá al entero.","unidad":"MWh","decimales":0,"contexto":"960 MWh a entregar; eficiencia del 88 %."},"solucion":{"valor":1091,"tolerancia":21.82,"explicacion":"960 ÷ 0,88 ≈ 1.091 MWh. Hoy se recortan unos 900 MWh: cubriría la mayor parte, y el resto se cargaría de la red en horas baratas."}},{"slug":"energia-5.s7.p5","orden":5,"grupo":"energia-5.s7.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios tendría la solución? Marcá todos.","opciones":[{"id":"o1","texto":"Menos gasoil quemado en las noches de verano"},{"id":"o2","texto":"Aprovechar energía solar que hoy se desperdicia"},{"id":"o3","texto":"Menor costo marginal en las horas pico"},{"id":"o4","texto":"Más recorte de energía solar"},{"id":"o5","texto":"Más emisiones en las horas pico"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Baterías y demanda flexible atacan dos problemas a la vez: el recorte del día y el gasoil de la noche."}},{"slug":"energia-5.s7.p6","orden":6,"grupo":"energia-5.s7.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene sumar primero la reducción industrial antes de dimensionar las baterías?","opciones":[{"id":"o1","texto":"Achica el problema y las baterías resultan más chicas"},{"id":"o2","texto":"Porque las baterías no sirven para las noches"},{"id":"o3","texto":"Porque las industrias pagan la electricidad más cara"},{"id":"o4","texto":"Porque la ley lo exige siempre"}]},"solucion":{"clave":["o1"],"explicacion":"La flexibilidad más barata va primero; la inversión se dimensiona para lo que queda.","por_opcion":{"o3":"No es el motivo: se trata de reducir lo que hay que cubrir."}}},{"slug":"energia-5.s7.p7","orden":7,"grupo":"energia-5.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con las baterías, la provincia ya no necesita ninguna capacidad de respaldo para una semana entera sin sol ni viento.","razones":[{"id":"r1","texto":"Porque las baterías cubren horas, no semanas"},{"id":"r2","texto":"Porque en una semana sin viento no hay demanda"},{"id":"r3","texto":"Porque las baterías duran para siempre"}]},"solucion":{"valor":false,"explicacion":"Las baterías cubren horas. Para varios días seguidos sin sol ni viento hacen falta otras fuentes firmes, importación o reservas de más larga duración.","clave":["r1"]}},{"slug":"energia-5.s7.p8","orden":8,"grupo":"energia-5.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La provincia redacta su plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Contrataremos 60 MW de reducción industrial para las noches de verano."},{"id":"s2","texto":"Instalaremos 240 MW de baterías, con 240 MWh de energía."},{"id":"s3","texto":"Cargaremos las baterías con la solar que hoy se recorta."},{"id":"s4","texto":"Desmantelaremos todas las turbinas el primer año."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan cuida los números, la confiabilidad y el ritmo de la transición.","por_opcion":{"s2":"Para 4 horas hacen falta 960 MWh: confunde potencia con energía.","s4":"Conviene mantener respaldo para los días más críticos mientras se completa la transición."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"energia-6","rama":"energia","orden":6,"nivel":3,"titulo_es":"La transición energética en Argentina","bajada_es":"Gas de Vaca Muerta, viento patagónico, sol del noroeste y hogares que usan garrafa: de dónde partimos, qué se discute y cómo sería una transición justa y posible.","objetivos_es":["Describir la matriz energética primaria y la matriz eléctrica argentinas","Analizar los argumentos del debate sobre el gas de Vaca Muerta","Evaluar el avance de las renovables frente a la meta de la Ley 27.191","Explicar la pobreza energética y sus diferencias regionales","Diseñar una hoja de ruta de transición que combine clima, economía y justicia"],"repasa":["energia-5","energia-4","consumo-4","comunidad-3"],"requiere_tronco":3,"fuentes":["argendata-transicion","cammesa","ley-27191-renovables","renovables-2025-ar","balanza-energetica-2024","iea-metano-2025","censo-gas-2022","inventario-gei-ar"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"energia-6.s1","orden":1,"tipo":"leccion","titulo_es":"De dónde partimos","bajada_es":"La energía primaria del país y la electricidad: dos matrices distintas que conviene no confundir.","minutos":10,"pasos":[{"slug":"energia-6.s1.p1","orden":1,"grupo":"energia-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos matrices","cuerpo":["La matriz energética primaria incluye toda la energía que usa el país: la que se quema en autos, camiones, industrias, calefacción y cocinas, y la que se usa para generar electricidad. En Argentina, el gas natural aporta alrededor de la mitad de esa energía y el petróleo cerca de un tercio: es una de las matrices más gasíferas del mundo.","La matriz eléctrica es solo la parte que se convierte en electricidad. Allí, en 2024, alrededor de la mitad vino de centrales térmicas (mayormente a gas), cerca de un cuarto de grandes represas, alrededor del 16 % de renovables como el viento y el sol, y cerca del 8 % de centrales nucleares."],"datos":{"tipo":"barras","titulo":"Matriz eléctrica argentina, 2024 (aproximado)","unidad":"%","filas":[{"etiqueta":"Térmica (mayormente gas)","valor":51},{"etiqueta":"Hidráulica de gran escala","valor":25},{"etiqueta":"Renovables (eólica, solar y otras)","valor":16},{"etiqueta":"Nuclear","valor":8}],"nota":"CAMMESA; valores redondeados que varían según el año hidrológico."}},"solucion":{}},{"slug":"energia-6.s1.p2","orden":2,"grupo":"energia-6.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto forma parte solo de la matriz primaria o también de la matriz eléctrica?","grupos":[{"id":"g1","nombre":"Solo de la primaria (no pasa por la red eléctrica)"},{"id":"g2","nombre":"También de la eléctrica"}],"items":[{"id":"i1","texto":"Nafta que carga un auto"},{"id":"i2","texto":"Gas que se quema en una central térmica"},{"id":"i3","texto":"Gas que se quema en una cocina"},{"id":"i4","texto":"Agua que mueve una represa"},{"id":"i5","texto":"Gasoil de un camión"},{"id":"i6","texto":"Viento que mueve un aerogenerador"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La electricidad es solo una parte de la energía: el transporte y la calefacción a gas quedan fuera de la matriz eléctrica."}},{"slug":"energia-6.s1.p3","orden":3,"grupo":"energia-6.s1.p3","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las fuentes de la matriz eléctrica argentina de 2024, de mayor a menor aporte.","items":[{"id":"i1","texto":"Térmica, mayormente gas"},{"id":"i2","texto":"Hidráulica de gran escala"},{"id":"i3","texto":"Renovables como viento y sol"},{"id":"i4","texto":"Nuclear"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Casi la mitad de la electricidad ya viene de fuentes que no queman combustibles fósiles.","valores":{"i1":"≈ 51 %","i2":"≈ 25 %","i3":"≈ 16 %","i4":"≈ 8 %"}}},{"slug":"energia-6.s1.p4","orden":4,"grupo":"energia-6.s1.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si toda la electricidad del país fuera renovable, ¿se resolverían las emisiones de energía de Argentina?","opciones":[{"id":"o1","texto":"No: transporte y calefacción usan combustibles directamente"},{"id":"o2","texto":"Sí, porque toda la energía es electricidad"},{"id":"o3","texto":"Sí, porque los autos no emiten"},{"id":"o4","texto":"No, porque la electricidad renovable emite más que el gas"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso la transición incluye electrificar usos (autos, calefacción con bombas de calor) además de limpiar la red.","por_opcion":{"o3":"Los autos a nafta y gasoil emiten, y no pasan por la red."}}},{"slug":"energia-6.s1.p5","orden":5,"grupo":"energia-6.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de cada 100 MWh de electricidad, 51 vienen de centrales térmicas, ¿qué porcentaje no viene de combustibles fósiles?","unidad":"%","decimales":0,"contexto":"Total 100; térmica 51."},"solucion":{"valor":49,"tolerancia":1,"explicacion":"(100 − 51) ÷ 100 × 100 ≈ 49 %. Casi la mitad de la electricidad ya no depende de quemar combustibles."}},{"slug":"energia-6.s1.p5.v2","orden":5,"grupo":"energia-6.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un año se generan 150.000 GWh y 76.500 GWh son térmicos. ¿Qué porcentaje es de otras fuentes? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Total 150000; térmica 76500."},"solucion":{"valor":49,"tolerancia":1,"explicacion":"(150.000 − 76.500) ÷ 150.000 × 100 ≈ 49 %. Casi la mitad de la electricidad ya no depende de quemar combustibles."}},{"slug":"energia-6.s1.p5.v3","orden":5,"grupo":"energia-6.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la generación total es de 140.000 GWh y la térmica de 72.000 GWh, ¿qué porcentaje aportan hidráulica, nuclear y renovables juntas? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"Total 140000; térmica 72000."},"solucion":{"valor":49,"tolerancia":1,"explicacion":"(140.000 − 72.000) ÷ 140.000 × 100 ≈ 49 %. Casi la mitad de la electricidad ya no depende de quemar combustibles."}},{"slug":"energia-6.s1.p6","orden":6,"grupo":"energia-6.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Electrificar","cuerpo":["Como la electricidad puede generarse sin emisiones y los motores y bombas de calor eléctricos son muy eficientes, una estrategia central de la transición es electrificar: pasar a la electricidad usos que hoy queman combustibles, como el transporte o la calefacción. Pero electrificar solo reduce emisiones si, al mismo tiempo, la electricidad se vuelve más limpia."]},"solucion":{}},{"slug":"energia-6.s1.p7","orden":7,"grupo":"energia-6.s1.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué electrificar y limpiar la red van juntos.","items":[{"id":"i1","texto":"Se pasan autos y calefacción a electricidad"},{"id":"i2","texto":"Aumenta la demanda eléctrica"},{"id":"i3","texto":"Si esa electricidad viene de renovables, bajan las emisiones"},{"id":"i4","texto":"Si viene de más gas, la mejora es menor"},{"id":"i5","texto":"Por eso hay que sumar renovables al mismo ritmo"},{"id":"i6","texto":"Electrificar reduce la demanda eléctrica"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Electrificar sin limpiar la red es cambiar el lugar de la chimenea."}},{"slug":"energia-6.s1.p8","orden":8,"grupo":"energia-6.s1.p8","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Matriz primaria"},{"id":"a2","texto":"Matriz eléctrica"},{"id":"a3","texto":"Electrificar"},{"id":"a4","texto":"Energía firme"}],"derecha":[{"id":"b1","texto":"Toda la energía que usa el país"},{"id":"b2","texto":"De dónde viene la electricidad"},{"id":"b3","texto":"Pasar usos a electricidad"},{"id":"b4","texto":"Disponible cuando se la necesita"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conceptos para no mezclar las discusiones sobre energía."}},{"slug":"energia-6.s1.p9","orden":9,"grupo":"energia-6.s1.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En Argentina, la mayor parte de la energía primaria viene de fuentes renovables.","razones":[{"id":"r1","texto":"Porque el gas y el petróleo aportan la mayor parte"},{"id":"r2","texto":"Porque Argentina no usa gas"},{"id":"r3","texto":"Porque la matriz primaria es solo electricidad"}]},"solucion":{"valor":false,"explicacion":"El gas natural aporta alrededor de la mitad y el petróleo cerca de un tercio: la matriz primaria es mayormente fósil, aunque la eléctrica esté más diversificada.","clave":["r1"]}},{"slug":"energia-6.s1.p10","orden":10,"grupo":"energia-6.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones reducen las emisiones de la energía en Argentina? Marcá todas.","opciones":[{"id":"o1","texto":"Sumar renovables a la red"},{"id":"o2","texto":"Electrificar transporte y calefacción con red limpia"},{"id":"o3","texto":"Mejorar la eficiencia de viviendas e industrias"},{"id":"o4","texto":"Reducir las fugas de metano en la cadena del gas"},{"id":"o5","texto":"Pasar centrales de gas a gasoil"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La transición combina limpiar, electrificar, ahorrar y controlar el metano."}},{"slug":"energia-6.s1.p11","orden":11,"grupo":"energia-6.s1.p11","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la energía primaria de Argentina aporta el gas natural.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":50,"banda":"lineal","explicacion":"Alrededor de la mitad: Argentina tiene una de las matrices primarias más dependientes del gas del mundo."}},{"slug":"energia-6.s1.p12","orden":12,"grupo":"energia-6.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El gas natural aporta alrededor de la mitad de la energía primaria."},{"id":"s2","texto":"Casi toda la electricidad argentina viene de centrales nucleares."},{"id":"s3","texto":"Cerca de un cuarto de la electricidad viene de grandes represas."},{"id":"s4","texto":"Si la red fuera 100 % renovable, desaparecerían todas las emisiones de energía."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Tener los datos claros evita discusiones con números equivocados.","por_opcion":{"s2":"La nuclear aporta cerca del 8 %.","s4":"Transporte y calefacción siguen quemando combustibles si no se electrifican."}}},{"slug":"energia-6.s1.p13","orden":13,"grupo":"energia-6.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Toda la energía que usa un país forma la matriz {{0}}; en Argentina, alrededor de la mitad viene del {{1}}; y pasar usos a la electricidad se llama {{2}}.","banco":[{"id":"w1","texto":"primaria"},{"id":"w2","texto":"gas"},{"id":"w3","texto":"electrificar"},{"id":"w4","texto":"eléctrica"},{"id":"w5","texto":"carbón"},{"id":"w6","texto":"importar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para entender de dónde parte la transición argentina."}}]},{"slug":"energia-6.s2","orden":2,"tipo":"leccion","titulo_es":"El gas de Vaca Muerta","bajada_es":"Dólares, empleo y seguridad energética de un lado; metano, bloqueo y riesgos del otro: el debate sobre el gas.","minutos":12,"pasos":[{"slug":"energia-6.s2.p1","orden":1,"grupo":"energia-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es Vaca Muerta","cuerpo":["Vaca Muerta es una formación geológica de Neuquén y provincias vecinas que contiene enormes recursos de gas y petróleo no convencionales, que se extraen con perforación horizontal y fractura hidráulica. Su desarrollo creció mucho en la última década. En 2024, impulsada por Vaca Muerta, Argentina tuvo un superávit comercial energético de unos 5.668 millones de dólares: exportó energía por unos 9.677 millones e importó por unos 4.009 millones, después de años de déficit."]},"solucion":{}},{"slug":"energia-6.s2.p2","orden":2,"grupo":"energia-6.s2.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Argentina exportó energía por 9.677 millones de dólares e importó por 4.009 millones en 2024, ¿cuál fue el superávit, en millones de dólares?","unidad":"millones de dólares","decimales":0,"contexto":"Exportaciones 9.677; importaciones 4.009 millones de dólares."},"solucion":{"valor":5668,"tolerancia":113.36,"explicacion":"9.677 − 4.009 = 5.668 millones de dólares, el mayor superávit energético en muchos años."}},{"slug":"energia-6.s2.p3","orden":3,"grupo":"energia-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los argumentos a favor","cuerpo":["Quienes impulsan el gas destacan que genera divisas, empleo y recaudación, que da seguridad energética al no depender de importaciones, que el gas emite menos CO₂ que el carbón y el petróleo al quemarse, y que exportado como gas natural licuado podría reemplazar carbón en otros países. También que las centrales a gas pueden dar la energía firme que las renovables necesitan como respaldo."]},"solucion":{}},{"slug":"energia-6.s2.p4","orden":4,"grupo":"energia-6.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los argumentos en contra o de precaución","cuerpo":["Quienes piden cautela señalan que el metano que se escapa en la extracción y el transporte calienta mucho y puede achicar o anular la ventaja del gas; que invertir en infraestructura que dura décadas puede bloquear la transición; que si el mundo reduce el uso de fósiles, esas inversiones pueden perder valor (activos varados); y los impactos locales del fracking: uso de agua y arena, tránsito de camiones, residuos y efectos sobre comunidades."]},"solucion":{}},{"slug":"energia-6.s2.p5","orden":5,"grupo":"energia-6.s2.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un argumento a favor del gas o de precaución?","grupos":[{"id":"g1","nombre":"A favor"},{"id":"g2","nombre":"De precaución"}],"items":[{"id":"i1","texto":"Genera divisas por exportaciones"},{"id":"i2","texto":"Las fugas de metano calientan mucho"},{"id":"i3","texto":"Da seguridad energética"},{"id":"i4","texto":"Infraestructura que puede bloquear la transición"},{"id":"i5","texto":"Puede dar respaldo firme a las renovables"},{"id":"i6","texto":"Riesgo de activos varados si baja la demanda mundial"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Un debate serio pone todos los argumentos sobre la mesa y los pesa con datos."}},{"slug":"energia-6.s2.p6","orden":6,"grupo":"energia-6.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El metano, la clave","cuerpo":["Según la Agencia Internacional de Energía, la industria del petróleo y el gas emite grandes cantidades de metano por fugas, venteos y quemas incompletas, y una parte importante de esas emisiones se puede evitar con tecnologías que ya existen, muchas veces a bajo costo o incluso con ganancia, porque el gas que no se escapa se puede vender. Controlar el metano es una de las formas más rápidas de reducir el calentamiento en las próximas décadas."]},"solucion":{}},{"slug":"energia-6.s2.p7","orden":7,"grupo":"energia-6.s2.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué las fugas de metano pueden anular la ventaja del gas.","items":[{"id":"i1","texto":"Al quemarse, el gas emite menos CO₂ que el carbón"},{"id":"i2","texto":"Pero en la extracción y el transporte se escapa metano"},{"id":"i3","texto":"El metano calienta mucho más que el CO₂ en el corto plazo"},{"id":"i4","texto":"Si las fugas son grandes, el balance total empeora"},{"id":"i5","texto":"La ventaja climática del gas se achica o desaparece"},{"id":"i6","texto":"Las fugas de metano enfrían la atmósfera"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La ventaja del gas depende de cuánto se escapa: medir y controlar el metano es decisivo."}},{"slug":"energia-6.s2.p8","orden":8,"grupo":"energia-6.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué medida mejora el balance climático del gas sin dejar de producirlo?","opciones":[{"id":"o1","texto":"Detectar y reparar fugas, y evitar venteos"},{"id":"o2","texto":"Aumentar la quema de gas en antorcha sin control"},{"id":"o3","texto":"Dejar de medir las emisiones para ahorrar"},{"id":"o4","texto":"Reemplazar gas por carbón en las centrales"}]},"solucion":{"clave":["o1"],"explicacion":"Controlar el metano es barato comparado con su efecto: una de las mejores inversiones climáticas.","por_opcion":{"o3":"Sin medir no se sabe qué reparar."}}},{"slug":"energia-6.s2.p9","orden":9,"grupo":"energia-6.s2.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué impactos locales de la extracción no convencional conviene controlar? Marcá todos.","opciones":[{"id":"o1","texto":"El uso de agua y su tratamiento"},{"id":"o2","texto":"El tránsito intenso de camiones"},{"id":"o3","texto":"Los residuos de la perforación"},{"id":"o4","texto":"Los efectos sobre comunidades cercanas"},{"id":"o5","texto":"La cantidad de turistas en la costa atlántica"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Además del clima, la actividad tiene impactos locales que requieren control y participación."}},{"slug":"energia-6.s2.p10","orden":10,"grupo":"energia-6.s2.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Fractura hidráulica"},{"id":"a2","texto":"Activo varado"},{"id":"a3","texto":"Bloqueo"},{"id":"a4","texto":"Venteo"}],"derecha":[{"id":"b1","texto":"Inyectar agua, arena y aditivos para liberar gas de la roca"},{"id":"b2","texto":"Inversión que pierde valor antes de lo previsto"},{"id":"b3","texto":"Infraestructura que ata el futuro a una tecnología"},{"id":"b4","texto":"Liberar gas a la atmósfera sin quemarlo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario clave del debate sobre el gas."}},{"slug":"energia-6.s2.p11","orden":11,"grupo":"energia-6.s2.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El gas natural es una energía limpia sin impacto climático.","razones":[{"id":"r1","texto":"Porque emite CO₂ y sus fugas de metano calientan"},{"id":"r2","texto":"Porque el gas no emite nada al quemarse"},{"id":"r3","texto":"Porque el gas es renovable"}]},"solucion":{"valor":false,"explicacion":"Emite CO₂ al quemarse, aunque menos que el carbón, y sus fugas de metano pueden aumentar mucho su impacto. Es un combustible fósil.","clave":["r1"]}},{"slug":"energia-6.s2.p12","orden":12,"grupo":"energia-6.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 100 toneladas de metano producidas se escapa el 2 %, ¿cuántas toneladas de CO₂e representan esas fugas, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":1,"contexto":"100 t de metano; fuga del 2 %; potencial 28."},"solucion":{"valor":56,"tolerancia":0.1,"explicacion":"100 × 2 % = 2 t de metano × 28 = 56 t CO₂e. Pequeños porcentajes de fuga pesan mucho en el balance."}},{"slug":"energia-6.s2.p12.v2","orden":12,"grupo":"energia-6.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 100 toneladas de metano producidas se escapa el 3 %, ¿cuántas toneladas de CO₂e representan esas fugas, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":1,"contexto":"100 t de metano; fuga del 3 %; potencial 28."},"solucion":{"valor":84,"tolerancia":0.1,"explicacion":"100 × 3 % = 3 t de metano × 28 = 84 t CO₂e. Pequeños porcentajes de fuga pesan mucho en el balance."}},{"slug":"energia-6.s2.p12.v3","orden":12,"grupo":"energia-6.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si de 100 toneladas de metano producidas se escapa el 1 %, ¿cuántas toneladas de CO₂e representan esas fugas, si el metano vale 28 veces el CO₂?","unidad":"t CO₂e","decimales":1,"contexto":"100 t de metano; fuga del 1 %; potencial 28."},"solucion":{"valor":28,"tolerancia":0.1,"explicacion":"100 × 1 % = 1 t de metano × 28 = 28 t CO₂e. Pequeños porcentajes de fuga pesan mucho en el balance."}},{"slug":"energia-6.s2.p13","orden":13,"grupo":"energia-6.s2.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para cubrir la demanda firme de una red con muchas renovables, de la de menores emisiones a la de mayores.","items":[{"id":"i1","texto":"Baterías cargadas con renovables"},{"id":"i2","texto":"Gas con control estricto de metano"},{"id":"i3","texto":"Gas con muchas fugas"},{"id":"i4","texto":"Gasoil en turbinas viejas"}],"extremos":["Menos emisiones","Más emisiones"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Aun dentro del gas, la forma de producirlo cambia mucho el resultado.","valores":{"i1":"mínimas","i2":"moderadas","i3":"altas","i4":"muy altas"}}},{"slug":"energia-6.s2.p14","orden":14,"grupo":"energia-6.s2.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este debate televisivo y marcá lo que no se sostiene.","segmentos":[{"id":"s1","texto":"Vaca Muerta ayudó a revertir el déficit energético."},{"id":"s2","texto":"El gas no tiene ningún impacto climático porque es natural."},{"id":"s3","texto":"Controlar las fugas de metano mejora mucho el balance del gas."},{"id":"s4","texto":"Si invertimos en gas, nunca hará falta pensar en la transición."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El debate sobre el gas mejora cuando se reconocen beneficios y riesgos con datos.","por_opcion":{"s2":"Es un fósil: emite CO₂ y metano.","s4":"Las inversiones de décadas pueden quedar varadas si baja la demanda de fósiles."}}},{"slug":"energia-6.s2.p15","orden":15,"grupo":"energia-6.s2.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La técnica para extraer gas no convencional se llama fractura {{0}}; una inversión que pierde valor antes de tiempo es un activo {{1}}; y el gas que se escapa sin quemarse es {{2}}.","banco":[{"id":"w1","texto":"hidráulica"},{"id":"w2","texto":"varado"},{"id":"w3","texto":"metano"},{"id":"w4","texto":"eléctrica"},{"id":"w5","texto":"dorado"},{"id":"w6","texto":"oxígeno"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para entender el debate sobre el gas."}}]},{"slug":"energia-6.s3","orden":3,"tipo":"leccion","titulo_es":"Viento, sol y una ley","bajada_es":"La Ley 27.191, los recursos renovables del país y cuánto se avanzó hacia la meta del 20 %.","minutos":11,"pasos":[{"slug":"energia-6.s3.p1","orden":1,"grupo":"energia-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Ley 27.191","cuerpo":["En 2015, la Ley 27.191 fijó metas para que una parte creciente de la electricidad viniera de fuentes renovables, hasta llegar al 20 % del consumo a fines de 2025. Para cumplirla hubo licitaciones públicas y un mercado para que las empresas compren energía renovable directamente. En pocos años se construyeron decenas de parques eólicos y solares."]},"solucion":{}},{"slug":"energia-6.s3.p2","orden":2,"grupo":"energia-6.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto se avanzó","cuerpo":["Según los datos de CAMMESA, a fines de 2024 las renovables cubrieron un récord de alrededor del 16 % de la demanda eléctrica, y en 2025 se sumaron más de 1.000 MW nuevos: en diciembre de 2025 cubrieron cerca del 19,6 % de la demanda de ese mes. En algunos momentos de mucho viento y sol, llegaron a cubrir más de un tercio de la demanda."],"destacado":{"valor":"≈ 19,6 %","texto":"de la demanda eléctrica de diciembre de 2025 fue cubierta con renovables, según datos de CAMMESA."}},"solucion":{}},{"slug":"energia-6.s3.p3","orden":3,"grupo":"energia-6.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es cubrir el 20 % de la demanda con renovables y se cubre el 16,1 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 20 %; cobertura 16.1 %."},"solucion":{"valor":3.9,"tolerancia":0.1,"explicacion":"20 − 16,1 = 3,9 puntos. Cerca de la meta, pero con el desafío de las líneas de transmisión para seguir creciendo."}},{"slug":"energia-6.s3.p3.v2","orden":3,"grupo":"energia-6.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es cubrir el 20 % de la demanda con renovables y se cubre el 19,6 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 20 %; cobertura 19.6 %."},"solucion":{"valor":0.4,"tolerancia":0.1,"explicacion":"20 − 19,6 = 0,4 puntos. Cerca de la meta, pero con el desafío de las líneas de transmisión para seguir creciendo."}},{"slug":"energia-6.s3.p3.v3","orden":3,"grupo":"energia-6.s3.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la meta es cubrir el 20 % de la demanda con renovables y se cubre el 17,5 %, ¿cuántos puntos porcentuales faltan?","unidad":"puntos porcentuales","decimales":1,"contexto":"Meta 20 %; cobertura 17.5 %."},"solucion":{"valor":2.5,"tolerancia":0.1,"explicacion":"20 − 17,5 = 2,5 puntos. Cerca de la meta, pero con el desafío de las líneas de transmisión para seguir creciendo."}},{"slug":"energia-6.s3.p4","orden":4,"grupo":"energia-6.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Recursos de primera","cuerpo":["Argentina tiene recursos renovables excepcionales. En la Patagonia, el viento es tan constante que muchos parques eólicos tienen factores de capacidad cercanos al 50 %, entre los más altos del mundo. En el noroeste, en la Puna, la radiación solar está entre las más altas del planeta. El desafío no es el recurso, sino llevar esa energía a donde se consume y financiar las obras."]},"solucion":{}},{"slug":"energia-6.s3.p5","orden":5,"grupo":"energia-6.s3.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada región con su recurso destacado.","izquierda":[{"id":"a1","texto":"Patagonia"},{"id":"a2","texto":"Noroeste y Puna"},{"id":"a3","texto":"Comahue y Litoral"},{"id":"a4","texto":"Zonas agrícolas"}],"derecha":[{"id":"b1","texto":"Viento fuerte y constante"},{"id":"b2","texto":"Radiación solar muy alta"},{"id":"b3","texto":"Grandes ríos y represas"},{"id":"b4","texto":"Biomasa y biogás de residuos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada región aporta un recurso distinto: la red los une."}},{"slug":"energia-6.s3.p6","orden":6,"grupo":"energia-6.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 100 MW tiene un factor de capacidad del 50 %. ¿Cuántos MWh genera en un año de 8.760 horas?","unidad":"MWh","decimales":0,"contexto":"100 MW; factor de capacidad 50 %; 8.760 horas."},"solucion":{"valor":438000,"tolerancia":1,"explicacion":"100 × 8.760 × 50 % = 438.000 MWh por año. Lo viste con el viento: el factor de capacidad define cuánto rinde un parque."}},{"slug":"energia-6.s3.p6.v2","orden":6,"grupo":"energia-6.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 50 MW tiene un factor de capacidad del 45 %. ¿Cuántos MWh genera en un año de 8.760 horas?","unidad":"MWh","decimales":0,"contexto":"50 MW; factor de capacidad 45 %; 8.760 horas."},"solucion":{"valor":197100,"tolerancia":1,"explicacion":"50 × 8.760 × 45 % = 197.100 MWh por año. Lo viste con el viento: el factor de capacidad define cuánto rinde un parque."}},{"slug":"energia-6.s3.p6.v3","orden":6,"grupo":"energia-6.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un parque eólico de 200 MW tiene un factor de capacidad del 40 %. ¿Cuántos MWh genera en un año de 8.760 horas?","unidad":"MWh","decimales":0,"contexto":"200 MW; factor de capacidad 40 %; 8.760 horas."},"solucion":{"valor":700800,"tolerancia":1,"explicacion":"200 × 8.760 × 40 % = 700.800 MWh por año. Lo viste con el viento: el factor de capacidad define cuánto rinde un parque."}},{"slug":"energia-6.s3.p7","orden":7,"grupo":"energia-6.s3.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el crecimiento de las renovables se frenó en algunas regiones.","items":[{"id":"i1","texto":"Los mejores vientos están lejos de las ciudades"},{"id":"i2","texto":"Se construyen muchos parques en esas zonas"},{"id":"i3","texto":"Las líneas que salen de la región se llenan"},{"id":"i4","texto":"Los parques nuevos no tienen por dónde enviar su energía"},{"id":"i5","texto":"Sin nuevas líneas, se frena la instalación"},{"id":"i6","texto":"Se frena porque el viento dejó de soplar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El recurso sobra; lo que falta es la red. Lo viste en la unidad anterior."}},{"slug":"energia-6.s3.p8","orden":8,"grupo":"energia-6.s3.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es hoy el principal límite para sumar más renovables en Argentina?","opciones":[{"id":"o1","texto":"La capacidad de las líneas de transmisión"},{"id":"o2","texto":"La falta de viento y de sol en el país"},{"id":"o3","texto":"Que las renovables son más caras que el gasoil"},{"id":"o4","texto":"Que la ley prohíbe nuevos parques"}]},"solucion":{"clave":["o1"],"explicacion":"Con recursos de primera, el cuello de botella es la infraestructura de red.","por_opcion":{"o3":"En general, hoy generan a costos competitivos."}}},{"slug":"energia-6.s3.p9","orden":9,"grupo":"energia-6.s3.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Argentina tiene recursos eólicos y solares entre los mejores del mundo.","razones":[{"id":"r1","texto":"Por el viento patagónico y el sol de la Puna"},{"id":"r2","texto":"Porque en Argentina no hay viento"},{"id":"r3","texto":"Porque el sol solo brilla en otros países"}]},"solucion":{"valor":true,"explicacion":"La Patagonia tiene vientos con factores de capacidad cercanos al 50 % y la Puna, una radiación solar de las más altas del planeta.","clave":["r1"]}},{"slug":"energia-6.s3.p10","orden":10,"grupo":"energia-6.s3.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto impulsó o frenó a las renovables en Argentina?","grupos":[{"id":"g1","nombre":"Impulsó"},{"id":"g2","nombre":"Frenó"}],"items":[{"id":"i1","texto":"Las metas de la Ley 27.191"},{"id":"i2","texto":"Líneas de transmisión saturadas"},{"id":"i3","texto":"Las licitaciones públicas de energía renovable"},{"id":"i4","texto":"Dificultades para financiar obras"},{"id":"i5","texto":"Los contratos de empresas que compran renovables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las políticas dieron el empujón; la red y el financiamiento marcan el ritmo."}},{"slug":"energia-6.s3.p11","orden":11,"grupo":"energia-6.s3.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué haría falta para que las renovables sigan creciendo en Argentina? Marcá todo.","opciones":[{"id":"o1","texto":"Nuevas líneas de alta tensión"},{"id":"o2","texto":"Almacenamiento en los nodos críticos"},{"id":"o3","texto":"Financiamiento a largo plazo"},{"id":"o4","texto":"Reglas estables para invertir"},{"id":"o5","texto":"Prohibir nuevos parques en la Patagonia"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Red, almacenamiento, financiamiento y reglas claras son la base del próximo salto."}},{"slug":"energia-6.s3.p12","orden":12,"grupo":"energia-6.s3.p12","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la demanda eléctrica cubrieron las renovables en diciembre de 2025, según datos de CAMMESA.","min":0,"max":100,"paso":0.1,"unidad":"%","escala":"lineal"},"solucion":{"valor":19.6,"banda":"lineal","explicacion":"Cerca del 19,6 %, muy cerca de la meta del 20 % de la Ley 27.191."}},{"slug":"energia-6.s3.p13","orden":13,"grupo":"energia-6.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este artículo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La Ley 27.191 fijó una meta del 20 % de renovables para 2025."},{"id":"s2","texto":"Las renovables no superaron nunca el 5 % de la demanda."},{"id":"s3","texto":"En la Patagonia hay parques con factores de capacidad cercanos al 50 %."},{"id":"s4","texto":"El principal límite para sumar renovables es la falta de viento."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos muestran un avance importante y un cuello de botella claro.","por_opcion":{"s2":"En diciembre de 2025 cubrieron cerca del 19,6 %.","s4":"El principal límite es la capacidad de transmisión."}}},{"slug":"energia-6.s3.p14","orden":14,"grupo":"energia-6.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La ley de fomento de las renovables es la Ley {{0}}; su meta era el {{1}} % del consumo para 2025; y hoy el principal límite es la {{2}}.","banco":[{"id":"w1","texto":"27.191"},{"id":"w2","texto":"20"},{"id":"w3","texto":"transmisión"},{"id":"w4","texto":"26.331"},{"id":"w5","texto":"50"},{"id":"w6","texto":"publicidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres datos clave sobre las renovables en Argentina."}}]},{"slug":"energia-6.s4","orden":4,"tipo":"leccion","titulo_es":"Pobreza energética","bajada_es":"Garrafas, leña, casas frías y facturas imposibles: la energía como derecho y sus desigualdades regionales.","minutos":11,"pasos":[{"slug":"energia-6.s4.p1","orden":1,"grupo":"energia-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la pobreza energética","cuerpo":["Un hogar está en pobreza energética cuando no puede acceder a los servicios de energía que necesita para una vida digna —calefacción, refrigeración, cocina, agua caliente, iluminación— o cuando pagarlos se lleva una parte desproporcionada de sus ingresos. No es solo falta de dinero: también influyen la calidad de la vivienda y el acceso a las redes."]},"solucion":{}},{"slug":"energia-6.s4.p2","orden":2,"grupo":"energia-6.s4.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué situaciones son señales de pobreza energética? Marcá todas.","opciones":[{"id":"o1","texto":"Pasar el invierno con la casa fría por no poder pagar la calefacción"},{"id":"o2","texto":"Gastar una parte muy grande del ingreso en garrafas"},{"id":"o3","texto":"Cocinar con leña en una casa sin ventilación"},{"id":"o4","texto":"Tener calefacción y pagar una factura razonable"},{"id":"o5","texto":"Elegir no usar aire acondicionado aunque se pueda pagar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La pobreza energética mezcla ingresos, vivienda y acceso a las redes."}},{"slug":"energia-6.s4.p3","orden":3,"grupo":"energia-6.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Red de gas y garrafa","cuerpo":["Según el Censo 2022, cerca del 38 % de la población vive en hogares sin conexión a la red de gas natural, y el 44 % usa principalmente gas en garrafa para cocinar. Las diferencias regionales son enormes: en La Pampa, Chubut y Neuquén más del 80 % de la población usa gas de red, mientras que en Formosa, Corrientes, Chaco y Misiones menos del 3 % lo hace. La garrafa suele ser más cara por unidad de energía que el gas de red, así que muchas veces los hogares con menos acceso pagan más."],"datos":{"tipo":"barras","titulo":"Población que usa principalmente gas de red para cocinar (Censo 2022)","unidad":"%","filas":[{"etiqueta":"La Pampa","valor":89.7},{"etiqueta":"Chubut","valor":86},{"etiqueta":"Neuquén","valor":83.8},{"etiqueta":"Misiones","valor":2.5},{"etiqueta":"Chaco","valor":1.2},{"etiqueta":"Formosa","valor":0.9}],"nota":"INDEC, Censo 2022, según datos publicados por Infobae."}},"solucion":{}},{"slug":"energia-6.s4.p4","orden":4,"grupo":"energia-6.s4.p4","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas provincias según el porcentaje de población que usa gas de red, de mayor a menor.","items":[{"id":"i1","texto":"La Pampa"},{"id":"i2","texto":"Neuquén"},{"id":"i3","texto":"Misiones"},{"id":"i4","texto":"Formosa"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una brecha enorme: en el noreste casi nadie tiene gas de red.","valores":{"i1":"≈ 90 %","i2":"≈ 84 %","i3":"≈ 2,5 %","i4":"≈ 1 %"}}},{"slug":"energia-6.s4.p5","orden":5,"grupo":"energia-6.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la falta de red de gas puede agravar la pobreza.","items":[{"id":"i1","texto":"Un barrio no tiene red de gas natural"},{"id":"i2","texto":"Las familias usan garrafas"},{"id":"i3","texto":"La garrafa suele costar más por unidad de energía"},{"id":"i4","texto":"Gastan una parte mayor de su ingreso en energía"},{"id":"i5","texto":"Les queda menos para otras necesidades"},{"id":"i6","texto":"La garrafa es siempre más barata que el gas de red"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Quienes tienen menos acceso a las redes a menudo pagan más por la energía."}},{"slug":"energia-6.s4.p6","orden":6,"grupo":"energia-6.s4.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene un ingreso de 600.000 pesos por mes y gasta 90.000 en energía. ¿Qué porcentaje de su ingreso es?","unidad":"%","decimales":0,"contexto":"Ingreso 600000; gasto en energía 90000."},"solucion":{"valor":15,"tolerancia":1,"explicacion":"90.000 ÷ 600.000 × 100 = 15 %. Un umbral usado a menudo para hablar de pobreza energética es el 10 % del ingreso."}},{"slug":"energia-6.s4.p6.v2","orden":6,"grupo":"energia-6.s4.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene un ingreso de 500.000 pesos por mes y gasta 60.000 en energía. ¿Qué porcentaje de su ingreso es?","unidad":"%","decimales":0,"contexto":"Ingreso 500000; gasto en energía 60000."},"solucion":{"valor":12,"tolerancia":1,"explicacion":"60.000 ÷ 500.000 × 100 = 12 %. Un umbral usado a menudo para hablar de pobreza energética es el 10 % del ingreso."}},{"slug":"energia-6.s4.p6.v3","orden":6,"grupo":"energia-6.s4.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar tiene un ingreso de 800.000 pesos por mes y gasta 64.000 en energía. ¿Qué porcentaje de su ingreso es?","unidad":"%","decimales":0,"contexto":"Ingreso 800000; gasto en energía 64000."},"solucion":{"valor":8,"tolerancia":1,"explicacion":"64.000 ÷ 800.000 × 100 = 8 %. Un umbral usado a menudo para hablar de pobreza energética es el 10 % del ingreso."}},{"slug":"energia-6.s4.p7","orden":7,"grupo":"energia-6.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La vivienda importa","cuerpo":["Una casa sin aislación, con techos de chapa y ventanas que no cierran bien pierde el calor en invierno y se recalienta en verano: necesita mucha más energía para estar confortable. Por eso, las políticas más efectivas contra la pobreza energética combinan ayudas para pagar la energía con mejoras en las viviendas: aislación de techos, burletes, ventanas, y artefactos eficientes."]},"solucion":{}},{"slug":"energia-6.s4.p8","orden":8,"grupo":"energia-6.s4.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué medida reduce de forma duradera la pobreza energética de un hogar?","opciones":[{"id":"o1","texto":"Aislar el techo y sellar las ventanas"},{"id":"o2","texto":"Regalar una garrafa por única vez"},{"id":"o3","texto":"Subir la tarifa para que se consuma menos"},{"id":"o4","texto":"Usar la cocina para calefaccionar la casa"}]},"solucion":{"clave":["o1"],"explicacion":"Mejorar la vivienda baja el consumo necesario para siempre; la ayuda puntual alivia, pero no resuelve.","por_opcion":{"o3":"Sin mejoras en la vivienda, solo empeora el problema."}}},{"slug":"energia-6.s4.p9","orden":9,"grupo":"energia-6.s4.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Usar el horno de la cocina a gas para calefaccionar una casa cerrada es seguro.","razones":[{"id":"r1","texto":"Porque puede producir monóxido de carbono"},{"id":"r2","texto":"Porque el gas no se quema en el horno"},{"id":"r3","texto":"Porque el monóxido de carbono es inofensivo"}]},"solucion":{"valor":false,"explicacion":"Puede producir monóxido de carbono, un gas invisible y mortal. Lo viste con el aire de adentro: la calefacción necesita artefactos adecuados y ventilación.","clave":["r1"]}},{"slug":"energia-6.s4.p10","orden":10,"grupo":"energia-6.s4.p10","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La medida ayuda a pagar la energía o reduce la energía necesaria?","grupos":[{"id":"g1","nombre":"Ayuda a pagar"},{"id":"g2","nombre":"Reduce la energía necesaria"}],"items":[{"id":"i1","texto":"Tarifa social"},{"id":"i2","texto":"Aislación de techos"},{"id":"i3","texto":"Subsidio a la garrafa para hogares vulnerables"},{"id":"i4","texto":"Burletes en puertas y ventanas"},{"id":"i5","texto":"Heladera eficiente"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Las dos hacen falta: alivio inmediato y mejoras que duran."}},{"slug":"energia-6.s4.p11","orden":11,"grupo":"energia-6.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En general, la garrafa cuesta más por unidad de energía que el gas de red.","razones":[{"id":"r1","texto":"Por el envase, la logística y la distribución"},{"id":"r2","texto":"Porque la garrafa tiene otro tipo de energía"},{"id":"r3","texto":"Porque el gas de red es siempre gratuito"}]},"solucion":{"valor":true,"explicacion":"Por eso, muchas veces los hogares sin red de gas —que suelen tener menos ingresos— pagan más por la misma energía.","clave":["r1"]}},{"slug":"energia-6.s4.p12","orden":12,"grupo":"energia-6.s4.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diagnóstico y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Cerca del 38 % de la población vive sin conexión a la red de gas."},{"id":"s2","texto":"En el noreste del país casi todos los hogares tienen gas de red."},{"id":"s3","texto":"La calidad de la vivienda influye en cuánta energía se necesita."},{"id":"s4","texto":"La pobreza energética depende solo del precio de la energía."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen diagnóstico mira ingresos, viviendas y redes a la vez.","por_opcion":{"s2":"En Formosa, Chaco, Corrientes y Misiones menos del 3 % lo usa.","s4":"También dependen el ingreso, la vivienda y el acceso a las redes."}}},{"slug":"energia-6.s4.p13","orden":13,"grupo":"energia-6.s4.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"No poder pagar la energía necesaria para una vida digna es pobreza {{0}}; según el Censo 2022, cerca del {{1}} % de la población no tiene red de gas; y aislar el {{2}} reduce la energía necesaria.","banco":[{"id":"w1","texto":"energética"},{"id":"w2","texto":"38"},{"id":"w3","texto":"techo"},{"id":"w4","texto":"hídrica"},{"id":"w5","texto":"8"},{"id":"w6","texto":"garaje"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de la pobreza energética en Argentina."}},{"slug":"energia-6.s4.p14","orden":14,"grupo":"energia-6.s4.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una solución.","izquierda":[{"id":"a1","texto":"Casa fría por techo de chapa"},{"id":"a2","texto":"Factura imposible de pagar"},{"id":"a3","texto":"Barrio sin red de gas"},{"id":"a4","texto":"Cocina a leña sin ventilación"}],"derecha":[{"id":"b1","texto":"Aislación del techo"},{"id":"b2","texto":"Tarifa social focalizada"},{"id":"b3","texto":"Extender la red o electrificar con bombas de calor"},{"id":"b4","texto":"Cocina eficiente y ventilación adecuada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada situación de pobreza energética pide una respuesta específica."}}]},{"slug":"energia-6.s5","orden":5,"tipo":"leccion","titulo_es":"Una transición justa y posible","bajada_es":"Eficiencia, electrificación, renovables con red, metano bajo control y nadie afuera: una hoja de ruta.","minutos":11,"pasos":[{"slug":"energia-6.s5.p1","orden":1,"grupo":"energia-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero, la eficiencia","cuerpo":["La energía más limpia y barata es la que no se necesita. Mejorar la eficiencia de viviendas, industrias, alumbrado y transporte reduce emisiones, baja facturas y hace más fácil todo lo demás, porque cada unidad de energía limpia rinde más. Por eso muchas hojas de ruta empiezan por la eficiencia: normas para edificios nuevos, etiquetado de artefactos, programas de recambio y aislación."]},"solucion":{}},{"slug":"energia-6.s5.p2","orden":2,"grupo":"energia-6.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas de eficiencia reducen el consumo de energía? Marcá todas.","opciones":[{"id":"o1","texto":"Normas de aislación para edificios nuevos"},{"id":"o2","texto":"Etiquetado de eficiencia en artefactos"},{"id":"o3","texto":"Alumbrado público LED"},{"id":"o4","texto":"Motores eficientes en las industrias"},{"id":"o5","texto":"Subsidiar sin límite el consumo de energía"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La eficiencia es la base: hace más baratas todas las demás medidas."}},{"slug":"energia-6.s5.p3","orden":3,"grupo":"energia-6.s5.p3","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué muchas hojas de ruta energéticas empiezan por la eficiencia?","opciones":[{"id":"o1","texto":"Abarata y facilita todas las demás medidas"},{"id":"o2","texto":"Porque es la única medida que reduce emisiones"},{"id":"o3","texto":"Porque no requiere ninguna inversión"},{"id":"o4","texto":"Porque así se evita sumar renovables"}]},"solucion":{"clave":["o1"],"explicacion":"Cada unidad de energía que no se necesita es una que no hay que generar, transportar ni pagar.","por_opcion":{"o3":"Requiere inversión, pero suele recuperarse rápido con el ahorro."}}},{"slug":"energia-6.s5.p4","orden":4,"grupo":"energia-6.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una hoja de ruta","cuerpo":["Una transición energética posible en Argentina combinaría varias líneas a la vez: eficiencia; renovables con las líneas y el almacenamiento que necesitan; electrificación del transporte y de la calefacción donde sea conveniente; control estricto del metano en la producción de gas mientras se lo siga usando; y reglas estables que permitan financiar obras de largo plazo. Todo eso con metas medibles y revisión periódica."]},"solucion":{}},{"slug":"energia-6.s5.p5","orden":5,"grupo":"energia-6.s5.p5","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená una hoja de ruta por etapas para la energía de una provincia.","items":[{"id":"i1","texto":"Diagnosticar consumos, emisiones y hogares vulnerables"},{"id":"i2","texto":"Lanzar programas de eficiencia y tarifa social focalizada"},{"id":"i3","texto":"Sumar renovables con líneas y almacenamiento"},{"id":"i4","texto":"Electrificar transporte público y calefacción donde convenga"},{"id":"i5","texto":"Medir resultados y ajustar metas cada año"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Diagnóstico, medidas rápidas, infraestructura, electrificación y evaluación continua."}},{"slug":"energia-6.s5.p6","orden":6,"grupo":"energia-6.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transición justa","cuerpo":["Una transición energética cambia economías enteras. Provincias como Neuquén dependen mucho de las regalías del petróleo y el gas, y miles de personas trabajan en esa industria. Una transición justa planifica con tiempo: diversifica las economías regionales, capacita a trabajadores para nuevos empleos, usa parte de los ingresos actuales para preparar el futuro y protege a los hogares vulnerables de subas bruscas."]},"solucion":{}},{"slug":"energia-6.s5.p7","orden":7,"grupo":"energia-6.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida hace más justa la transición o la hace más injusta?","grupos":[{"id":"g1","nombre":"Más justa"},{"id":"g2","nombre":"Más injusta"}],"items":[{"id":"i1","texto":"Capacitar a trabajadores del petróleo para nuevos empleos"},{"id":"i2","texto":"Quitar subsidios de golpe sin ninguna ayuda"},{"id":"i3","texto":"Ahorrar parte de las regalías en un fondo para el futuro"},{"id":"i4","texto":"Cerrar actividades sin plan para los trabajadores"},{"id":"i5","texto":"Tarifa social para hogares vulnerables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"La transición es más rápida y estable cuando nadie queda afuera."}},{"slug":"energia-6.s5.p8","orden":8,"grupo":"energia-6.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una provincia recibe 1.000 millones de dólares de regalías por año y decide ahorrar el 10 % en un fondo para diversificar su economía. ¿Cuántos millones ahorra en 10 años, sin contar intereses?","unidad":"millones de dólares","decimales":0,"contexto":"1000 millones por año; ahorro del 10 %; 10 años."},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"1.000 × 10 % = 100 por año; × 10 = 1.000 millones. Un recurso para preparar el futuro cuando los ingresos fósiles bajen. Cifras de ejemplo."}},{"slug":"energia-6.s5.p8.v2","orden":8,"grupo":"energia-6.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una provincia recibe 800 millones de dólares de regalías por año y decide ahorrar el 15 % en un fondo para diversificar su economía. ¿Cuántos millones ahorra en 10 años, sin contar intereses?","unidad":"millones de dólares","decimales":0,"contexto":"800 millones por año; ahorro del 15 %; 10 años."},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"800 × 15 % = 120 por año; × 10 = 1.200 millones. Un recurso para preparar el futuro cuando los ingresos fósiles bajen. Cifras de ejemplo."}},{"slug":"energia-6.s5.p8.v3","orden":8,"grupo":"energia-6.s5.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una provincia recibe 1.500 millones de dólares de regalías por año y decide ahorrar el 5 % en un fondo para diversificar su economía. ¿Cuántos millones ahorra en 10 años, sin contar intereses?","unidad":"millones de dólares","decimales":0,"contexto":"1500 millones por año; ahorro del 5 %; 10 años."},"solucion":{"valor":750,"tolerancia":15,"explicacion":"1.500 × 