10,"pasos":[{"slug":"energia-6.s7.p1","orden":1,"grupo":"energia-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La situación","cuerpo":["La provincia tiene 1,2 millones de habitantes. Menos del 3 % usa gas de red: la mayoría cocina con garrafa y muchas familias pasan frío en invierno o calor extremo en verano. Tiene mucho sol y un río con potencial para pequeños aprovechamientos. Su red eléctrica se corta en los picos de verano. El gobierno tiene presupuesto limitado y dos propuestas: extender la red de gas a toda la provincia, o combinar paneles solares, aislación de viviendas, bombas de calor eléctricas y refuerzos de la red eléctrica."]},"solucion":{}},{"slug":"energia-6.s7.p2","orden":2,"grupo":"energia-6.s7.p2","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ventajas tiene la segunda propuesta en esta provincia? Marcá todas.","opciones":[{"id":"o1","texto":"Aprovecha el sol abundante"},{"id":"o2","texto":"Mejora el confort en invierno y en verano"},{"id":"o3","texto":"No ata a la provincia a nueva infraestructura fósil"},{"id":"o4","texto":"La aislación reduce la energía necesaria para siempre"},{"id":"o5","texto":"No necesita reforzar la red eléctrica"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Electrificar con sol y eficiencia puede ser una ruta directa para una provincia sin red de gas, pero exige reforzar la red eléctrica."}},{"slug":"energia-6.s7.p3","orden":3,"grupo":"energia-6.s7.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si 1,2 millones de habitantes viven en hogares de 3 personas en promedio, ¿cuántos hogares hay?","unidad":"hogares","decimales":0,"contexto":"1,2 millones de habitantes; 3 personas por hogar."},"solucion":{"valor":400000,"tolerancia":8000,"explicacion":"1.200.000 ÷ 3 = 400.000 hogares. Un programa de aislación que llegue a 40.000 hogares por año cubriría todos en 10 años."}},{"slug":"energia-6.s7.p4","orden":4,"grupo":"energia-6.s7.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un programa aísla 40.000 hogares por año, ¿en cuántos años llega a los 400.000?","unidad":"años","decimales":0,"contexto":"400.000 hogares; 40.000 por año."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"400.000 ÷ 40.000 = 10 años: exactamente el horizonte del plan."}},{"slug":"energia-6.s7.p5","orden":5,"grupo":"energia-6.s7.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las primeras medidas por prioridad.","items":[{"id":"i1","texto":"Tarifa social y aislación para los hogares más vulnerables"},{"id":"i2","texto":"Refuerzo de la red eléctrica en los barrios que se cortan"},{"id":"i3","texto":"Paneles solares en edificios públicos y viviendas"},{"id":"i4","texto":"Estudios para pequeños aprovechamientos del río"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero proteger a los más vulnerables y evitar cortes; después, sumar generación local y estudiar nuevas fuentes.","valores":{"i1":"alivio y mejora duradera","i2":"evita cortes en los picos","i3":"energía local limpia","i4":"a mediano plazo"}}},{"slug":"energia-6.s7.p6","orden":6,"grupo":"energia-6.s7.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene reforzar la red eléctrica antes de promover bombas de calor en masa?","opciones":[{"id":"o1","texto":"Porque aumentaría la demanda y podría haber más cortes"},{"id":"o2","texto":"Porque las bombas de calor no usan electricidad"},{"id":"o3","texto":"Porque la red eléctrica funciona mejor sobrecargada"},{"id":"o4","texto":"Porque la ley lo prohíbe"}]},"solucion":{"clave":["o1"],"explicacion":"Electrificar sin preparar la red puede agravar los cortes: las dos cosas van juntas.","por_opcion":{"o3":"Una red sobrecargada se corta más."}}},{"slug":"energia-6.s7.p7","orden":7,"grupo":"energia-6.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Extender la red de gas es la única forma de que una provincia sin gas mejore su acceso a la energía.","razones":[{"id":"r1","texto":"Porque electrificar con renovables y eficiencia es otra ruta"},{"id":"r2","texto":"Porque la electricidad no sirve para calefaccionar"},{"id":"r3","texto":"Porque el gas es la única energía posible"}]},"solucion":{"valor":false,"explicacion":"También es posible electrificar con renovables y eficiencia. Cuál conviene depende de costos, recursos, tiempos y objetivos climáticos: hay que comparar las opciones con datos.","clave":["r1"]}},{"slug":"energia-6.s7.p8","orden":8,"grupo":"energia-6.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El gobierno provincial redacta el plan. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"Priorizaremos a los hogares más vulnerables en la aislación."},{"id":"s2","texto":"Promoveremos bombas de calor sin reforzar la red."},{"id":"s3","texto":"Mediremos cada año el gasto en energía de los hogares."},{"id":"s4","texto":"No haremos consultas: el plan es técnico."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan energético es técnico y también social.","por_opcion":{"s2":"Aumentaría los cortes: la red debe reforzarse a la par.","s4":"La participación mejora el diseño y la aceptación del plan."}}}]}]}$ac$::jsonb);
